\[ 
\Psi_\mathbb{O}(A, B)= \sum_{\mathcal{S} \subseteq \mathbb{O} \setminus \{A \cup B\}} \frac{1}{(|\mathcal{S}|+1) {{|\mathbb{O}|-1} \choose {|\mathcal{S}|+1}}} (U(\mathcal{S}\cup \{A\})-U(\mathcal{S}\cup \{B\}))
\]
