    Check $d=\psi_\mathbb{O'}(A \setminus \Delta A) - \psi_\mathbb{O'}(B \cup \Delta A)$ using Monte Carlo;\\
    \If{$d<0$}
    {
        \Return $\Delta A$
    }
    }
  }
\caption{The Size-Ascending Exact Algorithm \label{algo:sizeascending}}
\end{algorithm}


