\section{Heuristic Approximation Methods}\label{sec:methods}

Computing the exact answer to the counterfactual explanation problem is costly and does not scale up for the scenarios where there are many data owners.  Thus, in this section we explore heuristic methods in two ways.

Firstly, we approximate the difference between the Shapley values of two data owners through Monte Carlo sampling. Secondly, we explore how to estimate Shapley value changes when we move some data entries from one data owner to the other and then greedily search for a counterfactual explanation.  

\subsection{Estimating Differential Shapley Value}\label{sec:mc-baseline}

A straightforward approach to estimate the difference between the Shapley values of two data owners is to first estimate the individual Shapley values and then infer the difference. This approach has two drawbacks. Firstly, we need to draw samples to estimate the two individual Shapley values, and each has independent estimation error. Secondly, the estimation of the difference using the estimated individual Shapley values introduces a new estimation error. Can we reduce the estimation error and improve efficiency by estimating the difference directly?

According to Theorem~\ref{thm:differential}, the differential Shapley value between two data owners depends only on the difference between the marginal utility $U(\mathcal{S} \cup \{A\})$ and $U(\mathcal{S} \cup \{B\})$ on all coalitions $\mathcal{S}$ in which neither $A$ nor $B$ participates. This insight can be used in estimating the differential Shapley value directly using Monte Carlo approximation.

\begin{corollary}[Differential Shapley Value by Permutation]\label{cor:mc-baseline}
For two data owners $A, B \in \mathbb{O}$,
\[
\begin{split}
%& \psi_\mathbb{O}(A) - \psi_\mathbb{O}(B)\\
\Psi_\mathbb{O}(A, B) =& \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})\\
&-U(P^\pi_{\{A, B\}} \cup \{B\}))
\end{split}
\]
where 
%$\Pi(\mathbb{O})$ is the set of all possible permutations of data owners except for $A$ and $B$, and 
$P^\pi_{\{A, B\}}$ is the set of data owners preceding $A$ and $B$ in permutation $\pi$.
\proof
For each subset of data owners $\mathcal{S} \subseteq \mathbb{O} \setminus \{A, B\}$, there are 
$|\mathcal{S}|! \times 2 \times (|\mathbb{O} \setminus \mathcal{S}|-1)!=2|\mathcal{S}|!(|\mathbb{O}|-|\mathcal{S}|-1)!
$
permutations $\pi$ in $\Pi(\mathbb{O})$ such that $P^\pi_{\{A, B\}}=\mathcal{S}$.  Following Theorem~\ref{thm:differential}, we have  
\[
\begin{split}
%& \psi_\mathbb{O}(A) - \psi_\mathbb{O}(B)\\
\Psi_\mathbb{O}(A, B)=& \sum_{\mathcal{S} \subseteq \mathbb{O} \setminus \{A \cup B\}} \frac{1}{(|\mathcal{S}|+1) {{|\mathbb{O}|-1} \choose {|\mathcal{S}|+1}}} (U(\mathcal{S}\cup \{A\})-U(\mathcal{S}\cup \{B\}))\\
=& \sum_{\pi \in \Pi(\mathbb{O})} \frac{1}{(|P^\pi_{\{A, B\}}|+1) {{|\mathbb{O}|-1} \choose {|P^\pi_{\{A, B\}}|+1}}}\\
& \times \frac{(U(P^\pi_{\{A, B\}} \cup \{A\})-U(P^\pi_{\{A, B\}} \cup \{B\}))}{2|P^\pi_{\{A, B\}}|!(|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1)!}\\
=& \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})\\
&-U(P^\pi_{\{A, B\}} \cup \{B\})) \qed
\end{split}
\]
\end{corollary}

The corollary immediately leads to a Monte Carlo estimator, which takes a uniform sample of permutations $X \subseteq \Pi(\mathbb{O})$ to estimate the differential Shapley value $\Psi_{\mathbb{O}}(A,B)$. We can show that this estimation is unbiased.

\begin{corollary}[Unbiased Estimate]\label{cor:diff-est}
For a uniform sample of permutations $X \subseteq \Pi(\mathbb{O})$,
\[
\begin{split}
%& \widehat{\psi_\mathbb{O}(A) - \psi_\mathbb{O}(B)}\\
& \Delta \psi_{\mathbb{O}}^{A-B}\\
=& \frac{|\mathbb{O}|}{2|X|}\sum_{\pi \in X} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})-U(P^\pi_{\{A, B\}} \cup \{B\}))
\end{split}
\]
is an unbiased estimate of $\Psi_\mathbb{O}(A,B)$.
\proof
By linearity of expectation and uniformity of samples,
\[
\begin{split}
& \mathbb{E}[\Delta \psi_{\mathbb{O}}^{A-B}]\\
=& \mathbb{E}[\frac{|\mathbb{O}|}{2|X|}\sum_{\pi \in X} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})\\
&-U(P^\pi_{\{A, B\}} \cup \{B\}))]\\
% =& \frac{|\mathbb{O}|}{2|X|}\mathbb{E}[\sum_{\pi \in X} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})\\
% &-U(P^\pi_{\{A, B\}} \cup \{B\}))]\\
=& \frac{|\mathbb{O}|}{2|X|}|X| \times \mathbb{E}[\frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})\\
&-U(P^\pi_{\{A, B\}} \cup \{B\}))]\\
=& \frac{|\mathbb{O}|}{2}\sum_{\pi \in \Pi(\mathbb{O})} \frac{1}{|\mathbb{O}|!} \times (\frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})\\
&-U(P^\pi_{\{A, B\}} \cup \{B\})))\\
=& \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}(U(P^\pi_{\{A, B\}} \cup \{A\})\\
&-U(P^\pi_{\{A, B\}} \cup \{B\})) \\
=& \Psi_\mathbb{O}(A, B)\qed
\end{split}
\]
\end{corollary}

Using Corollary~\ref{cor:diff-est} in Algorithm~\ref{algo:bruteforce}, we can obtain a Monte Carlo baseline algorithm for the counterfactual explanation problem.  The pseudo-code is given in Algorithm~\ref{algo:mc-baseline}.

\begin{algorithm}[t]
\DontPrintSemicolon
%\setstretch{1.3}
\SetAlgoLined
\KwInput{the same as Algorithm~\ref{algo:bruteforce}
  }
\KwOutput{An approximation to solution to Equation~\ref{eq:problem}}
\For{$i=1$ \textbf{\em to} $|A|-1$}{
    \For {$\Delta A \subset A$ s.t. $|\Delta A|=i$}{
    Let $\mathbb{O'}= \mathbb{O}\setminus \{A, B\} \cup \{A \setminus \Delta A, B \cup \Delta A\}$;\\
    Estimate $\Delta \psi_{\mathbb{O'}}^{A \setminus \Delta A-B \cup \Delta A}$ as an unbiased estimate of $\Psi_\mathbb{O'}(A \setminus \Delta A, B \cup \Delta A)$ using Monte Carlo based on Corollary~\ref{cor:diff-est}\\
    \If{$\Delta \psi_{\mathbb{O'}}^{A \setminus \Delta A-B \cup \Delta A} < 0$}
    {
       \Return{$\Delta A$
    }
  }
}
}
\Return{A}
\caption{The Monte Carlo Baseline Algorithm \label{algo:mc-baseline}}
\end{algorithm}

\subsection{A Greedy Approach: the Framework}\label{sec:greedy}

The Monte Carlo baseline algorithm (Algorithm~\ref{algo:mc-baseline}) still needs to search across many subsets of the data sets in ascending order and thus needs to use Monte Carlo estimation many times. 
\nop{For example, if data owner $A$ owns 100 data entries and  the counterfactual explanation has 10 entries, the Monte Carlo baseline algorithm has to try out at least \re{$\sum_{i=1}^{9}{100 \choose i}+1>1.9 \times 10^{12}$ subsets of $A$}. In general, Algorithm~\ref{algo:mc-baseline} has to check \re{$\sum_{i=1}^{|\Delta A|-1}{|A| \choose {|\Delta A|-1}}+1$ subsets of $A$}, where $|\Delta A|$ is the \re{size of the} minimal explanation found, which is at least as large as the true counterfactual explanation.}

To tackle the computational cost, we explore a greedy approach. We iteratively identify the best data entry owned by data owner $A$ such that, if moved to $B$, reduces the difference of the Shapley values between $A$ and $B$ most. As the goal is to bring down the differential Shapley $\Psi_\mathbb{O}(A, B)$ from Theorem \ref{thm:differential} to a  negative value as quickly as possible, we move these ``powerful'' data entries one by one from $A$ to $B$ until $\Psi_\mathbb{O}(A, B)<0$.

Specifically, 
%in the counterfactual explanation problem of Shapley value, where there are two data owners $A, B \in \mathbb{O}$ such that $\psi_\mathbb{O}(A)>\psi_\mathbb{O}(B)$, 
for a data entry $x \in A$, the change of the differential Shapley value caused by moving $x$ from $A$ to $B$ is 
\begin{equation}\label{eq:x-diff}
\begin{split}
\Lambda_\mathbb{O}^{A \xrightarrow{x} B}=& \Psi_\mathbb{O}(A, B)-\Psi_\mathbb{O'}(A \setminus \{x\}, B \cup \{x\})\\
=&[\psi_{\mathbb{O}}(A)-\psi_{\mathbb{O}}(B)]-
[\psi_{\mathbb{O}'}(A \setminus \{x\})-\psi_{\mathbb{O}'}(B \cup \{x\})],
\end{split}
\end{equation}
where $\mathbb{O}'=\mathbb{O}[A\xrightarrow{\{x\}}B]$.
The larger the value of $\Lambda_\mathbb{O}^{A \xrightarrow{x} B}$, the more significant the change for counterfactual explanation.
%Hereafter, for the sake of brevity, we often write $\mathbb{O}[A\xrightarrow{\{x\}}B]$ as $\mathbb{O}[A\xrightarrow{x}B]$ by omitting the set parentheses of a set with single item when there is no ambiguity from context.  

Given data owners $A$ and $B$, $\Psi_{\mathbb{O}}(A, B)$ in Equation~\ref{eq:x-diff} is a constant.  Thus, we define the \textbf{power} of $x$ with respect to $A$ and $B$, denoted by $power^{\mathbb{O}}_{A\rightarrow B}(x)$, as the change of the differential Shapley value when $x$ is moved from $A$ to $B$, that is, 
\[
power^{\mathbb{O}}_{A\rightarrow B}(x)=\psi_{\mathbb{O}'}(B \cup \{x\})-\psi_{\mathbb{O}'}(A \setminus \{x\})
\]
Heuristically, the larger the power of a data entry, the more the data entry contributes to a counterfactual explanation of the Shapley values.

The framework of our greedy approach works as follows. We find the data entry $x$ that has the largest power and move it from $A$ to $B$.  If the Shapley value of $B$ becomes larger than that of $A$ after the move, that is, 
$\psi_{\mathbb{O}'}(A \setminus \{x\})<\psi_{\mathbb{O}'}(B \cup \{x\})$ and thus
$power^{\mathbb{O}}_{A\rightarrow B}(x)>0$, then $x$ is a counterfactual explanation. If not, then we iteratively find the next entry with the largest power, append this entry to the set containing the previously computed best entries, and conduct the move.  The iteration continues until the Shapley value of $B$ becomes larger than that of $A$ after the moves.  The set of all entries moved form a greedy approximation of the counterfactual explanation.

\subsection{Computing the Power of a Data Entry}

%\todo{Reviewer 2 says math is difficult to read, needs more text and less equations.}

In our greedy approach, the key operation that is performed again and again is computing the power of a data entry. Now, let us consider how to compute the power of a data entry efficiently.  

First of all, if data owner $A$ has only one data entry, that is, $A=\{x\}$, then after moving $x$ to $B$, $A$ becomes empty and thus the Shapley value is $0$.  $x$ is the trivial counterfactual explanation.  Thus, in the rest of the discussion, we assume $|A| >1$.

A data entry $x \in A$ must be in one of the two cases, $x \in A \cap B$ and $x \in A \setminus B$.  We consider the two situations one by one.

\subsubsection{The power of a Common Data Entry}

Suppose $x \in A \cap B$, that is, $x$ is a \textbf{common data entry} to $A$ and $B$.  If we move $x$ from $A$ to $B$, what change would happen to the Shapley values of the two data owners?

\nop{
According to the definition, we have
\[
power^{\mathbb{O}}_{A\rightarrow B}(x) =\psi_{\mathbb{O}'}(B \cup \{x\})-\psi_{\mathbb{O}'}(A \setminus \{x\})
\]
where $\mathbb{O}'=\mathbb{O}[A\xrightarrow{\{x\}}B]$.}  
Since $x \in A \cap B \subseteq B$, $B \cup \{x\}=B$.  Thus, using Theorem~\ref{thm:differential}, we have
\begin{equation}\label{eq:temp1}
%\begin{split}
power^{\mathbb{O}}_{A\rightarrow B}(x) =
%\psi_{\mathbb{O}'}(B)-\psi_{\mathbb{O}'}(A \setminus \{x\})\\
\sum_{\mathcal{S} \subseteq \mathbb{O}'\setminus\{B, A\setminus\{x\}\}}\frac{U(\mathcal{S}\cup\{B\})-U(\mathcal{S}\cup\{A\setminus\{x\}\}}{(|\mathcal{S}|+1){{|\mathbb{O}'|-1}\choose{|\mathcal{S}|+1}}}
%\end{split}
\end{equation}

Since $|A|>1$, $A\setminus\{x\} \neq \emptyset$, moving a data entry $x$ from $A$ to $B$ does not make $A$ empty. Thus, the number of non-empty data owners remains the same after the moving, that is$,|\mathbb{O}|=|\mathbb{O}'|$. Moreover, for every coalition $\mathcal{S} \subseteq \mathbb{O}\setminus\{A, B\}$, there exists a unique coalition $\mathcal{S}' \subseteq \mathbb{O}'\setminus\{A\setminus\{x\}, B\}$ such that $\mathcal{S}=\mathcal{S}'$, and vice versa. Based on these two observations, Equation~\ref{eq:temp1} can be further rewritten to
\begin{equation}\label{eq:temp2}
\begin{split}
& power^{\mathbb{O}}_{A\rightarrow B}(x)\\
%=& \sum_{\mathcal{S} \subseteq \mathbb{O}\setminus\{B, A\setminus\{x\}\}}\frac{U(\mathcal{S}\cup\{B\})-U(\mathcal{S}\cup\{A\setminus\{x\}\}}{(|\mathcal{S}|+1){{|\mathbb{O}|-1}\choose{|\mathcal{S}|+1}}}\\
=& \sum_{\mathcal{S} \subseteq \mathbb{O}\setminus\{B, A\setminus\{x\}\}}\frac{U(\mathcal{S}\cup\{B\})}{(|\mathcal{S}|+1){{|\mathbb{O}|-1}\choose{|\mathcal{S}|+1}}}-\sum_{\mathcal{S} \subseteq \mathbb{O}\setminus\{B, A\setminus\{x\}\}}\frac{U(\mathcal{S}\cup\{A\setminus\{x\}\}}{(|\mathcal{S}|+1){{|\mathbb{O}|-1}\choose{|\mathcal{S}|+1}}}
\end{split}
\end{equation}

\nop{
The first term in Equation~\ref{eq:temp2} is constant for any $x \in A \cap B$.  Thus, we have 
\begin{equation}\label{eq:temp5}
power^{\mathbb{O}}_{A\rightarrow B}(x) = -\sum_{\mathcal{S} \subseteq \mathbb{O}\setminus\{B, A\setminus\{x\}\}}\frac{U(\mathcal{S}\cup\{A\setminus\{x\}\}}{(|\mathcal{S}|+1){{|\mathbb{O}|-1}\choose{|\mathcal{S}|+1}}}
\end{equation}
}

To enable Monte Carlo approximation, using Corollary~\ref{cor:mc-baseline}, we have:
\begin{equation}\label{eq:temp6}
\begin{split}
& power^{\mathbb{O}}_{A\rightarrow B}(x) = \psi_{\mathbb{O}'}(B \cup \{x\})-\psi_{\mathbb{O}'}(A \setminus \{x\})\\
=& \psi_{\mathbb{O}'}(B)-\psi_{\mathbb{O}'}(A \setminus \{x\})\\
=& \frac{1}{2(|\mathbb{O}'|-1)!}\sum_{\pi \in \Pi(\mathbb{O}')} \frac{1}{|\mathbb{O}'|-|P^\pi_{\{A\setminus \{x\}, B\}}|-1}\Big (U(P^\pi_{\{A\setminus \{x\}, B\}} \cup \{B\})\\
& -U(P^\pi_{\{A\setminus \{x\}, B\}} \cup \{A\setminus \{x\}\}\Big )\\
\end{split}
\end{equation}
Notice that, for any permutation $\pi' \in \Pi(\mathbb{O}')$, there exists a unique permutation $\pi \in \Pi(\mathbb{O})$ such that $P^{\pi'}_{\{A\setminus \{x\}, B\}}=P^{\pi}_{\{A, B\}}$ and vice versa. Thus, Equation~\ref{eq:temp6} can be further rewritten to
\begin{equation}\label{eq:temp7}
\begin{split}
& power^{\mathbb{O}}_{A\rightarrow B}(x) \\
=& \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{U(P^\pi_{\{A, B\}} \cup \{B\})-U(P^\pi_{\{A, B\}} \cup \{A\setminus \{x\}\}}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}\\
% =&  \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{U(P^\pi_{\{A, B\}} \cup \{B\})}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}\\
% & -  \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{U(P^\pi_{\{A, B\}} \cup \{A\setminus \{x\}\}}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}\\
\end{split}
\end{equation}

\nop{
The first term in Equation~\ref{eq:temp7} is constant for any $x \in A \cap B$.  Thus, we have 
\begin{equation}\label{eq:temp8}
power^{\mathbb{O}}_{A\rightarrow B}(x) \sim -  \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{U(P^\pi_{\{A, B\}} \cup \{A\setminus \{x\}\}}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}
\end{equation}


Equations~\ref{eq:temp5} and~\ref{eq:temp8} are intuitively understandable. Since $x \in A \cap B$, removing $x$ from $A$ reduces the contributions of $A$ to coalitions but does not improve those of $B$.  Therefore, the power of $x$ with respect to $A$ and $B$ depends only on how much removing $x$ from $A$ reduces the contributions of $A$ to coalitions.
}

Based on Corollary~\ref{cor:diff-est} and Equation~\ref{eq:temp7}, we have the following Monte Carlo estimation.

\begin{theorem}[MC-Common Entry]\label{thm:mc-common}
For $x \in A \cap B$ and a uniform sample of permutations $X \subseteq \Pi(\mathbb{O})$,
\[
\widehat{power^{\mathbb{O}}_{A\rightarrow B}(x)}=
\frac{|\mathbb{O}|}{2|X|}\sum_{\pi \in X} \frac{U(P^\pi_{\{A, B\}} \cup \{B\})-U(P^\pi_{\{A, B\}} \cup \{A\setminus \{x\}\}}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1}
\]
is an unbiased estimation of $power^{\mathbb{O}}_{A\rightarrow B}(x)$.
\qed
\end{theorem}

\subsubsection{The power of a Differential Data Entry}

Suppose $x \in A \setminus B$, that is, $x$ is a data entry that $A$ has but $B$ does not.  In such a case, we call $x$ a \textbf{differential data entry}. Moving $x$ from $A$ to $B$ may not only reduce the contributions from $A$ to coalitions but may also improve those from $B$. Using the exact same logic and theorems as above, we get the following Monte Carlo estimation:

\nop{
Still, using Theorem~\ref{thm:differential}, we have
\begin{equation}\label{eq:temp9}
\begin{split}
& power^{\mathbb{O}}_{A\rightarrow B}(x)\\
=&\sum_{\mathcal{S} \subseteq \mathbb{O}'\setminus\{B\cup\{x\}, A\setminus\{x\}\}}\frac{U(\mathcal{S}\cup\{B \cup \{x\}\})-U(\mathcal{S}\cup\{A\setminus\{x\}\}}{(|\mathcal{S}|+1){{|\mathbb{O}'|-1}\choose{|\mathcal{S}|+1}}}\\
\end{split}
\end{equation}
where $\mathbb{O}'=\mathbb{O}[A\xrightarrow{\{x\}}B]$.

Similarly to the case of common data entries (Equation~\ref{eq:temp2}), since $|A|>1$, $A\setminus\{x\} \neq \emptyset$.  Thus, $|\mathbb{O}|=|\mathbb{O}'|$. Moreover, for every $\mathcal{S} \subseteq \mathbb{O}\setminus\{A, B\}$ there exists a unique $\mathcal{S}' \subseteq \mathbb{O}'\setminus\{A\setminus\{x\}, B\cup\{x\}\}$ such that $\mathcal{S}=\mathcal{S}'$, and vice versa. Like before, Equation~\ref{eq:temp9} can be further rewritten as
\begin{equation}\label{eq:temp10}
\begin{split}
& power^{\mathbb{O}}_{A\rightarrow B}(x)\\
=&\sum_{\mathcal{S} \subseteq \mathbb{O}\setminus\{B\cup\{x\}, A\setminus\{x\}\}}\frac{U(\mathcal{S}\cup\{B \cup \{x\}\})-U(\mathcal{S}\cup\{A\setminus\{x\}\}}{(|\mathcal{S}|+1){{|\mathbb{O}|-1}\choose{|\mathcal{S}|+1}}}\\
\end{split}
\end{equation}

Using Corollary~\ref{cor:mc-baseline}, we have 
\begin{equation}\label{eq:temp11}
\begin{split}
power^{\mathbb{O}}_{A\rightarrow B}(x) =& \psi_{\mathbb{O}'}(B \cup \{x\})-\psi_{\mathbb{O}'}(A \setminus \{x\})\\
=& \frac{1}{2(|\mathbb{O}'|-1)!}\sum_{\pi \in \Pi(\mathbb{O}')} \frac{1}{|\mathbb{O}'|-|P^\pi_{\{A\setminus \{x\}, B\cup\{x\}\}}|-1} \\
& \cdot \Big (U(P^\pi_{\{A\setminus \{x\}, B\cup \{x\}\}} \cup \{B\cup\{x\}\})\\
& -U(P^\pi_{\{A\setminus \{x\}, B\cup\{x\}\}} \cup \{A\setminus \{x\}\})\Big )\\
\end{split}
\end{equation}

\re{Again,} for any permutation $\pi' \in \Pi(\mathbb{O}')$, there exists a unique permutation $\pi \in \Pi(\mathbb{O})$ such that $P^{\pi'}_{\{A\setminus \{x\}, B\cup\{x\}\}}=P^{\pi}_{\{A, B\}}$ and vice versa. \re{We rewrite} Equation~\ref{eq:temp11} as
\begin{equation}\label{eq:temp12}
\begin{split}
power^{\mathbb{O}}_{A\rightarrow B}(x) =&  \frac{1}{2(|\mathbb{O}|-1)!}\sum_{\pi \in \Pi(\mathbb{O})} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1} \\
& \cdot \Big (U(P^\pi_{\{A, B\}} \cup \{B\cup\{x\}\})-U(P^\pi_{\{A, B\}} \cup \{A\setminus \{x\}\})\Big )\\
\end{split}
\end{equation}

Based on Corollary~\ref{cor:diff-est} and Equation~\ref{eq:temp12}, we have the following Monte Carlo estimation.}

\begin{theorem}[MC-Differential Item]\label{thm:mc-diff}
For $x \in A \setminus B$ and a uniform sample of permutations $X \subseteq \Pi(\mathbb{O})$,
\[
\begin{split}
\widehat{power^{\mathbb{O}}_{A\rightarrow B}(x)} =&  \frac{|\mathbb{O}|}{2|X|}\sum_{\pi \in X} \frac{1}{|\mathbb{O}|-|P^\pi_{\{A, B\}}|-1} \\
& \cdot \Big (U(P^\pi_{\{A, B\}} \cup \{B\cup\{x\}\})-U(P^\pi_{\{A, B\}} \cup \{A\setminus \{x\}\})\Big )\\
\end{split}
\]
is an unbiased estimation of $power^{\mathbb{O}}_{A\rightarrow B}(x)$.
\qed
