\section{Preliminaries} \label{sec-pre}

In this paper, we use standard notions of a deterministic and nondeterministic Turing machine. Below we give definitions of function and language classes that we will consider:

\begin{definition}
	\begin{enumerate}
		\item  \textnormal{\cite{val79}} $\sp = \{acc_{M} \ | \ M$ is a NPTM$\}$, where $acc_{M}(x)$ is the number of accepting paths of $M$ on input $x \in \Sigma^{*}$.		
		\item \textnormal{\cite{fen94}} $\gapp = \{gap_{M} \ | \ M$ is a NPTM$\}$, where $gap_{M}(x) = acc_{M}(x) - rej_{M}(x)$ and $rej_{M}(x)$ is the number of rejecting paths of $M$ on input $x \in \Sigma^{*}$.
		\item \textnormal{\cite{kia01}} $\totp = \{tot_{M} \ | \ M$ is a NPTM$\}$, where $tot_{M}(x) = Total_{M}(x) - 1$ and $Total_{M}(x)$ is the number of all paths of $M$ on input $x \in \Sigma^{*}$.%\footnote{The "-1" in the definition of $\totp$ allows these functions to take a zero value. A certificate-based definition of $\totp$ is given in \cite{}.}
		\footnote{The "-1" in the definition of $\totp$ allows these functions to take a zero value. A second definition of $\totp$ in terms of certificates and verifiers is given in \cite{iva25}.}		
		\item \textnormal{\cite{kob89}} $\spanp = \{span_{M} \ | \ M$ is a NPTM$\}$, where $span_{M}(x)$ is the number of distinct outputs on accepting paths of $M$ on input $x \in \Sigma^{*}$.		
		\item $\fp = \{f: \Sigma^{*} \rightarrow \mathbb{Z} \ | \ f$ is computable in polynomial time$\}$.		
		%\item $\fpl = \{f \ | \ f \in \fp$ and $f \geqslant 0\}$.
	\end{enumerate}
\end{definition}

$\fpl$ and $\gappl$ are the subsets of $\fp$ and $\gapp$ respectively, that contain only non-negative valued functions. %of the form $\Sigma^{*} \rightarrow \mathbb{Z}_{\geqslant 0}$.

\begin{definition}
	\begin{enumerate}
		\item The class $\np$ consists of all languages $L$ for which there exists a function $f \in \sp$ such that for any $x \in \Sigma^{*}$: 
		\begin{align*}
			x \in L \Leftrightarrow f(x) > 0.
		\end{align*}
		\item The class $\up$ consists of all languages $L$ for which there exists a function $f \in \sp$ such that for any $x \in \Sigma^{*}$:
		\begin{align*}
			x \in L \Leftrightarrow f(x) = 1, \\
			x \notin L \Leftrightarrow f(x) = 0.
		\end{align*}
		\item The class $\cp$ consists of all languages $L$ for which there exist functions $f \in \sp$ and $g \in \fp$ such that for any $x \in \Sigma^{*}$:
		\begin{align*}
			x \in L \Leftrightarrow f(x) = g(x).
		\end{align*}
		\item The class $\pp$ consists of all languages $L$ for which there exist functions $f \in \sp$ and $g \in \fp$ such that for any $x \in \Sigma^{*}$:
		\begin{align*}
			x \in L \Leftrightarrow f(x) > g(x).
		\end{align*}
		\item The class $\spp$ consists of all languages $L$ for which there exists a function $f \in \gapp$ such that for any $x \in \Sigma^{*}$:
		\begin{align*}
			x \in L \Leftrightarrow f(x) = 1, \\
			x \notin L \Leftrightarrow f(x) = 0.
		\end{align*}
	\end{enumerate}
\end{definition}

The following relations are well known or follow immediately from definitions:

\begin{proposition} \label{rel-bas}
	\begin{enumerate}
		\item $\fpl \subseteq \totp \subseteq \sp \subseteq \spanp$.
		\item \textnormal{\cite{fen94,bak24}} $\gapp = \sp - \sp = \sp - \fp = \totp - \totp = \totp - \fp$.
		\item $\p \subseteq \up \subseteq \np \subseteq \pp$.
		\item $\conp \subseteq \cp \subseteq \pp$.
		\item $\sp \subseteq \fp^{\pp}$.
	\end{enumerate}
\end{proposition}

The next theorem gives characterizations of the inclusions between function classes that are not known to hold:

\begin{theorem}
	\begin{enumerate}
		%\item \textnormal{\cite{}}
		\item \textnormal{\cite{iva25}} $\sp = \totp$ if and only if $\p = \np$. 
		\item \textnormal{\cite{kob89}} $\spanp = \sp$ if and only if $\np = \up$. 
		\item $\spanp \subseteq \gapp$ if and only if $\np \subseteq \spp$. 
		\item If $\gappl \subseteq \spanp$, then $\mathsf{PH} = \mathsf{\Sigma^{P}_{2}}$.
		%\item If $\gappl \subseteq \sp$, then $\mathsf{PH} = \mathsf{\Sigma^{P}_{2}}$.
		\item The inclusion $\sp \subseteq \gappl$ is proper unless $\mathsf{PH} = \mathsf{\Sigma^{P}_{2}}$. 
	\end{enumerate}
\end{theorem}

\begin{proof}
	\begin{enumerate} 
		\setcounter{enumi}{2}
		\item The proof from right to left is given in \cite[Corollary 3.5]{mah94}. The proof from left to right follows from \autoref{np-span}.
		\item For every class $L \in \cp$ there exists a function $f \in \gappl$ such that $L = \{x \ | \ f(x) = 0\}$ \cite{for97}. If $\gappl \subseteq \spanp$, then $L \in \conp$. From $\cp = \conp$ it follows that $\mathsf{PH} = \mathsf{\Sigma^{P}_{2}}$ \cite{ike22}: $\mathsf{PH} \subseteq \p^{\sp} \subseteq \np^{\sp} = \np^{\cp} = \np^{\conp} = \mathsf{\Sigma^{P}_{2}}$, where $\mathsf{PH} \subseteq \p^{\sp}$ is by Toda's theorem \cite{tod91}.
		\item Immediate from $(4)$. \qedhere
	\end{enumerate}
\end{proof}

\begin{lemma} \label{np-span}
	A language $L$ is in the class $\np$ if and only if there exists a function $f \in \spanp$ such that for any $x \in \Sigma^{*}$:
	\begin{align*}
		x \in L \Leftrightarrow f(x) = 1, \\
		x \notin L \Leftrightarrow f(x) = 0.
	\end{align*}
\end{lemma}

In \cite{tod92}, it is shown that $\sp^{\mathsf{PH}} \subseteq \fp^{\sp[1]}$. $\spanp$ is a subset of $\sp^{\mathsf{PH}}$, because $\spanp \subseteq \sp^{\np} \subseteq \sp^{\mathsf{PH}}$. From \autoref{rel-bas} we have the following proposition:\footnote{The class $\mathsf{SpanL}$ \cite{alv93}, which is a subset of $\totp$, is also known to be 1-Cook equivalent with $\sp$ \cite{alv93,hem95}. In \cite{hem95}, it is shown that $\gapp = \mathsf{SpanL} - \mathsf{FL}$. It follows that $\fp^{\mathsf{SpanL}[1]} = \fp^{\sp[1]} = \fp^{\spanp[1]}$.}

\begin{proposition} \label{tur-eq}
	$\fp^{\sp[1]} = \fp^{\gapp[1]} = \fp^{\totp[1]} = \fp^{\spanp[1]}$.
\end{proposition}

\begin{definition} [\cite{boo84,boo85}]
	\begin{enumerate}
		\item The class $\npsv$ consists of all functions $f$ such that there exists a NPTM that on any input $x \in \Sigma^{*}$ has at least one accepting path and outputs the value of $f(x)$ on every accepting path.
		\item The class $\upsv$ consists of all functions $f$ such that there exists a NPTM that on any input $x \in \Sigma^{*}$ has exactly one accepting path and outputs the value of $f(x)$ on the unique accepting path.
	\end{enumerate}
\end{definition}

The classes $\npsv$ and $\upsv$ contain the total functions from the classes $\mathsf{NPSV}$ and $\mathsf{UPSV}$ respectively. %which were introduced
The proof of \autoref{npsv-fp} is given in \cite[Proposition 2.4]{boo85}.

\begin{proposition} \label{npsv-fp}
	\begin{enumerate}
		\item \textnormal{\cite{sel94}} $\npsv = \fp^{\np \cap \conp}$.
		\item \textnormal{\cite{hem06}} $\upsv = \fp^{\up \cap \coup}$.
	\end{enumerate}
\end{proposition}

In sections 4 and 5, we assume that the classes $\npsv$, $\upsv$ contain only non-negative integer valued functions in order to compare them with the integer-valued counting functions.

\section{Low languages and low functions}

In this section, we characterize the classes of languages and functions that are low for counting function classes. 

\begin{definition}
	Let $C$ be a relativizable complexity class. 
	\begin{enumerate}
		\item A language $L$ is low for the class $C$, if $C^{L} = C$. $Low(C)$ is the class of all languages that are low for $C$.
		\item A function $g$ is low for the class $C$, if $C^{g} = C$. $Low_{f}(C)$ is the class of all functions that are low for $C$.
	\end{enumerate}
\end{definition}

\begin{theorem}
	\begin{enumerate} 
		\item \textnormal{\cite{li93}} $Low(\sp) = \up \cap \coup$.
		\item \textnormal{\cite{fen94}} $Low(\gapp) = \spp$.
		\item \textnormal{\cite{fen94}} $Low(\gappl) = \spp$.
		\item $Low(\totp) = \p$.
		\item $Low(\spanp) = \np \cap \conp$.
		%\item \textnormal{\cite{}} $\up \cap \coup = \{L \ | \  \sp^{L} = \sp\}$.
		%\item \textnormal{\cite{}} $\spp = \{L \ | \  \gapp^{L} = \gapp\}$.
		%\item \textnormal{\cite{}} $\spp = \{L \ | \  \gappl^{L} = \gappl\}$.
		%\item $\p = \{L \ | \  \totp^{L} = \totp\}$.
		%\item $\np \cap \conp = \{L \ | \  \spanp^{L} = \spanp\}$.
	\end{enumerate}
\end{theorem}

\begin{proof} 	
	\begin{enumerate} 
		\setcounter{enumi}{3}
		\item All languages in $\p$ are low for $\totp$. If a language $L$ is low for $\totp$, then there exists a function in $\totp^{L} = \totp$ such that for any $x \in \Sigma^{*}$:
		\begin{align*}
			x \in L \Leftrightarrow f(x) = 1, \\
			x \notin L \Leftrightarrow f(x) = 0.
		\end{align*}
		Then $L$ is in $\p$, because every polynomial bounded $\totp$-function is in $\fp$ \cite{bak24}. 		
		\item $(\subseteq)$: For every oracle NPTM $M^{L}$, where $L \in \np \cap \conp$, there exists an NPTM $M'$ without an oracle that has the same set of output values. Let $N_{1}$ be a NPTM that witnesses $L \in \np$ and $N_{2}$ be a NPTM that witnesses $L \in \conp$. $M'$ simulates $M$, and whenever $M$ makes an oracle call, $M'$ guesses the oracle answer and simulates $N_{1}$ to verify the positive answer and simulates $N_{2}$ to verify the negative answer. $M'$ continues the computation only on paths with a correct oracle answer and rejects on the other paths. 

		$(\supseteq)$: If a language $L$ is low for $\spanp$, then there exist functions $f, g \in \spanp^{L} = \spanp$ such that for any $x \in \Sigma^{*}$:
		\begin{align*}
			x \in L \Leftrightarrow f(x) = 1, \ g(x) = 0,\\
			x \notin L \Leftrightarrow f(x) = 0, \ g(x) = 1.
		\end{align*}
		By \autoref{np-span}, $L \in \np$ and $L \in \conp$.
		\qedhere
	\end{enumerate}
\end{proof}

In \autoref{low-functions} we assume that a NPTM can have as an oracle only a function such that the length of its output value is polynomially bounded in the length of the input.

