%	Let $f$ be a function.
%	\begin{enumerate}
%		\item $graph(f) = \{(x, y) \ | \ y = f(x)\}$.
%		\item $pregraph(f) = \{(x, y) \ | \ y$ is a prefix of $f(x)\}$.
%	\end{enumerate}
%\end{definition}

%\begin{definition} [\cite{}]
%	For a function $f$, let $pregraph(f) = \{(x, y) \ | \ y$ is a prefix of $f(x)\}$. 
%\end{definition}

\begin{theorem} \label{low-functions}
	\begin{enumerate} 
		\item $Low_{f}(\sp) = \upsv$.
		\item $Low_{f}(\gapp) = \fp^{\spp}$.
		\item $Low_{f}(\gappl) = \fp^{\spp}$.
		\item $Low_{f}(\totp) = \fp$.
		\item $Low_{f}(\spanp) = \npsv$.
		%\item $\upsv = \{f \ | \  \sp^{f} = \sp\}$.
		%\item $\fp^{\spp} = \{f \ | \  \gapp^{f} = \gapp\}$.
		%\item $\fp^{\spp} = \{f \ | \  \gappl^{f} = \gappl\}$.
		%\item $\fp = \{f \ | \  \totp^{f} = \totp\}$.
		%\item $\npsv = \{f \ | \  \spanp^{f} = \spanp\}$.
	\end{enumerate}
\end{theorem}

\begin{proof}
	We give a proof only for $\sp$. The proofs for $\gapp$, $\gappl$, $\totp$, and $\spanp$ are similar. $\upsv$ is low for $\sp$, because $\sp^{\upsv} = \sp^{\fp^{\up \cap \coup}} \subseteq \sp^{\up \cap \coup} = \sp$. For a function $f$, let %\footnote{The terms $graph(f)$ and $pregraph(f)$ are used in \cite{}.}
	$pregraph(f) = \{(x, y) \ | \ y$ is a prefix of $f(x)\}$ \cite{boo85}. If a function $f$ is low for $\sp$, then $\sp^{pregraph(f)} \subseteq \sp^{f} = \sp$, which implies that $pregraph(f) \in \up \cap \coup$. Therefore, $f \in \fp^{pregraph(f)} \subseteq \fp^{\up \cap \coup}$.
\end{proof}

\section{Relations between NPSVt, UPSVt, and counting classes} \label{sec-rel}

In this section, we establish the relations between the classes $\npsv$, $\upsv$, and the counting function classes $\sp$, $\gappl$, $\totp$, and $\spanp$. The classes $\sp$, $\gappl$, $\spanp$ contain $\upsv$, and $\spanp$ contains $\npsv$ unconditionally. For the other inclusions we give characterizations in terms of inclusions between language classes.

\begin{proposition} \label{upsv-totp}
	$\upsv \subseteq \totp$ if and only if $\p = \up \cap \coup$.
\end{proposition}

\begin{proof}
	Let $L$ be a language in $\up \cap \coup$. If $\upsv = \fp^{\up \cap \coup} \subseteq \totp$, then the function 
	\begin{align*}
		f(x) = \begin{cases}
			1, &\text{$x \in L$;}\\
			0, &\text{$x \notin L$.}
		\end{cases}
	\end{align*}
	is in $\totp$. Then $L$ is in $\p$, because every polynomial bounded $\totp$-function is in $\fp$ \cite{bak24}. 

	If $\p = \up \cap \coup$, then $\upsv = \fp^{\up \cap \coup} = \fp \subseteq \totp$.
\end{proof}

\begin{proposition}
	\begin{enumerate}
		\item $\npsv \subseteq \totp$ if and only if $\p = \np \cap \conp$.
		\item $\npsv \subseteq \sp$ if and only if $\up \cap \coup = \np \cap \conp$.
		\item $\npsv \subseteq \gappl$ if and only if $\np \cap \conp \subseteq \spp$.
	\end{enumerate}
\end{proposition}

\begin{proof}
	The proofs from left to right are similar to \autoref{upsv-totp}. The proofs from right to left are immediate from $\fp \subseteq \totp$, $\fp^{\up \cap \coup} \subseteq \sp$, and $\fp^\spp \subseteq \gappl$.
\end{proof}

\begin{proposition} \label{in-upsv}
	The following statements are equivalent:
	\begin{enumerate}
		\item $\totp \subseteq \upsv$.
		\item $\sp \subseteq \upsv$.
		\item $\gappl \subseteq \upsv$.
		\item $\spanp \subseteq \upsv$.
		\item $\pp = \up$.
	\end{enumerate}
\end{proposition}

\begin{proof}
	To prove that $(1 - 4)$ implies $(5)$, it suffices to show that $(1)$ implies $(5)$. Let $L$ be a language in $\pp$. Then there exist functions $f \in \totp$ and $g \in \fp$ such that $L = \{x \ | \ f(x) > g(x)\}$. If $\totp \subseteq \upsv$, then there exists a NPTM $M$ that on any input $x \in \Sigma^{*}$ has exactly one accepting path and outputs $f(x)$ on the unique accepting path. Then $L \in \up$, because there exists a NPTM $M'$ that simulates $M(x)$ and accepts on the unique accepting path of $M(x)$ if and only if $f(x) > g(x)$.

	$(5)$ implies $(1 - 4)$, because every class from $\sp$, $\totp$, $\gappl$, and $\spanp$ is a subset of $\fp^{\sp}$ by \autoref{tur-eq}. If $\pp = \up$, then $\fp^{\sp} = \fp^{\pp} = \fp^{\up \cap \coup} = \upsv$.	
\end{proof}

\begin{proposition}
	The following statements are equivalent:
	\begin{enumerate}
		\item $\totp \subseteq \npsv$.
		\item $\sp \subseteq \npsv$.
		\item $\gappl \subseteq \npsv$.
		\item $\spanp \subseteq \npsv$.
		\item $\pp = \np$.
	\end{enumerate}
\end{proposition}

\begin{proof}
	The proof is similar to \autoref{in-upsv}.
\end{proof}

\section{Closure under composition with FP} \label{sec-fp}

In this section, we study the closure of counting function classes under left composition with the class $\fpl$. In \cite{ogi93}, it is shown that the closure of $\sp$ under composition with multivariate $\fpl$-functions is equivalent to $\pp = \up$, and for $\spanp$ this closure is equivalent to $\p^{\pp} = \np$.
We show that in these theorems univariate $\fpl$-functions can be considered, and also we add an equivalent statement $\sp = \upsv$ to \autoref{fp-sp}. To \autoref{fp-span} we add equivalent statements $\spanp = \npsv$ and $\pp = \np$. The proof of equivalence between $\sp = \upsv$ and $\pp = \up$ can be found in \cite[Theorem 4.3(1)]{kos99} and \cite[Theorem 5.11(2)]{hem06}. We give the proofs for $\sp$ and $\spanp$, which can also be applied for $\gapp$, $\gappl$, and $\totp$.

%In this section, we show that for each of the classes $\sp$, $\gapp$, $\gappl$, $\totp$, $\spanp$ the closure under left composition with $\fpl$ implies that the class collapses to its low class of functions.

\begin{theorem} \label{fp-sp}
	The following statements are equivalent:
	\begin{enumerate}
		\item $\fpl \circ \sp \subseteq \sp$.
		\item $\sp = \upsv$.
		\item $\pp = \up$.
	\end{enumerate}
\end{theorem}

\begin{proof}	
	$(1 \Rightarrow 3)$: Let $L = \{x \ | \ f(x) > g(x)\}$, where $f \in \sp$, $g \in \fp$. The function 
	\begin{align*}
		h(x) = \begin{cases}
			1, &\text{$f(x) > g(x)$;}\\
			0, &\text{$\textnormal{otherwise}$.}
		\end{cases}
	\end{align*}
	is in $\fpl^{\sp[1]}$, which coincides with the class $\fp_{+} \circ \sp$ by \autoref{comp-sp}. By assumption, $h \in \sp$ and $L \in \up$. 

	$(3 \Rightarrow 2)$: If $\pp = \up$, then $\sp \subseteq \fp^{\pp} = \fp^{\up \cap \coup} = \upsv$.

	$(2 \Rightarrow 1)$: Follows from $\fpl \circ \upsv \subseteq \upsv$.
\end{proof}

\begin{theorem} \label{fp-span}
	The following statements are equivalent:
	\begin{enumerate}
		\item $\fpl \circ \spanp \subseteq \spanp$.
		\item $\spanp = \npsv$.
		\item $\pp = \np$.
	\end{enumerate}
\end{theorem}

\begin{proof}
	$(1 \Rightarrow 3)$: Let $L = \{x \ | \ f(x) > g(x)\}$, where $f \in \sp$, $g \in \fp$. The function 
	\begin{align*}
		h(x) = \begin{cases}
			1, &\text{$f(x) > g(x)$;}\\
			0, &\text{$\textnormal{otherwise}$.}
		\end{cases}
	\end{align*}
	is in $\fpl^{\spanp[1]}$, which coincides with the class $\fp_{+} \circ \spanp$ by \autoref{comp-sev}. By assumption, $h \in \spanp$. By \autoref{np-span}, $L \in \np$. 

	$(3 \Rightarrow 2)$: If $\pp = \np$, then $\spanp \subseteq \fp^{\sp} = \fp^{\pp} = \fp^{\np \cap \conp} = \npsv$.

	$(2 \Rightarrow 1)$: Follows from $\fpl \circ \npsv \subseteq \npsv$.
\end{proof}

The proof of equivalence between $\fpl \circ \gapp \subseteq \gapp$ and $\pp = \spp$ can be found in \cite{gup91,fen94}.

\begin{theorem} [\cite{thi94,gup91,fen94}]
	The following statements are equivalent:
	\begin{enumerate}
		\item $\fpl \circ \gapp \subseteq \gapp$.
		\item $\gapp = \fp^{\spp}$.
		\item $\pp = \spp$.
	\end{enumerate}
\end{theorem}

The theorem for $\gappl$ can be proved similarly. In \cite{thi94}, it is shown that $\pp = \spp$ is equivalent to $\gappl = \fpl^{\spp}$.

\begin{theorem} [\cite{thi94,gup91,fen94}]
	The following statements are equivalent:
	\begin{enumerate}
		\item $\fpl \circ \gappl \subseteq \gappl$.
		\item $\gappl = \fpl^{\spp}$.
		\item $\pp = \spp$.
	\end{enumerate}
\end{theorem}

The proof of the following theorem is given in \cite{iva25}.

\begin{theorem} [\cite{iva25}]
	The following statements are equivalent:
	\begin{enumerate}
		\item $\fpl \circ \totp \subseteq \totp$.
		\item $\totp = \fpl$.
		\item $\pp = \p$.
	\end{enumerate}
\end{theorem}

\section{One function computes several functions} \label{sec-sev}

In this section, we prove a technical lemma, which states that functions from $\sp$, $\gapp$, $\totp$, and $\spanp$ can output the values of several functions. The first application of this idea is \autoref{comp-sev}, which shows that a composition of $\fp$ with one function is the same as a composition with several functions. The second application is \autoref{sp-sp}, which states that a NPTM with a $\sp$ oracle can always make at most one query to the oracle. A function $h$ is in the class $\fp \circ (\sp \times \ldots \times \sp)$ if there exist functions $f \in \fp$ and $g_{1}, ..., g_{k} \in \sp$ such that for any $x \in \Sigma^{*}$: $h(x) = f(g_{1}(x), \ldots, g_{k}(x))$. 

\begin{lemma} \label{comp-sp}
	$\fp \circ \sp = \fp^{\sp[1]} = \fp \circ (\sp \times \ldots \times \sp)$.
\end{lemma}

\begin{proof}
	For every functions $f_{1}, \ldots, f_{k} \in \sp$ there exists a function $g \in \sp$ that on input $x \in \Sigma^{*}$ outputs a concatenation of the values of $f_{1}(x), \ldots, f_{k}(x)$. The function $g$ can be defined as $g(x) = f_{1}(x) \cdot 2^{(k - 1)p(|x|)} + f_{2}(x) \cdot 2^{(k - 2)p(|x|)} + \ldots + f_{k}(x)$, where $p$ is a polynomial such that for any $x \in \Sigma^{*}$: $|f_{1}(x)| \leqslant p(|x|), \ldots, |f_{k}(x)| \leqslant p(|x|)$. It follows that $\fp \circ \sp = \fp \circ (\sp \times \ldots \times \sp)$. $\fp^{\sp[1]}$ is a subset of $\fp \circ (\sp \times \fp)$, because for every function $f \in \fp^{\sp[1]}$ there exist functions $g, h \in \fp$ and $t \in \sp$ such that for any $x \in \Sigma^{*}$: $f(x) = g(t(h(x)), x)$.
\end{proof}

For the classes $\gapp$, $\totp$, and $\spanp$ the same statement also holds, because they contain $\fpl$ and closed under addition, multiplication, and parsimonious reductions. From \autoref{tur-eq} we have the following corollary:

\begin{corollary} \label{comp-sev}
	$\fp \circ \sp = \fp \circ \gapp = \fp \circ \totp = \fp \circ \spanp = \fp^{\sp[1]} = \fp^{\gapp[1]} = \fp^{\totp[1]} = \fp^{\spanp[1]} = \fp \circ (\sp \times \ldots \times \sp) = \fp \circ (\gapp \times \ldots \times \gapp) = \fp \circ (\totp \times \ldots \times \totp) = \fp \circ (\spanp \times \ldots \times \spanp)$.
\end{corollary}

In \cite[Lemma 4.3]{kob89}, it is proved that $\sp^{\np} = \sp^{\np[1]}$. We use a similar idea in \autoref{sp-sp}.

\begin{proposition} \label{sp-sp}
	\begin{enumerate}
		\item $\sp^{\sp} = \sp^{\sp[1]}$.
		\item $\gapp^{\sp} = \gapp^{\sp[1]}$.
	\end{enumerate}
\end{proposition}

\begin{proof}
	\begin{enumerate}
		\item Let $M^{f}$ be a NPTM with an oracle $f \in \sp$.  There exists a NPTM $N^{g}$ with an oracle $g \in \sp$ such that for any $x \in \Sigma^{*}$: $acc_{M^{f}}(x) = acc_{N^{g}}(x)$ and on every computation path $N^{g}$ makes at most one query to the oracle. The machine $N^{g}$ simulates $M^{f}$ and guesses all oracle answers. Before it halts, $N^{g}$ verifies all oracle answers by a single query to the oracle, and rejects if at least one oracle answer was guessed incorrectly.	The oracle function $g$ is constructed so that on input $(x_{1}, \ldots, x_{k}) \in \Sigma^{*}$ the function $g$ outputs a concatenation of the values of $f(x_{1}), \ldots, f(x_{k})$. Let $S$ be a NPTM and $p$ be a polynomial such that for any $x \in \Sigma^{*}$: $acc_{S}(x) = f(x)$ and $|f(x)| \leqslant p(|x|)$. The function $g$ can be defined as $g(x) = acc_{T}(x)$, where $T$ is the NPTM that on input $(x_{1}, \ldots, x_{k}) \in \Sigma^{*}$: generates $k$ branches, simulates $S(x_{i})$ on the $i$-th branch for $1 \leqslant i \leqslant k$, and then generates $2^{(i - 1) \cdot p(\max(|x_{1}|, \ldots, |x_{k}|))}$ accepting paths. By construction, $g(x) = f(x_{k}) \cdot 2^{(k - 1)p(\max(|x_{1}|, \ldots, |x_{k}|))} + f(x_{k - 1}) \cdot 2^{(k - 2)p(\max(|x_{1}|, \ldots, |x_{k}|))} + \ldots + f(x_{1})$.
		\item The proof is similar to $(1)$. 
		\qedhere
	\end{enumerate}
\end{proof}

The same statement holds for languages that are defined using a single $\sp$ or $\gapp$ function:

\begin{corollary}
	\begin{enumerate}
		\item $\np^{\cp[1]} = \np^{\pp[1]} =  \np^{\pp} = \np^{\sp[1]} = \np^{\sp} = \np^{\gapp} = \np^{\totp} = \np^{\spanp}$.
		\item $\pp^{\cp[1]} = \pp^{\pp[1]} = \pp^{\pp} = \pp^{\sp[1]} = \pp^{\sp} = \pp^{\gapp} = \pp^{\totp} = \pp^{\spanp}$.
	\end{enumerate}
\end{corollary}



