\bigskip\noindent
\textbf{Analysis of the algorithm.} We now show that the proposed algorithm indeed produces a collection of parallelotopes $\cP=\cP_4$ which satisfies the conditions of Lemma~\ref{lemma:polytope decomposition}. First, we observe that the elements of $\cP$ cover $Q$ trivially.
Next, we show that $|\cP|=O_{d, h}(1)$.

\begin{lemma}\label{lemma:few parallelotopes}
The collection $\cP$ contains at most $O_{d, h}(1)$ parallelotopes.
\end{lemma}
\begin{proof}
We show, by induction on $d$, that there exists a function $f(d, h)$ such that, for any set of $h$ halfspaces $\cH$ in $\bR^d$ and any polytope $Q\in {\rm POL}(\cH)$ we have $|\cP|\leq f(d, h)$. For the base case $d=2$,  Lemma~\ref{lemma:plane decomposition} implies that $f(2, h)=4h$ suffices.

Assume that $d\geq 3$. First, observe that  $|\cP_1|\leq O_{h}(1)$. Indeed, the number of hyperplanes $H_f$ dividing $Q$ is the number of $(d-2)$-dimensional facets, which is at most $\binom{h}{2}$. Hence, these hyperplanes cut $Q$ into $O_{d,h}(1)$ cells.

To analyze Step 2, take any cell $C\in \cP_1$ and consider how many cells it contributes to $\cP_2$. Recall that in Step 2, we project $C$ to the horizontal hyperplane and decompose its shadow. The $(d-1)$-dimensional shadow of $C$, denoted by $C'$, has at most $O_{d,h}(1)$ facets and therefore the inductive hypothesis implies that the number of parallelotopes in the decomposition of $C'$ is at most $f(d-1, O_{d,h}(1))$. This shows that $|\cP_2|\leq f(d-1, O_{d,h}(1)) |\cP_1|\leq O_{d,h}(1)$.

In Step 3, we  subdivide each prism $P\in \cP_2$ into at most $2$ prisms, so we have $|\cP_3|\leq 2|\cP_2|$. Finally, Step 4, we apply induction on a $(d-1)$-dimensional vertical face $F$ of the prism $P$ which has parallel edges. The face $F$ has at most $2^{d-1}$ vertices and at most $2(d-1)$ facets, since $P$ is a slanted prism with a parallelotope base. Therefore, $F$ is covered by  at most $f(d, 2(d-1))$ parallelotopes and we conclude $|\cP|=|\cP_4|\leq f(d, 2(d-1)) \cdot |\cP_3|= O_{d,h}(1)$. This finishes the proof of the lemma.
\end{proof}

The last ingredient needed for the proof of the Lemma~\ref{lemma:polytope decomposition} is to show that the set of directions of facets of parallelotopes is contained in a set of size $O_{d,h}(1)$, independently of which element $Q\in {\rm POL}(\cH)$ we picked.


\begin{lemma}\label{lemma:bounding the directions}
For every collection $\cH$ of $h$ halfspaces in $\bR^d$, there exists a collection $\cH'$ of at most $O_{d, h}(1)$ halfspaces, such that the following holds. For any  $Q\in {\rm POL}(\cH)$, the collection of parallelotopes in $\cP$ produced by the above algorithm are intersections of translates of halfspaces of $\cH'$.    
\end{lemma}
\begin{proof}
We describe the elements of $\cH'$ by induction on $d$, noting that the base case $d=2$ is addressed in Lemma~\ref{lemma:plane decomposition}. In the inductive step, we consider the four steps of the algorithm separately.

\medskip
\noindent
\textit{Step 1.} First, let $\cH_1$ be the collection of halfspaces bounded by the vertical hyperplanes through the $(d-2)$-flats formed by the intersections $h_1\cap h_2$ for distinct $h_1, h_2\in \cH$. The observation is that each cell $C\in \cP_1$ is an intersection of translates of halfspaces of $\cH_1$, by construction. Furthermore, note that $\cH_1$ contains at most $2\binom{h}{2}=O_h(1)$ halfspaces, since each vertical hyperplane bounds two halfspaces.

\medskip
\noindent
\textit{Step 2.} Now consider all $(d-2)$-flats of the form $h_1\cap h_2$ for some $h_1, h_2\in \cH_1$, and denote by $\cF$ the set of $(d-1)$-dimensional halfspaces bounded by the projections of these flats to the horizontal hyperplane. The elements of $\cF$ are codimension 1 subspaces of the horizontal hyperplane, and thus we can apply the inductive hypothesis. Thus, if a cell $C\in \cP_1$ projects to a cell $C'\in {\rm POL}(\cF)$, then $C'$ can be covered with some parallelotopes  belonging to ${\rm POL}(\cF')$, for some $\cF'$ depending only on $\cF$ and having size $O_{d, h}(1)$. Let $\cH_2$ be the union of $\cH_1$ and the set of all halfspaces we get by extending the halfspaces of $\cF'$ in the vertical direction. Note that each prism in $\cP_2$ is an intersection of translates of halfspaces in $\cH_2$.

\medskip
\noindent
\textit{Step 3.} Let $\cV$ be the set of direction vectors of lines formed by the intersection of $d-1$ hyperplanes of $\cH_2$. Note that each $1$-dimensional face of a cell in $\cP_2$ is parallel to some $v\in \cV$. Now, consider the hyperplanes spanned by $d-1$ linearly independent  vectors from $\cV$ and let $\cH_3$ be the collection of halfspaces determined by these hyperplanes. The size of $\cH_3$ can be bounded as follows: first note that $|\cV|\leq \binom{|\cH_2|}{d-1}=O_{d, h}(1)$ and $|\cH_3|\leq 2\binom{|\cV|}{d-1}=O_{d, h}(1)$. Furthermore, each cell of $\cP_3$ is an intersection of translates of halfspaces from $\cH_3$.

\medskip
\noindent
\textit{Step 4.} For each vertical hyperplane in $h\in \cH_3$, let $\cF(h)$ be the set of intersections of all other hyperplanes in $\cH_3$ with $h$. This collection of $(d-2)$-dimensional hyperplanes bounds each vertical face $F$ of a cell $P\in \cP_3$. Therefore, there exists a collection of halfspaces $\cF'(h)$, of size $O_{d, h}(1)$, such that each parallelotope in the subdivision of $F$ belongs to ${\rm POL}(\cF'(h))$. Now, for each vector $v$ from the set of directions $\cV$ defined in Step 3, consider the hyperplane determined by $v$ and each element of $\cF'(h)$, and add the corresponding halfspaces to $\cH_4$. By construction, each parallelotope from $\cP=\cP_4$ is bounded by translates of halfspaces from $\cH_4$, and so it suffices to set $\cH'=\cH_4$. The size of $\cH_4$ is bounded by $|\cH_4|\leq \sum_{h\in \cH_3} |\cF'(h)| |\cV|=|\cH_3| \cdot |\cV| \cdot O_{d, h}(1) = O_{d, h}(1)$.
\end{proof}

Lemma~\ref{lemma:polytope decomposition} is now a direct corollary of the previous  results. It only remains to prove Proposition~\ref{prop:point-polytope incidence graphs}.

\begin{proof}[Proof of Proposition~\ref{prop:point-polytope incidence graphs}.]
Let $G$ be the incidence graph of the set of $n$ polytopes $X\subset \mbox{POL}(\cH)$ and set of $n$ points $Y\subset \mathbb{R}^d$.

Apply Lemma~\ref{lemma:polytope decomposition} to the set of halfspaces $\cH$, thus obtaining the set of halfspaces $\cH'$. Each polytope $Q\in X\subseteq {\rm POL}(\cH)$ is the union of a collection of parallelotopes $\cP_Q\subseteq {\rm POL}(\cH')$ of size  $|\cP_Q|\leq A$ for some $A=O_{d,h}(1)$. Say that the \emph{type} of a parallelotope  $T\in {\rm POL}(\cH')$ is the set of $d$ linear hyperplanes parallel to some face of $T$. Then there are at most $\binom{|\cH'|}{d}\leq B$ different types, where $B=O_{d,h}(1)$. Pick a type $\alpha$ randomly from the uniform distribution, and for every $Q\in X$, pick an element of $T_Q\in \cP_Q$ independently from the uniform distribution. Let $X'$ be the collection of parallelotopes $T_Q$ that have type $\alpha$, and let $G'$ be the indicedence graph of $(X',Y)$. Observe that $G'$ is isomorphic to a subgraph of $G$, so if $G$ is $K_{s,s}$-free, then $G'$ is $K_{s,s}$-free as well.

Given an edge $\{y,Q\}$ of $G$, there is at least one $T\in \cP_Q$ such that $y\in T$. Therefore, the probability that $\{y,T_Q\}$ is an edge of $G'$ is at least $1/AB$. Hence, the expected number of edges of $G'$ is at least $e(G)/AB$. Thus, there is a choice of $\alpha$ and $\{T_Q:Q\in Y\}$ such that $G'$ has at least $e(G)/AB$ edges, fix such a choice. After an appropriate affine transformation, each $\alpha$-type parallelotope can be made an axis-parallel box. Therefore, $G'$ is an incidence graph of  $n$ points and at most $n$ axis-parallel boxes in $\mathbb{R}^d$. By the result of Chan and Har-Peled \cite{CH23}, if $G'$ is $K_{s,s}$-free, then $e(G')=O_d(s(\log n/\log \log n)^{d-1})$. As $AB=O_{d,h}(1)$, we get $e(G)=O_{d,h}(s(\log n/\log \log n)^{d-1})$.
\end{proof}

\section{Polygon visibility graphs and ordered graphs}\label{sec:polygon visibility}


In this section, we prove Theorem \ref{thm:polygon_visibility}. We prepare the proof with a number of  general results, starting with a result about graphs of bounded VC-dimension. Then, we will present some results about the degree-boundedness of ordered graphs avoiding some fixed ordered matching, which might be of independent interest. 

Given a graph $G$, its \emph{VC-dimension} is the largest positive integer $d$ with the following property. There is a $d$-element subset $U\subset V(G)$ such that for every $T\subset U$, there is some vertex $v\in V(G)$ with $N(v)\cap U=T$. Lov\'asz and Szegedy \cite{LSz} proved that graphs of bounded VC-dimension admit a so called \emph{ultra-strong regularity lemma}. This lemma states that if $G$ has VC-dimension at most $d$ and given $\eps\in (0,1/2)$, then there is a partition of $V(G)$ into sets $V_1,\dots,V_t$ such that (i) $t=(1/\eps)^{O(d^2)}$, (ii) $|V_1|,\dots,|V_t|\in \{\lfloor|V(G)|/t\rfloor,\lceil |V(G)|/t\rceil\}$, (iii) all but $\eps t^2$ of the pairs $(i,j)$ with $1\leq i<j\leq t$ satisfy that either $e(G[V_i,V_j])<\eps |V_i||V_j|$ or $e(G[V_i,V_j])\geq (1-\eps)|V_i||V_j|$. We only use the following immediate qualitative consequence of this lemma.

\begin{lemma}\label{lemma:VC}
Let $d$ be an integer and $\beta\in (0,1]$, then for every $\gamma\in (0,1/2)$ there exists $\alpha=\alpha(d,\beta,\gamma)$ such that the following holds. Let $G$ be an $n$-vertex graph of VC-dimension at most $d$. If $e(G)\leq (1-\beta) \binom{n}{2}$, then there exist disjoint $A,B\subset V(G)$ such that $|A|=|B|\geq \alpha n$, and the bipartite graph between $G[A,B]$ has maximum degree $\gamma |A|$.
\end{lemma}

\begin{proof}
Let $\eps=\min\{\gamma/4,\beta/4\}$, and let $V_1,\dots,V_t$ be a partition of $V(G)$ given by the ultra-strong regularity lemma. Say that a pair $(i,j)$ with $1\leq i<j\leq t$ is \emph{bad} if $e(G[V_i,V_j])> \eps|V_i||V_j|$. Then the number of non-edges of $G$ contained in some bad pair is at most $\eps (n/t)^2\cdot t^2+(n/t)^2\cdot \eps t^2=2\eps n^2$. Hence, as $2\eps<\beta/2$, there must exist a good pair $(i,j)$. Then there are at most $\eps |V_i||V_j|\leq (\gamma/4)|V_i||V_j|$ edges in the bipartite graph $H=G[V_i,V_j]$. 

Let $A, B$ be the sets of $|V_i|/2$ vertices of lowest degree from both $V_i$ and $V_j$, and note that all of them must have degree at most $(\gamma/2)|V_i|$. Otherwise, the $|V_i|/2$ vertices of higest degree would each have degree larger than $(\gamma/2)|V_i|$, giving more than $(\gamma/4)|V_i||V_j|$ edges in $H$, contradiction.
\end{proof}

We now discuss some results about ordered graphs avoiding a fixed ordered matching. An \emph{ordered graph} is a graph with a linear ordering on its vertex set, denoted by $<$. An ordered graph $G$ is \emph{ordered bipartite} if we can write $V(G)=A\cup B$ such that $A<B$ (that is, $a<b$ for every $a\in A$ and $b\in B$), and every edge of $G$ has one endpoint in $A$ and in $B$. The celebrated Marcus-Tardos theorem \cite{MT04} is equivalent to the statement that if $M$ is an ordered bipartite matching and $G$ is ordered bipartite with both vertex classes of size $n$ not containing $M$, then $G$ has at most $O_M(n)$ edges. Here, the condition that $G$ is ordered bipartite can be relaxed as follows. If $G$ is an $n$ vertex ordered graph not containing $M$ as an ordered subgraph, then $G$ has $O_M(n)$ edges, see \cite{Tardos}. We prove that the following strengthening also holds.

\begin{theorem}\label{thm:matching_degree_bounded}
Let $M$ be an ordered bipartite matching. If $G$ is an ordered graph not containg an induced copy of $M$, and $G$ contains no $K_{s,s}$, then $G$ has $O_{M,s}(n)$ edges.
\end{theorem}

\begin{proof}
Let $V(M)=\{1,\dots,k\}$ with the natural ordering. For an integer $\ell$, let $M^{(\ell)}$ be an arbitrary ordered bipartite matching satisfying the following. The vertex set of $M^{(\ell)}$ can be partitioned into intervals $I_1,\dots,I_{k}$ of size $\ell$ such that $I_a<I_b$ if $a<b$, and there is a perfect matching between $I_a$ and $I_b$ if $ab\in E(M)$, otherwise there is no edge between $I_a$ and $I_b$. For every $\ell$, $M^{(\ell)}$ is clearly an ordered bipartite matching, so there exists $c_{\ell}$ such that every $n$-vertex ordered graph which does not contain $M^{(\ell)}$ as an ordered subgraph has at most $c_{\ell}n$ edges, by \cite{Tardos}.

Choose $\ell$ sufficiently large such that every bipartite graph with vertex classes of size $\ell$ and no copy of $K_{s,s}$ has at most $\ell^2/k^2$ edges. Such a choice is possible by the K\H{o}v\'ari-S\'os-Tur\'an theorem. We show that if $G$ does not contain $K_{s,s}$, but it contains $M^{(\ell)}$, then $G$ contains an induced copy of $M$. If this is true, then every $K_{s,s}$ and induced $M$-free ordered graph has at most $c_{\ell}n$ edges, finishing the proof.

If $G$ contains $M^{(\ell)}$ as an ordered subgraph, we can find $\ell$-element sets $J_1<\dots<J_k$ in $V(G)$ such that there is a complete matching $N_{ab}$ between $J_a$ and $J_b$ if $ab\in E(M)$. Note that if $G$ contains no $K_{s,s}$, then the number of edges between $J_i$ and $J_j$ for every $1\leq i<j\leq k$ is at most  $\ell^2/k^2$.  For every $ab\in E(M)$,  pick an edge $x_ax_b\in E(N_{ab})$ randomly among the $\ell$ edges from the uniform distribution. We show that with positive probability, $\{x_1,\dots,x_k\}$ induces of copy of $M$. For every $1\leq i<j\leq k$ for which $ij\not\in E(M)$, 
$$\mathbb{P}(x_ix_j\in E(G))=\frac{e(G[J_i,J_j])}{\ell^2}\leq \frac{1}{k^2}.$$
Hence, by the union bound,
$$\mathbb{P}(\exists ij\not\in E(M): x_ix_j\in E(G))\leq \frac{\binom{k}{2}}{k^2}<1.$$
Thus, there is a choice of $\{x_1,\dots,x_k\}$ inducing a copy of $M$ in $G$.
\end{proof}

Unfortunately, if $M$ has at least 2 edges, it is not true that $K_{s,s}$-free ordered graphs avoiding an induced copy of $M$ must have $O_M(sn)$ edges, i.e. the hidden constant in $O_{M, s}(n)$ may not be linear in $s$, which can be seen by considering, say $s=n^{1/2}$, and very dense random ordered graphs. The reason for this is that the family of ordered graphs avoiding an induced copy of $M$ does not have the density-EH property. 

However, if the complement of $G$ avoids bipartite-induced copies of some ordered bipartite matching, then we can establish the density-EH property. Given an ordered bipartite graph $H$, say that an ordered graph $G$ contains a \emph{bipartite-induced} copy of $H$ if there exists $A,B\subset V(G)$ such that $A<B$, and the bipartite subgraph of $G$ between $A$ and $B$ is isomorphic to $H$ (note that we do not require $A$ and $B$ to be independent sets). A similar result is established in \cite{KPT}, but we present a proof for completeness as well. 

\begin{theorem}\label{thm:matching_EH}
Let $G$ be an ordered graph on $n$ vertices, and let $c>0$. Let $M$ be an ordered bipartite matching, then there exists $\eps=\eps(c,M)>0$ such that the following holds. If $G$ has at least $cn^2$ edges, and the complement of $G$ contains no bipartite-induced copy of $M$, then $G$ contains a biclique of size at least $\eps n$.
\end{theorem}
\begin{proof}
We divide the proof into three simple claims.

\begin{claim}
There exist $A,B\subset V(G)$ such that $A<B$, $|A|=|B|\geq \delta n$ for some $\delta=\delta(c)>0$, and there are at least $c^2|A||B|$ edges between $A$ and $B$.
\end{claim}

\begin{proof}
 Without loss of generality, let $\{1,\dots,n\}$ be the vertex set of $G$, endowed with the natural ordering. Let $A_0=\{1,\dots,k\}$ and $B_0=\{k+1,\dots,n\}$, where $k$ is randomly chosen from the uniform distribution. Say that an edge $f=\{x,y\}$, with $x<y$,  is \emph{cut} if $x\in A_0$ and $y\in B_0$, and let $X$ be the number of cut edges.  Then $\mathbb{P}(f\mbox{ is cut})=\frac{y-x}{n}$, so $$\mathbb{E}(X)=\sum_{\{x,y\}\in E(G)}\frac{y-x}{n}\geq \frac{cn^2}{2}\cdot \frac{c}{2}=\frac{c^2n^2}{4}.$$
Here, the first inequality follows as there are at most $cn^2/2$ edges $\{x,y\}$ with $y-x\leq cn/2$. Hence, there is a choice for $k$ such that $X\geq c^2n^2/4$. This is only possible if $\min\{k,n-k\}\geq c^2n/4$ also holds. Let $\delta=c^2/4$, and let $A\subset A_0$ and $B\subset B_0$ be random $\delta n$ size subsets chosen from the uniform distribution. Then the expected number of edges between $A$ and $B$ is at least $\frac{|A||B|}{|A_0||B_0|}\cdot c^2n^2/4\geq c^2|A||B|$.
\end{proof}

Let $H_0$ be the bipartite subgraph between $A$ and $B$, and let $H$ be the bipartite complement of $H_0$. Then $H$ has at most $(1-c^2)|A||B|$ edges, and $H$ contains no bipartite-induced copy of $M$.

\begin{claim}
For every $\lambda>0$, there exist $A_1\subset A$ and $B_1\subset B$ such that $|A_1|=|B_1|\geq \alpha |A|$ for some $\alpha=\alpha(M,c,\lambda)$, and the maximum degree of $H[A_1\cup B_1]$ is at most $\lambda |A_1|$.
\end{claim}

\begin{proof}
It is known (and easy to prove) that ordered graphs with no bipartite-induced copy of a given ordered bipartite graph $\Gamma$ have VC-dimension $O_\Gamma(1)$. Therefore,  Lemma \ref{lemma:VC} gives the desired result.
\end{proof}


Let $k$ be the number of edges of $M$, and set $\lambda=1/(8k^3)$. Let $A_1,B_1$ be the sets guaranteed by the previous claim with respect to $\lambda$, so $|A_1|=|B_1|\geq \alpha |A|\geq \alpha\delta n$ for some $\alpha=\alpha(M,c,\lambda)=\alpha(M,c)$.

\begin{claim}\label{claim:finding an empty biclique}
There exists $A_2\subset A_1$ and $B_2\subset B_1$ such that $|A_2|=|B_2|\geq \lambda |A_1|$, and there are no edges between $A_2$ and $B_2$ in $H$.
\end{claim}

\begin{proof}
Assume that there exist no such $A_2,B_2$, then we show that $H$ contains a bipartite induced copy of $M$. Let $V(M)=\{1,\dots,2k\}$, and let $I_1<\dots<I_k$ be a partition of $A_1$ into intervals of size $|A_1|/k$, and $I_{k+1}<\dots<I_{2k}$ be a partition of $B_1$ into intervals of size $|B_1|/k$. For every $ab\in E(M)$, there is a matching $N_{ab}$ of size $|I_a|/2=|A_1|/2k$ between $I_a$ and $I_b$. Otherwise, by K\"onig's theorem, there exist $X\subset I_a$ and $Y\subset I_b$ such that $|X|=|Y|=|A_1|/(2k)>\lambda|A_1|$ and with no edges between $X$ and $Y$. Let $V(N_{ab})=J_a\cup J_b$ with $J_a\subset I_a$ and $J_b\subset I_b$. For every $ab\in E(M)$, pick a random edge $x_ax_b$ of $N_{ab}$ independently from the uniform distribution. We show that $\{x_1,\dots,x_{2k}\}$ induces a copy of $M$ with positive probability. For every $ij\not\in E(M)$, $$\mathbb{P}(x_ix_j\in E(H))= \frac{e(H[J_i,J_j])}{|J_i||J_j|}\leq \frac{|J_i|(\lambda |A_1|)}{|J_i|(|A_1|/2k)}=\frac{1}{4k^2},$$
where  in the first inequality we used that the maximum degree of $H[A_1\cup B_1]$ is at most $\lambda n$. Hence, by the union bound, $$\mathbb{P}(\exists ij\not\in E(M): x_ix_j\in E(G))\leq \frac{\binom{2k}{2}}{4k^2}<1.$$
Thus, there is a choice of $\{x_1,\dots,x_{2k}\}$ inducing a copy of $M$ in $H$.
\end{proof}

As $\lambda|A_1|\geq \lambda \alpha |A|\geq \lambda\alpha\delta n$, the sets $A_2$ and $B_2$ from Claim~\ref{claim:finding an empty biclique} span a biclique of size at least $\lambda\alpha\delta n$ in $G$. Here, $\eps:=\lambda\alpha\delta>0$ only depends on $M$ and $c$, as promised.
\end{proof}

Given a Jordan curve $K$, say that two sets $A,B\subset K$ are \emph{separated} if $K$ can be cut into two subcurves such that one of the subcurves contains $A$, the other $B$. The following lemma sharpens Corollary 3.5 in \cite{AK25}.


