\begin{lemma}\label{lemma:visibility1}
Let $K$ be a Jordan curve, and let $A,B\subset K$ be finite sets such that $A$ and $B$ are separated. If $G$ is the visibility graph of $A\cup B$ with respect to $K$, and $G$ is $K_{s,s}$-free, then there are $O(s(|A|+|B|))$ edges between $A$ and $B$.
\end{lemma}

\begin{proof}
Order $A\cup B$ in clockwise order on the curve $K$ such that the points of $A$ are before the points of $B$, then this defines an ordering $<$ of $G$ with $A<B$. 

Say that an ordered bipartite graph $H$ is a \emph{double cherry} if it has the following form. The vertex classes of $H$ are $\{1,2,3\}$ and $\{4,5,6\}$, the pairs  $\{2,4\},\{2,6\},\{1,5\},\{3,5\}$ are edges, and $\{2,5\}$ is not an edge. The rest of the pairs between the two vertex classes can be either edges or non-edges. See Figure \ref{fig:double_cherry} for an illustration. It is proved in \cite{AK25} that a curve visibility graph does not contain a bipartite-induced copy of a double cherry.

 Define a collection $\mathcal{F}$ of horizontal and vertical segments in the plane as follows. Let $a_1<\dots<a_m$ be the elements of $A$, and $b_1<\dots<b_n$ be the elements of $B$. For every $k\in [m]$, add to $\mathcal{F}$ the closed vertical segment with endpoints $(k,\ell)$ and $(k,\ell')$, where $b_{\ell}\in B$ is the first neighbour of $a_k$, and $b_{\ell'}\in B$ is the last neighbour with respect to $<$. If $a_k$ has does not have neighbours in $B$, do not add anything. Also, for every $\ell\in [n]$, add to $\mathcal{F}$ the open horizontal segment with endpoints $(k,\ell)$ and $(k',\ell)$, where $a_{k}\in A$ is the first neighbour of $b_{\ell}$, and $a_{k'}\in A$ is the last neighbour with respect to $<$. Then $\mathcal{F}$ contains at most $|A|+|B|$ segments. 

 Let $Q$ be the intersection graph between the horizontal and vertical segments. Then $Q$ contains at least $e(G[A, B])$ edges. Indeed, if $a_ib_j$ is an edge of $G$, then there exist $a_{i_1},a_{i_2}\in A$ and $b_{j_1},b_{j_2}\in B$ with $i_1\leq i\leq i_2$ and $j_1\leq j\leq j_2$ such that $a_{i_1}$ is the first neighbour of $b_j$ and $a_{j_2}$ is the last, and similarly for $b_{j_1}$ and $b_{j_2}$. In this case, the edge $a_ib_j$ corresponds to the intersection of the horizontal segment with endpoints $(i_1,j), (i_2,j)$ and the vertical segment with endpoints $(i,j_1), (i,j_2)$, both of which belong to $\cF$. Note that these two segments intersect in the point $(i,j)$, and therefore every intersection of $Q$ corresponds to an edge of $G[A, B]$.

\begin{claim}
If a horizontal and a vertical segment in $\mathcal{F}$ intersect in some point $(i,j)$, then $(a_i,b_j)$ is an edge of $G$.
\end{claim}

\begin{proof}
Let $(i,j_1)$ and $(i,j_2)$ be the endpoints of the horizontal segment, and $(i_1,j)$ and $(i_2,j)$ be the endpoints of the vertical segment. By the definition of the segments, we know $a_{i_1}b_j,a_{i_2}b_j,a_ib_{j_1},a_{i}b_{j_2}$ are edges of $G$. If $a_ib_j$ is not an edge of $G$, then we must have $i_1<i<i_2$ and $j_1<j<j_2$. But then $G$ contains a bipartite-induced copy of a double cherry with vertices $a_{i_1}, a_i, a_{i_2}, b_{j_1}, b_j, b_{j_2}$, which is impossible.
\end{proof}

From the previous claim, we deduce that if $G$ is $K_{s,s}$-free, then $Q$ is also $K_{s,s}$-free. But then, $Q$ has $O(s(|A|+|B|))$ edges by Proposition \ref{prop:vertical vs horizontal}, which gives that $e(G[A,B])\leq e(Q)\leq O(s(|A|+|B|))$. 
\end{proof}


\begin{theorem}
Let $G$ be an $n$-vertex visibility graph with respect to an $x$-monotone Jordan curve $K$. If $G$ is $K_{s,s}$-free, then $G$ has $O(sn)$ edges.
\end{theorem}

\begin{proof}
Let $P\subset K$ be the vertex set of $G$. If $K$ is an $x$-monotone Jordan curve, let us denote by $x_\ell, x_r$ (one of) its leftmost and rightmost points. Then, two internally disjoint arcs of $K$ join $x_\ell$ and $x_r$ -- let us denote them by $K_\ell$ and $K_{u}$, standing for the \textit{lower} and the \textit{upper} part of $K$, respectively. Then $K_{\ell}$ and $K_u$ are $x$-monotone curves, i.e. curves such that every vertical line intersects them in at most one point. Let $P_{\ell}=P\cap K_{\ell}$ and $P_u=P\cap K_u$. By Lemma \ref{lemma:visibility1}, we have $e(G[P_{\ell},P_u])=O(sn)$. We prove that $e(G[P_{\ell}])=O(sn)$ holds as well, which, by symmetry, implies $e(G[P_{u}])=O(sn)$ and finishes the proof.

Let $G'=G[P_{\ell}]$, and order the elements of $P_{\ell}$ from left to right, this gives an ordering of $G'$. Let $\mathcal{M}$ be the family of ordered bipartite graphs $M$ of the following form: the vertex classes of $M$ are $\{1,2,3\}$ and $\{4,5,6\}$, the pairs $\{1,6\}$, $\{2,4\}$, $\{3,5\}$ are edges of $M$, but $\{2,5\}$ is not an edge.

\begin{claim}\label{claim:x monotone}
    $G'$ contains no bipartite-induced copy of a member of $\mathcal{M}$. 
\end{claim}

\begin{proof}
Assume that $p_1<p_2<p_3<q_1<q_2<q_3$ induces a bipartite-induced copy of some $M\in\mathcal{M}$ in $G'$. Then $p_1q_3$ is an edge. This means that the part of $K_{\ell}$ between the points $p_1$ and $q_3$ is below the segment $p_1q_3$, and $K_{u}$ is above this segment. Furthermore, $p_2q_1$ is also an edge of $G'$, so the part of $K_{\ell}$ between $p_2$ and $q_1$ is below $p_2q_1$. This is also true for $p_3$ and $q_2$. But then the segment $p_2q_2$ cannot intersect $K_{\ell}$ as it is above every point of $p_2q_1\cup p_3q_2$, and it also cannot intersect $K_u$ as it is below $p_1q_3$. Hence, $p_2q_2$ is an edge as well, contradiction.
