\vspace{-0.5cm}
\begin{theorem}
Let $G$ be an $n$-vertex visibility graph with respect to a star-shaped Jordan curve $K$. If $G$ is $K_{s,s}$-free, then $G$ has $O(sn)$ edges.
\end{theorem}

\begin{proof}
Let $P\subset K$ be the vertex set of $G$. Let $c\in K^*$ be a point such that every half-line starting at $c$ intersects $K$ in at most one point. Let $\ell$ be an arbitrary line through $c$, then $\ell$  intersects $K$ in exactly two points. Therefore, $\ell$ cuts $K$ into two parts, $K_1$ and $K_2$, let $P_i=K_i\cap P$ for $i=1,2$. By Lemma~\ref{lemma:visibility1}, we have $e(G[P_1,P_2])=O(sn)$. We prove that $e(G[P_{i}])=O(sn)$ holds as well for $i=1,2$, then we are done. By symmetry, it is enough to consider $P_1$.

Let $G_1=G[P_{1}]$, and order the elements of $P_{1}$ in clockwise direction starting from the one of the endpoints of $K_1$. This gives an ordering of $G_1$. Let $\mathcal{M}$ be the family of ordered bipartite graphs $M$ of the following form: the vertex classes of $M$ are $\{1,2\}$ and $\{3,4\}$, the pairs $\{1,3\}$ and $\{2,4\}$ are edges, but $\{1,4\}$ is not an edge.

\begin{claim}\label{claim:star-shaped}
    $G_1$ contains no bipartite-induced copy of a member of $\mathcal{M}$. 
\end{claim}

\begin{proof}
\begin{figure}[h]
    \centering
    \vspace{-0.2cm}
    \begin{tikzpicture}[scale=0.7]
        \node[vtx, label=left:$c$] (c) at (0, 0) {};
        \node[vtx, label=below:$p_1$] (p1) at (0.7,-1.7) {};
        \node[vtx, label=right:$p_2$] (p2) at (2,-1) {};
        \node[vtx, label=right:$q_1$] (q1) at (2.3,1) {};
        \node[vtx, label=above:$q_2$] (q2) at (1.3,2) {};

        \draw[thick] ($(p1)+(-1, 0)$) to[out=0, in=-140] (p1) to[out=40, in=-120] (p2) to[out=60, in=180] ($(p2)+(1, 0.5)$) to[out=0, in=-45] (q1) to[out=135, in=-40] (q2) to[out=140, in=0] ($(q2)+(-1, 0)$);

        \draw[thick] (p1) -- (q1);
        \draw[thick] (p2) -- (q2);
        \draw[thick, dashed] (p1) -- (q2);
    \end{tikzpicture}
    \vspace{-0.3cm}
    \caption{Illustration of proof of Claim~\ref{claim:star-shaped}.}
    \vspace{-0.3cm}
    \label{fig:star-shaped}
\end{figure}
Assume that $p_1<p_2<q_1<q_2$ induces a bipartite-induced copy of some $M\in\mathcal{M}$ in $G_1$. Then $p_1q_1$ and $p_2q_2$ are edges. Consider the 4 half-lines starting from $c$ and going through $p_1,p_2,q_1,q_2$, denote them by $\ell_1,\ell_2,\ell_3,\ell_4$. These half-lines follow a clockwise order. The intersection point of $\ell_2$ and the segment $p_1q_2$ must be before $p_2$, using that $K$ is star-shaped. Similarly, the intersection of $\ell_3$ and $p_2q_2$ is before $q_1$. This implies that $p_1q_1$ and $p_2q_2$ intersect in some point $x$, and the quadrilateral $cp_1xq_2$ is convex and is contained in $K^*$. But then $p_1q_2$ is contained in $K$, which means that $p_1q_2$ is an edge of $G_1$, contradiction.
\end{proof}

Let $M\in\mathcal{M}$ be the unique member with $\{2,3\}$ being a non-edge. Then $M$ is a matching, and the bipartite complement of $M$ is also a matching. Let $\mathcal{F}$ be the family of graphs $H$ which have an ordering such that  $H$ does not contain a bipartite-induced copy of $M$. Then $\mathcal{F}$ is a hereditary family of graphs and $G_1\in\mathcal{F}$. Moreover, $\mathcal{F}$ is degree-bounded by Theorem \ref{thm:matching_degree_bounded}, and it has the density-EH property by Theorem \ref{thm:matching_EH}. Therefore, by Theorem \ref{thm:master}, every $n$ vertex $K_{s,s}$-free member of $\mathcal{F}$ has $O(sn)$ edges, so this holds for $G'$ as well. This finishes the proof.
\end{proof}

