\begin{lstlisting}[language=SPARQL, caption={SPARQL query for the competency question C6.3}, label={lst:C6.3}, basicstyle=\ttfamily\scriptsize, breaklines=true, frame=single, columns=flexible, numbers=left, float=h]
PREFIX hpc: <http://ontology.hpc.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hpcSystem ?systemName (AVG(?execTimeSeconds) AS ?avgExecutionTimeSeconds)
WHERE {
  ?hpcSystem a hpc:HPCSystem ;
             hpc:systemName ?systemName ;
             hpc:hasRack ?rack .
  ?rack hpc:hasComputeNode ?computeNode .
  ?job hpc:usesComputeNode ?computeNode ;
       hpc:hasJobStartTime ?startTime ;
       hpc:hasJobEndTime ?endTime .
  ?startTime hpc:timestamp ?startTimestamp .
  ?endTime hpc:timestamp ?endTimestamp .

  BIND(
    ( xsd:dateTime(?endTimestamp) - xsd:dateTime(?startTimestamp) ) * 86400 AS ?execTimeSeconds
  )
}
GROUP BY ?hpcSystem ?systemName
ORDER BY ?hpcSystem
\end{lstlisting}

