\section{Our Contribution}
\label{sec:contribution}
\begin{theorem}
\label{thm:finite-S}
Under the line aspect ratio assumption (Definition~\ref{assumme:AR1}), there exists a finite set $\mathcal{S}$ on $\overline{xy}$ such that:

$$|\mathcal{S}| \text{ is bounded by } \text{AR}$$
%%%% #1 %%%5 $|\S| \in poly(n)$, where $n$ is the complexity of $\P$.
$$
\overline{uv} \subseteq \bigcup_{s \in \mathcal{S}} \text{VP}(s)
$$
\end{theorem}

\begin{proof}
The size of $\mathcal{S}$ is determined by $\text{AR} = LW/SW$:
\begin{enumerate}
    \item The slicing approach (Section~\ref{subsec:slicing-algorithm}) decomposes $\overline{uv}$ into visibility intervals.
    \item By Lemma \ref{lem:covering-target}, the points in $\S$ cover the target.
    \item Observation~\ref{obs:I-larger-SW} establishes that each interval has length $\geq SW$.
    \item Since $\overline{uv}$ has maximum length $LW$, the number of intervals is $\leq \frac{LW}{SW} = \text{AR}$.
\end{enumerate}
Thus $|\mathcal{S}|$ is finite and bounded by $\text{AR}$. 
\end{proof}

