The total number of transactions between nodes with a given value $\rho \in \{0, \dots,N\}$ of reciprocity is defined as
\begin{equation} \label{eq:tro}
            T_\rho = \sum_{i \in \mathcal{N}} \eta_{i\rho}  \sum_{j \in \mathcal{N}} \delta_{ij} \delta_{ji}(e_{ij} + e_{ji}),
        \end{equation}
where $\eta_{i\rho} \in \{0,1\}$ is given by
\begin{equation}
\eta_{i\rho} = 1 \iff \{r_i=\rho\}.  
\end{equation}
\noindent Analogously, the total volume of transactions between  nodes with a given value $\rho$ of reciprocity is defined by 
\begin{equation} \label{eq:vro}
    v_\rho = \sum_{i \in \mathcal{N}} \eta_{i\rho} \sum_{j \in \mathcal{N}} \delta_{ij} \delta_{ji} (w_{ij} + w_{ji}).
\end{equation}

