\section{Bounding CREW-PRAM Time in the Presence of Uncertainty}\label{app:cooknisanun}

The folklore "pointer-doubling" technique used by Nisan \cite{Nisan91} to prove that CREW-PRAM time complexity is at most $\log_2(\depth(f))$ can be adapted easily to show that CREW-PRAM time complexity of $\uf$ is at most $\log_2(\depth_\un(f))$.

For completeness, we show Cook, Dwork, and Reischuk's \cite{CDR86} lower bound on the time required by a parallel random access machines without concurrent writes in terms of sensitivity of the function can also be extended. They proved that any PRAM (as defined below) computing a function $f$ requires at least $\log_bs(f)$ steps where $b = \frac{1}{2}(5 + \sqrt{21})$. In this section we shall extend this result to say that any CREW-PRAM require at least $\log_b{\sen_\un(f)}$ time to compute $\uf$.

\begin{definition}[PRAM]
    A PRAM consists of a set $\Pi  = \{P(1), P(2), \cdots\}$ of processors, a set $\Gamma = \{M(1), M(2), \}$ of cells, an alphabet $\Sigma$, a number $n$ of inputs, and an execution time $T$. Each processor $P(i)$ consists of a state set $Q_i$ (any of the sets $\Pi, \Gamma ,\Sigma, Q_i$ may be infinite), and functions $\rho_i: Q_i\rightarrow \mathbb{N}^{+}, \tau_i: Q_i \rightarrow \mathbb{N}, \sigma_i: Q_i \rightarrow \Sigma $ and $\delta_i: Q_i \times \Sigma \rightarrow Q_i$. Here for any $q \in Q_i$, $\rho_i(q)$ decides the memory index to be read, $\delta_i$ represents the state transition function that changes the state of $P_i$ based on the previous state and the  alphabet read, $\tau_i(q)$ represents the memory index to be written into next and $\sigma_i(q)$ is the alphabet that will be written in that memory index next. ($\tau_i(q)$ indicates that no cell is written into)

    At each time $t= 0, 1,. ., T$ each processor $P(i)$ is in a state $q \in Q_i$ and each cell $M(i)$ contains a symbol $s_{i}^t \in \Sigma$. At time $t = 0$, cells $M(1),..., M(n)$ contain the inputs $X_1,\cdots,X_n$. That is, $s_{i}^t  = X_i \forall i \in [n]$, and $s_{i}^0 = b_0 \forall i>n$, where $b_0$ is some distinguished (blank) member of $\Sigma$. All processors are initially in the distinguished state $q_0$  i.e. $q_{i}^0 = q_0 \forall i$. In general,
    $$q_{i}^{t+1} = \delta_i(q_{i}^t, s_{j}^t)$$
    for all processors $P(I)$ where the index read is $j = \rho_i(q_i^t)$

    \[
        s_{k}^{t+1} = \begin{cases}
            \sigma_i(q_{i}^{t+1}) & \textrm{ if $k = \tau_i(q_{i}^{t+1})$} \\
            s_{k}^t & \textrm{ otherwise} 
        \end{cases}
    \]

    It is a condition of correctness of the PRAM (expressing the constraint of not allowing concurrent writes) that for $t = 0, 1,. , T- 1$, $\tau_{j}(q_{j}^{t+1})$ and $\tau_{k}(q_{k}^{t+1})$  are either both zero or distinct for all $j \neq k$. The value $f(X1,\cdots, Xn)$ of the function $f$ computed by the PRAM is the contents $s_{1}^T$ of cell $M(1)$ at time $T$.
\end{definition}

For an input string $I \in \zuon$, we denote by $I(i)$ that 2 strings which differs from I exactly at position $i$. We use $I(i, b_i)$ to denote the string that differs from $I$ exactly at position $i$ by the bit $b_i$.

\begin{definition}
    An index $i$ affects a processor $P$ (and respectively, a cell $M$) at time $t$ with $I$ iff the state of $P$ (and respectively the content of $M$) at input configuration $I$ differs from the state of $P$ (and respectively the content of $M$) for any of the inputs configurations in $I(i)$.

    Index-bit pair $(i, b_i)$ affects  a processor $P$ (and respectively, a cell $M$) at time $t$ with $I$ iff the state of $P$ (and respectively the content of $M$) at input configuration $I$ differs from the state of $P$ (and respectively the content of $M$) for $I(i, b_i)$.    
\end{definition}

\begin{theorem}
    If $f: \{0, 1, \un\}^n \rightarrow \{0, 1, \un\}$ has $\sen_\un(f)$ as its sensitivity then any PRAM computing it will require at least $\log_b \sen_un(f)$ time to compute it.
\end{theorem}

\begin{proof}
    Let $K(P, t, i)$ (respectively, $L(M, t, i)$)  be the set of input indices which affect processor $P$ (respectively,  memory cell $M$) at with $I$. Let $K_t, L_t$, satisfy the recurrence equations:
    \begin{enumerate}
        \item $K_0 = 0$
        \item $L_0 = 1$
        \item $K_{t+1} = K_{t} + L_{t}$
        \item $L_{t+1} = L_{t} + 3K_{t+1}$
    \end{enumerate}

    As proven in \cite{CDR86}, the solution to these equations is $$K_{t} = \frac{b^t}{\sqrt{21}} - \frac{\Bar{b}^t}{\sqrt{21}}, L_{t} = \frac{3 + \sqrt{21}}{2\sqrt{21}}b^t + \frac{-3 + \sqrt{21}}{2\sqrt{21}}\Bar{b}^t$$
    where $b = \frac{1}{2}(5+\sqrt{21}), \Bar{b} = \frac{1}{2}(5 - \sqrt{21})$. Consider the input $I$ with the maximum sensitivity, we know that at $T$ all the $\sen_\un(f)$ bits affect the content of $M(1)$ and hence $|L(M(1), I, T)| = \sen_\un(f)$. By the below lemma, we can say that $$\sen_\un(f) \le L_{T} \le b^T \implies T \ge \log_b \sen_un(f)$$

    \begin{lemma}
        $|K(P, I, t)| \le K_{t}$ and $|L(M, I , t)| \le L_{t}$ for all $P, M, t$ and $I$
    \end{lemma}
    We now prove the above lemma by induction as follows:
    \begin{description}
        \item[Hypothesis:] $|K(P, I, t)| \le K_{t}$ and $|L(M, I , t)| \le L_{t}$ for all $P, M, I$ at time $t$
        \item [Base case:] At $t = 0$, we know that $K(P, I, 0) = 0$ and $L(M, I, 0) = 1$

        \item [Induction step:]
        \begin{enumerate}
            \item Consider $K(P, I, t+1)$. Any index $i$ that affects $P$ at time $t+1$ would have either affected $P$ at time $t$ or it would change the cell $M(\rho_i(q_{i}^t))$ that it would've read from (it is the same cell $P$ would've read from for input configuration $I$ at time $t$). Hence we know that $K(P, I, t+1) \subseteq K(P, I, t) \cup L(M, I, t)$. This satisfies $|K(P, I, t+1)| \le |K(P, I, t)|+ |L(M, I, t)| \le K_t + L_t = K_{t+1}$

            \item Now let us consider $L(M, I, t+1)$. We have the following 2 cases:

            \begin{description}
                \item[Case 1:] Suppose that for the input configuration $I$, some processor $P$ writes into $M$. Any index $i$ that affects $M$ at $t+1$ would definitely affect $P$ at time $t+1$ (if not then $P$ would've written the same alphabet into $M$). Hence we have $L(M, I, t+1) \subseteq K(P, I, t+1)$ and hence $|L(M, I, t+1)| \le K_{t+1} \le L_{t+1}$ since $K_t, L_t$ are non negative for all $t$.
                \item[Case 2:] If no processor had written into $M$, then index $i$ (say by the change to a bit $b_i$) would affect $M$ at $t+1$ it it had either affected it at $t$ or if it causes some processor to write into $M$ at time $t$. Say $Y(M, I, t+1)$ denotes the number of indices that when changed to any of the other bits makes some processor $Q$ write into $M$. Then we know that $L(M, I, t+1) \subseteq L(M, I, t) \cup Y(M, I, t+1)$. We shall upper bound $|Y|$ using the following lemma by $K_{t+1}$. Hence we have $|L(M, I, t+1)| \le |L(M, I, t)| + Y(M, I, t+1)| \le L_{t} + 3K_{t+1} = L_{t+1}$
            \end{description}
        \end{enumerate} 
    \end{description}

    \begin{lemma}
        Suppose $M$ is not written into by any processor at $t+1$ for the input configuration $I$ then $Y(M, I, t+1) \le 3K_{t+1}$
    \end{lemma}
    Consider $Y(M, I, t+1) = \{(u_1, b_1), ..., (u_r, b_r)\}$ where any $I(u_i, b_i)$ is the input where the index $u_i$ (all the indices are unique) has its bit replaced by $b_i$ and this makes $Q_i$ write into $M$. If there are multiple possible $b_i$'s for a $u_i$ we pick any one. 

    \begin{observation}
        Note that if $Q_i \neq Q_j$ then either $(u_i, b_i)$ affects $Q_j$ at $t+1$ for input $I(u_j, b_j)$ or $(u_j, b_j)$ affects $Q_i$ at $t+1$ for input $I(u_i, b_i)$
    \end{observation}
    This happens simply because if not, for the input $I(u_i, b_i)(u_j, b_j)$ both $Q_i$ and $Q_j$ are going to write to $M$.

    In order to bound $r$ we shall create the bipartite graph with vertices $(u_1, b_1), \cdots, (u_r, b_r)$ and $(v_1, b_1), \cdots, (v_r, b_r)$. There is an edge between $(u_i, b_i)$ and $(v_j, b_j)$ if and only if $(u_i, b_i)$ affects $Q_j$ for $I(v_j, b_j)$ at $t+1$. Consider the in-degree of $(v_j, b_j)$, note that it can only be at most $K(Q_j, I(v_j, b_j), t+1)$ since all the $(u_i, b_i)$ pairs affecting it have unique indices. Hence we have $$e \le r K(Q_j, I(v_j, b_j), t+1) \le rK_{t+1}$$
    We shall use the observation above to lower bound $e$ by the number of pairs $((u_i, b_i), (u_j, b_j))$ that lead to different processors writing to $M$. For a fixed $(u_i, b_i)$ there can be at most $K(Q_i, I, t+1)-1$ other pairs that affect $Q_{i}$. Hence there are at least $r-|K_(Q_i, I, t+1)|$ pairs that will cause some other processor to write into $M$ (note that $Q_i$ has to be affected in order to write into $M$). We have

    $$\frac{1}{2}r(r - K_{t+1}) \le \frac{1}{2}r(r - |K_(Q_i, I, t+1)|) \le e$$

    Hence we have $\frac{1}{2}r(r - K_{t+1}) \le rK_{t+1} \implies r \le 3k_{t+1}$
\end{proof}



\section{Alternative Definitions for Sensitivity of Hazard-free Extensions}\label{app:alternative-sen}

We consider two other natural definitions of sensitivity for hazard free extensions and prove that they are linearly equivalent to the definition of sensitivity for hazard-free extensions used in this paper.


\newcommand{\stabs}{\mathsf{stbs}}
In the following definition, we consider a bit to be sensitive if for some input, we can change the value of that bit from $0$ or $1$ to $\un$ and make the output of the function $\un$.
\begin{definition}[Stable Sensitivity]
Let $f$ be the hazard-free extension of some $n$-input Boolean function. For an $x\in \{0, \un, 1\}^n$ such that $f(x)$ is stable, we define the stable sensitivity $\stabs(f,x)$ of $f$ at $x$ as the number of bits that can be made unstable (individually) so that $f(x)$ is unstable. 
$$\stabs(f) = \max_{x : \textrm{$f(x)$ is stable}} \stabs(f,x)$$
\end{definition}

\newcommand{\slys}{\mathsf{stys}}
In the following definition, we consider a bit to be sensitive for some input if switching the value from a certain to uncertain value changes the output from certain to uncertain or vice-versa.
 For $B \subseteq [n], x \in \{0,1,\un\}^n$, we define $x \oplus B = \{ y \in \{0,1,\un\}^n \mid \forall i \in B, x_i = \un \iff y_i \neq \un$.
 %, x_i \neq \un \iff y_i = \un\}$.
\begin{definition}[Stability Sensitivity]
    Let $f$ be the hazard-free extension of some $n$-input Boolean function. For an $x\in \{0, \un, 1\}^n$, the Stability Sensitivity at the input $x$, denoted by $\slys(f,x)$, is defined as:
    $$\slys(f,x) = \left| \left\{ i : \begin{array}{l} \exists y \in x \oplus \{i\},     f(x) = \un \iff f(y) \neq \un
    \end{array}
    \right\} \right|$$
    The Stability Sensitivity of $f$, $\slys(f)$ is then defined as :
    $$\slys(f) = \max_{x \in \{0,1,\un\}^n} \slys(f,x)$$
\end{definition}

We shall prove that these measures of sensitivity $\stabs(f), \slys(f)$ are at polynomially related to $\sen(f)$ for any hazard free extension $f$. In fact, similar to the relation between $\sen_\un(f), \bsen_\un(f)$ and $\cc_\un(f)$ they are also away from $\sen(f)$ by a factor of at most 2. We use the notation $\stabs_\un^{(b)}, \slys_\un^{(b)}$ where $b\in \{0, 1\}$ to denote sensitivities for inputs that yield a $b$ output and $\slys_\un^{(u)}$ to denote Stability Sensitivity for inputs that yield a $\un$ output.

\begin{claim}
    Let $f$ be the hazard -free extension of some $n$-bit Boolean function. Then, $ \stabs^{(b)}(f) = \slys^{(b)}(f) = \sen_\un^{(b)}(f)$ for $b \in \{0, 1\}$ and $\slys^{(u)}(f) \le \sen_\un^{(u)}(f)$
\end{claim}
\begin{proof}
    It is easy to see that for any $x \in \zuon, b \in \{0, 1\}$ such that $f(x) = b, \stabs(f, x) = \slys(f, x) \le \sen_\un(f, x)$ and for any input $x$ such that $f(x)  = \un, \slys(f, x) \le \sen_\un(f, x)$.
    From ~\ref{thm:senstr} we know that $\sen_\un^{(1)}(f)$ occurs at the input $x$ that corresponds to the largest sized prime implicant (or implicate for $\sen_\un^{(0)}$) or the minimum sized maximal monochromatic subcube where all the stable bits are sensitive. Hence at this input $\stabs^{(1)}(f, x) = \sen_\un^{(1)}(f, x) = \sen_\un^{(1)}(f)$ and by a similar argument for $\stabs^{(0)}$ we have $ \stabs^{(b)}(f) = \slys^{(b)}(f) = \sen_\un^{(b)}(f)$ for $b \in \{0, 1\}$
\end{proof}
Since we already know that $\sen_\un^{(u)}(f) \le \sen_\un^{(0)}(f) + \sen_\un^{(1)}(f) - 1$, we know that $\frac{\sen_\un(f)}{2} \le \stabs(f) \le \slys(f) \le \sen_\un(f)$ thus proving that these notions of sensitivity are at most a factor of 2 away from our choice of sensitivity and thus they would all satisfy the Sensitivity Conjecture.



