\section{Prior Work}
In this section, we discuss work related to our results. 

The below theorem uses the generalized definition of the ECC, that takes a general filtration rather than being restricted to a height function.
\begin{theorem}[Dłotko \& Gurnari~\cite{dlotko2023euler} Proposition 2] \label{lowerbound}
Given geometric simplicial complexes $K_1, K_2$, with filtrations $\mathcal{F}$ and $\mathcal{G}$ respectively, then the $L_1$ distance of the Euler Characteristic Curves between them is bounded by the Wasserstein distance between the filtrations.
\begin{equation*}
    {\|\ECC_\mathcal{F}(K_1)-\ECC_\mathcal{G}(K_2)\|_1 \leq 2W_{1,\infty} (\Dgm(\mathcal{F}(K_1)),\Dgm(\mathcal{G}(K_2))}
\end{equation*}
\end{theorem}
This result gives a relationship between the ECC of a complex with a filtration and the persistence diagrams obtained from the same filtration. 
We can further restrict the filtration to be the height function in a direction, making it suitable for the ECT.
\begin{equation*}
%
%
   {\|\ECC_\nu(f(K)) - \ECC_\nu(g(K))\|_1 \leq 2W_{1,\infty}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)})).}
\end{equation*}

The next theorem uses the $W_{1,1}$ distance, as opposed to the $W_{1,\infty}$.
We also restrict the bound to only include embeddings of the same abstract simplicial complex, as that is a requirement for the next result we present.
\begin{theorem}[{Skraba \& Turner~\cite[Thm.~5.5]{skraba2020wasserstein}}] \label{upperbound}
Let $K$ be an abstract simplicial complex, and let $\omega_{d-2}$ denote the area of $ \mathbb{S}^{d-2}$. Given two embedding functions, $f,g:K\longrightarrow\R^d$, let $$C_d = 2 \omega_{d-2} \int_0^\frac{\pi}{2}\cos(\theta)\sin^{d-2}(\theta)d\theta \text{ and } C_K = \max\limits_{{v \in V(K)}} |\{ \sigma \;|\; v \in \sigma \}  |. $$
Then
\begin{equation*}
%
           {\int_{\nu\in S^{d-1}}W_{1,1}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)})) d\nu \leq C_K C_d \sum_{v\in V(K)}\|f(v) - g(v)\|_2}.
\end{equation*}
\end{theorem}

While the two results utilize two different Wasserstein distances, they are closely related.
This difference is remedied via the following theorem.
\begin{theorem}[Turner~\cite{turner_medians_2020}]
For any two given persistence diagrams, $\Dgm(\mathcal{F})$ and $\Dgm(\mathcal{G})$,
\begin{equation*}
    W_{p,\infty}(\Dgm(\mathcal{F}),\Dgm(\mathcal{G}))\leq W_{p,p}(\Dgm(\mathcal{F}),\Dgm(\mathcal{G})) \leq 2W_{p,\infty}(\Dgm(\mathcal{F}),\Dgm(\mathcal{G}))
\end{equation*}
\end{theorem}


We want to use these two results to bound the distance between the Euler Characteristic Transforms based on the distance of two embedding functions of the same abstract complex. 
We propose the following metric on the space of ECT functions, building on the $L_1$ norm. 
\begin{defn}[ECT Distance~\cite{curry2022many}]
    Given two embeddings of the same abstract simplicial complex $K$, the distance between the Euler Characteristic Transform of each is defined as 
    $$d_{\ECT}(ECT(f(K)),ECT(g(K))) := \underset{\nu\in \mathbb{S}^{d-1}}{\int} \|\ECC_\nu(f(K)) - \ECC_\nu(g(K))\|_1 \ d\nu.$$
\end{defn}
Here, the distance is a metric, as embeddings of the same abstract simplicial complex are guaranteed to have the same Euler Characteristic when the filtrations are complete and will therefore produce a finite distance in every direction. 
Thus, all we require is the following lemma to establish that this is indeed a metric. 
\begin{lemma}
\label{IntOfMetricSd-1}
 Let $\rho$ be a metric on a space of $\mathcal{L}^p(\R)$ functions $\R \to \R$. 
 For $a,b:\mathbb{S}^{d-1} \times \R \to \R$ we denote $a_\nu(t) = a(\nu,t)$ so that $a_\nu: \S^{d-1} \to \R$. 
 Then
 $\rho'(a,b) :=\underset{\mathbb{S}^{d-1}}{\int} \rho(a_\nu,b_\nu))\,d\nu$,
 if it exists, is also a metric.
 %
\end{lemma}

\begin{proof}
%
%
%
%
%
%
By the non-negativity of $\rho$, the integrand $\rho(a_\nu, b_\nu)$ is non-negative over the domain $\mathbb{S}^{d-1}$, so $\rho'(a, b) \geq 0$. Moreover, $\rho'(a, b) = 0$ if and only if $\rho(a_\nu, b_\nu) = 0$ for all $\nu \in \mathbb{S}^{d-1}$, which occurs if and only if $a(\nu, t) = b(\nu, t)$ for all $\nu$. Hence, $\rho'(a, b) = 0$ if and only if $a = b$.

For the symmetry property, we have:
\[
\rho'(a, b) = \int_{\mathbb{S}^{d-1}} \rho(a_\nu, b_\nu)\, d\nu = \int_{\mathbb{S}^{d-1}} \rho(b_\nu, a_\nu)\, d\nu = \rho'(b, a),
\]
where we used the symmetry of $\rho$.

To verify the triangle inequality, note that for each $\nu \in \S ^{d-1}$,
\[
\rho(a(\nu, t), c(\nu, t)) \leq \rho(a_\nu, b_\nu) + \rho(b(\nu, t), c(\nu, t)).
\]
Integrating both sides over $\S ^{d-1}$ yields:
\begin{align*}
\rho'(a, c) &= \int_{\S ^{d-1}} \rho(a_\nu, c_\nu)\, d\nu \\
&\leq \int_{\S ^{d-1}} \left[ \rho(a_\nu, b_\nu) + \rho(b_\nu, c_\nu) \right]\, d\nu \\
&= \int_{\S ^{d-1}} \rho(a_\nu, b_\nu)\, d\nu + \int_{\S ^{d-1}} \rho(b_\nu, c_\nu)\, d\nu \\
&= \rho'(a, b) + \rho'(b, c).
\end{align*}

Therefore, $\rho'$ satisfies non-negativity, identity of indiscernibles, symmetry, and the triangle inequality, so it is a metric.
\end{proof}


We similarly establish this same integral-metric property for $\R$, and thus implicitly for compact subsets of $\R$. 
