\section{Results}
%
In this section, we present our main stability result for the $\ECT$, showing that it is stable with respect to embedding distance. 
\begin{theorem}\label{thm:ectstablity}
Let $K$ be  an abstract simplicial complex $K$ with vertex set $V(K)$. 
Let
$$C_d = 2 \omega_{d-2} \int_0^\frac{\pi}{2}\cos(\theta)\sin^{d-2}(\theta)d\theta
\qquad \text{and }\qquad 
C_K = \max\limits_{{v \in V(K)}} |\{ \sigma \in K \mid v \in \sigma \}  |.$$ 
Then given two embeddings 
$$
f: K \rightarrow \R^d \text{ and } g:K \rightarrow \R^d$$
we have that
$$
d_{\ECT}\big{(}ECT(f(K)), ECT(g(K))\big{)} 
\leq 
2 C_K C_d \sum_{v\in V(K)}\|f(v) - g(v)\|_2.
$$
   %
\end{theorem}

\begin{proof}
Let $h_\nu$ denote the height function in direction $\nu$, and let $h_\nu^{f(K)}$ denote the filtration of $f(K)$ induced by $h_\nu$. 
From Theorem \ref{lowerbound}, %
we have that 
\begin{equation}
\label{eqn:frompolish}
%
{\|\ECC_\nu(f(K)) - \ECC_\nu(g(K))\|_1 \leq 2W_{1,\infty}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)})).}
\end{equation}
From Theorem \ref{upperbound}, %
we have that 
\begin{equation}%
\label{eqn:fromscary}
{\int_{\nu\in S^{d-1}}W_{1,1}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)})) d\nu \leq C_K C_d \sum_{v\in V(K)}\|f(v) - g(v)\|_2}.
\end{equation} 
Since by Lemma \ref{upperbound} %
we know that for any persistence diagrams $\Dgm(K_1), \Dgm(K_2)$, 
$$W_{1,\infty}(\Dgm(K_1), \Dgm(K_2)) \leq W_{1,1}(\Dgm(K_1), \Dgm(K_2)), $$
it follows that 
$$2W_{1,\infty}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)}))\leq 2W_{1,1}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)})).$$
Integrating \eqref{eqn:frompolish} over $\S ^{d-1}$, and multiplying \eqref{eqn:fromscary} by two we obtain
\begin{align*}
   d_{\ECT}\big{(}\ECT(f(K)), \ECT(g(K))\big{)} &
   = \underset{\nu\in \S ^{d-1}}{\int}\|\ECC_\nu(f(K)) - \ECC_\nu(g(K))\|_1 d\nu \\
   &\leq \underset{\nu\in \S ^{d-1}}{\int}2W_{1,\infty}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)})) d\nu\\
   &\leq 2\int_{\nu\in S^{d-1}}W_{1,1}(\Dgm(h_\nu^{f(K)}),\Dgm(h_\nu^{g(K)})) d\nu\\
   &\leq 2 C_K C_d \sum_{v\in V(K)}\|f(v) - g(v)\|_2.
\end{align*}
\end{proof}

\section{$\SELECT$ Stability}
In this section, we define and extend this bound to $\SELECT$ as an extension of the $\ECT$ adapted to piecewise linear functions. 
Specifically, we say that $f: \R^d \to \R$ is a in $\PL(\R^d)$ if it is continued, supported on a finite geometric simplicial complex $K$, and the values of on the faces of $K$ are determined by linear interpolation of the vertices spanning the face. 
We also denote the set of continuous functions $g: X \to Y$ by $\Func(X,Y)$.
First, we define the Lifted Euler Characteristic Transform ($\LECT$).
Note that while 
\begin{defn}[\cite{kirveslahti2024representing}]
For piecewise linear functions $f: \R ^d \rightarrow \R $, the \emph{Lifted Euler Characteristic Transform} is given by a map
\begin{equation*}
\LECT: \PL(\R ^d) \rightarrow \Func(\S ^{d-1} \times \R  \times \R, \Z )    
\end{equation*}
defined as
\begin{equation*}
\LECT(f)(\nu,a,t) = \chi \Big( \left\{x \in \R ^{d} \ \mid \ \langle x ,\nu\rangle \le a , \, f(x) = t \right\} \Big). 
\end{equation*}
\end{defn}
Note that the original definition in \cite{kirveslahti2024representing} is given on a broader class of functions, called defineable functions which are related to o-minimal structures \cite{van1998tame}, however that generalization is beyond this scope of our work. 

$\LECT$ considers only level sets of a field, which turns out to be less than ideal. 
In particular, this poses a problem when trying to define a distance on fields, the usual tool for which is integration, due to each level set being measure 0. 
In order to account for this, we instead focus on the Super Lifted Euler Characteristic Transform, $\SELECT$.

\begin{defn}[\cite{kirveslahti2024representing}]
For piecewise linear  functions $f: \R ^d \rightarrow \R $, the \emph{Super Lifted Euler Characteristic Transform} (SELECT) is given by a map
\begin{equation*}
\SELECT: \PL(\R ^d) \rightarrow \Func(\S ^{d-1} \times \R  \times \R, \Z )   
\end{equation*}
defined as
\begin{equation*}
\SELECT(f)(\nu,a,t) = \chi \big(\{x \in \R ^{d} \ \mid \ \langle x , \nu\rangle \le a , \, f(x) \geq t \} \big). 
\end{equation*}
\end{defn}


In~\cite{kirveslahti2024representing} the injectivity of $\LECT$ and  $\SELECT$ is proven which relies on having complete information in terms of the resulting functions.
The addition of this extra parameter, the value of the function, poses a challenge in terms of extending our bound to $\SELECT$. 
In addition, our bound as it is right now deals exclusively in simplicial complexes, not at all in fields. 
As such, we will now dedicate a few paragraphs to establishing the setting in which our $\SELECT$ distance works. 

%
%

For our SELECT results, we consider PL functions on a simplicial complex $K$. 
These are induced by a function $\phi: V(K)\rightarrow \R_{>0}$ assigning a value to each vertex of $K$. 
We then define the extension to the full complex $K$ by $\bar \phi(\sigma) = \min_{v \in \sigma} \phi(v)$, so that $K^t = \bar \phi \inv [t,\infty)$ is a simplicial complex for every $t$.  
In particular, this means that if $\sigma' \subseteq \sigma$, $\phi(\sigma') \geq \phi(\sigma)$. 
This is analagous to the standard definition of simplex-wise monoanalogous but allows us to have superlevel sets be subcomplexes rather than sublevel sets. 

We study the functions given by two embeddings of $K$, $f, g:K \to \R^d$ for this input function $\phi:V \to \R_{>0}$ given by 
$\bar{f}(x) := \bar \phi \circ f\inv$ where we take $f\inv(x)$ to mean the simplex $\sigma$ of $K$ for which $x \in f(\sigma)\subset \R^d$.
Likewise, we set $\bar{g}:= \bar\phi \circ g^{-1}$. 
Note that $\bar \phi$ is simplex-wise monotone and therefore constant on each simplex, so for any $t$, $\bar{f} \inv(t,\infty]$ is a subcomplex of the geometric complex $f(K)$ in that if it contains a point from the image of a simplex, it contains the entirety of that simplex.
A similar result holds for $g$. 

However, the simplex-wise monotone input means that the resulting functions are piecewise constant and thus not necessarily continuous, which was a requirement for a PL function. 
If we wanted a PL function, we could have instead looked at the following construction. 
Any point $x \in \mathrm{Im}(f)$ is part of the image of some unique simplex $\sigma$ and thus has barycentric coordinates based on the vertices of that simplex, $x = \sum_{v \in \sigma} b_v f(v)$ with $b_v \in [0,1]$ and $\sum b_v = 1$. 
So then we could define $\Phi(x) = \sum_{v \in \sigma} b_v \phi(v)$ to get a PL function. 
However, since this idea is closely related to the idea of a lower star filtration (see \cite[Chapter VI.3]{Edelsbrunner2010}), we can retract $\Phi \inv[t,\infty)$ to $K^t$ for any $t$. 
Because the two sets have the same homotopy type, they have the same Euler characteristic, and so we are justified in using the piecewise constant function instead. 


Thus, we define $\twiddle{f}: \S^{d-1} \times \R \times \R$ as $\SELECT(\phi\circ f^{-1})$ and $\twiddle{g}$ as $\SELECT(\phi\circ g^{-1})$. 
Now, we can take the SELECT-distance from~\cite{kirveslahti2024representing}, and modify it to reflect our restriction on the codomain of our fields.
$$
d_{\SELECT}(\twiddle{f}, \twiddle{g}) 
= \left(\int_{\R _{>0}} \int_{\S ^{d-1}}  \int_{\R } \bigm\vert \tilde{f}(\nu,a,t)-\tilde{g}(\nu,a,t) \bigm\vert^p  \ da \ d\nu \ dt\right)^{1/p}.
$$
%
%
Though this is a $p$-distance, like many others, we will restrict its use in our paper to $p=1$ in order to match the ECT distance.
We can now prove the following theorem. 


\begin{theorem}
Let $K$ be an abstract simplicial complex with vertex function $\phi:V\rightarrow\R_{>0}$, and let $f,g$ be two embedding functions $f, g: K\rightarrow\R^d$. 
Define constants
$$C_d = 2 \omega_{d-2} \int_0^\frac{\pi}{2}\cos(\theta)\sin^{d-2}(\theta)d\theta, 
\qquad 
C_K = \max\limits_{{v \in V(K)}} \left|\{ \sigma \in K \mid v \in \sigma \}  \right|$$
and $r_{\max} = \max \{\phi(\sigma) \mid \sigma \in K\}$. 
Then for $\twiddle{f} = \SELECT(\phi\circ f^{-1})$ and $\twiddle{g} = \SELECT(\phi\circ g^{-1})$, we have 
$$
d_{\SELECT}(\twiddle{f}, \twiddle{g}) \leq 2 r_{\max} C_d C_K \underset{v \in V(K)}{\sum}{\|f(v) - g(v)\|_2}.
$$
\end{theorem}

\begin{proof}
%
First, we can rewrite our modified SELECT-distance as
\begin{align*}
d_{\SELECT}(\twiddle{f}, \twiddle{g})_1 
&= \int_{\R _{>0}} \int_{\S ^{d-1}}  \int_{\R } 
     \left|  \tilde{f}(\nu,a,t)-\tilde{g}(\nu,a,t) \right|    \ da \ d\nu \ dt \\
&= \int_{\R _{>0}} \int_{\S ^{d-1}}  \int_{\R } \left | \ECC_\nu(f(K^t),a)-\ECC_\nu(g(K^t),a) \right |  \ da \ d\nu \ dt \\
&= \int_{\R _{>0}} \int_{\S ^{d-1}} \left \| \ECC_\nu(f(K^t))-\ECC_\nu(g(K^t)) \right\|_1 \ d\nu \ dt \\
&= \int_{\R _{>0}} d_{\ECT}\big(ECT(f(K^t)), ECT(g(K^t))\big) \ dt.
\end{align*}
We know by our ECT stability theorem, Thm.~\ref{thm:ectstablity}, that 
$$
d_{\ECT}\big(ECT(f(K^t)), ECT(g(K^t))\big) 
\leq 2 C_d C_{K^t} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2,
$$
so we obtain
\begin{align*}
d_{\SELECT}(\twiddle{f}, \twiddle{g})_1 &\leq \int_{\R _{>0}} 2 C_d C_{K^t} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2 \ dt \\
&\leq 2 C_d \int_{\R _{>0}} C_{K^t} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2 \ dt.
\end{align*}
We are able to pull $C_d$ out of the integral because it is not dependent on the subcomplex. The other terms, however, are dependent on the subcomplex. 
The constant
$$
C_{K^t} = \underset{v \in V(K^t)}{\max} |\{\sigma \in K^t \mid v \in \sigma\}|
$$
is the maximum number of cofaces for any vertex in $K^t$. 
As $t$ increases and the subcomplex contracts, the number of cofaces for each vertex will only ever decrease or stay the same. 
This means that $C_{K^t} \leq C_{K}$ for all $t \in \R _{>0}$.
Furthermore, for 
$t > r_{\max}=\underset{\sigma\in K}{\max} \{\phi(\sigma)\}$, $K^t = \emptyset$, so for large enough $t$, $C_{K^t} = 0$. 
This means that we can restrict our bounds of integration, loosen our upper bound, and then pull out $C_K$, as follows:
\begin{align*}
d_{\SELECT}(\twiddle{f}, \twiddle{g})_1 &\leq 2 C_d \int_{\R _{>0}} C_{K^t} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2 \ dt \\
&\leq 2 C_d \int_{0}^{r_{\max}} C_{K^t} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2 \ dt \\
&\leq 2 C_d \int_{0}^{r_{\max}} C_{K} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2 \ dt \\
&\leq 2 C_d C_K \int_{0}^{r_{\max}} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2  \ dt.
\end{align*}
We can use similar logic to deal with the remaining integrand. 
$V(K^t) \subseteq V(K)$ for every $t$, so 
$$
\sum_{v\in V(K^t)} \|f(v) - g(v)\|_2 
\leq 
\sum_{v\in V(K)} \|f(v) - g(v)\|_2
$$
for every $t$. 
This leads to our final upper bound.
\begin{align*}
d_{\SELECT}(\twiddle{f}, \twiddle{g})_1 &\leq 2 C_d C_K \int_{0}^{r_{\max}} \sum_{v\in V(K^t)}\|f(v) - g(v)\|_2  \ dt \\ 
&\leq 2 C_d C_K \int_{0}^{r_{\max}} \sum_{v \in V(K)}\|f(v) - g(v)\|_2  \ dt \\
&\leq 2 C_d C_K \sum_{v\in V(K)}\|f(v) - g(v)\|_2 \int_{0}^{r_{\max}} 1 \ dt \\
&\leq 2 r_{\max} C_d C_K \sum_{v\in V(K)}\|f(v) - g(v)\|_2.
\end{align*}
\end{proof}

\section{Discussion and Conclusion} %

The stability of the Euler Characteristic Transform (ECT) is crucial for its dependable application in shape analysis. 
This work contributes to this area by establishing an explicit upper bound (Theorem \ref{thm:ectstablity}) on the $d_{\ECT}$ distance. 
This bound arises when comparing two distinct geometric embeddings of the same abstract simplicial complex $K$ and directly links variations in the ECT to the sum of $L_2$ distances between corresponding vertex positions. 
This quantifies ECT's sensitivity to geometric perturbations when the underlying combinatorial topology is fixed. 
We subsequently extended this stability framework to the Super Lifted Euler Characteristic Transform (SELECT), considering fields induced by simplex-wise monotone functions $\phi$ on $K$, and similarly connected the $d_{\SELECT}$ stability to vertex displacements and the range of $\phi$.

These findings provide important theoretical guarantees for the robustness of ECT and SELECT. Such stability is particularly relevant in applications involving deformable objects or variations in pose where the intrinsic mesh topology is preserved, supporting the reliable use of these TDA descriptors in analytical pipelines.

However, our results are contingent on specific conditions: primarily, the comparison of embeddings of an identical abstract complex and, for SELECT, the use of a particular class of field-inducing functions. 
A significant direction for future research is therefore the generalization of these stability results. 
This includes extending SELECT stability to more commonly used field representations, such as those derived from piecewise-linear interpolation, and developing frameworks for ECT/SELECT comparisons across different underlying combinatorial structures. 
Refining the derived bounds also remains an important objective.


