% The following can easily be extended to the approximation of vector or function valued quantities of interest.

\mg{Assuming \lt{that} our quantity of interest is smooth with respect to the parameters $\y$, global polynomial approximation represents a common choice in the context of parametric PDEs and related problems, as already \lt{mentioned} in the introduction.} %\cite{Nobile2008a,Xiu2005,Babuska2004,Back2011,Zhang2012,Maitre2010,Gunzburger2014,Cohen2015,Adcock2022}.
In particular, this assumption ensures that we can write the quantity of interest as a convergent polynomial series.
\ah{More explicitly, consider a basis of multi-variate polynomials $\{\chebBasis_{\vMiPoly}(\y)\}_{\vMiPoly\in\N_0^{\nY}}$ where  $\chebBasis_{\vMiPoly}(\y) = \prod_{\iY=1}^{\nY}\oneChebBasis_{\miPoly_{\iY}}(y_{\iY})$ and each term $\oneChebBasis_{\miPoly_{\iY}}(y_{\iY})$ is a polynomial of degree $p_{\iY}$ \mg{in the parameter $y_\iY$}.
For example, $\oneChebBasis_{\miPoly_{\iY}}(y_{\iY})$ could be the monomial $y^{\miPoly_{\iY}}$, or the Chebyshev polynomial of the first kind of degree ${\miPoly_{\iY}}$.
}
The quantity of interest $q$ can then be expressed as a convergent polynomial series,
\begin{equation}\label{eq:spectral}
    q(\y) \equiv \sum_{\vMiPoly \in \N_0^{\nY}} \FT{q}_{\vMiPoly}\chebBasis_{\vMiPoly}(\y).
\end{equation}
% \text{ with } \lvert \FT{q}_{\vMiPoly} \rvert \lesssim C(q,a) \prod_{\iY=1}^{\nY}  \ellipseR_{\iY}^{-\miPoly_{\iY}}
%  by proving the analyticity of the quantity of interest $q$ with respect to the input parameters, see e.g.\ \cite{Gunzburger2014,Cohen2015,Adcock2022}.
