\paragraph{\ah{Admissibility of multi-index sets}}
A valid approximation in \eqref{eq:combinationtechnique} is obtained only if the multi-index set $\miset$ is admissible (also known as downwards closed, or a lower set).
Admissibility requires each multi-index $\vMi \in \miset$ to satisfy
\begin{equation}\label{eq:admissibile}
    \vMi - \vUnit_{\iY} \in \miset \forall \iY=1,...,\nY \st \mi_{\iY}>1
\end{equation}
where $\vUnit_{\iY}=[0,0,...,1,...,0]$ is the unit multi-index with \mg{value} $1$ only in the $i^\text{th}$ entry.
% For an admissible (also referred to as downwards closed) multi-index set $\miset\subset\N^{\nY}$, the sparse grid approximation of $u\in C^0(\Gamma;\R)$ is
% \begin{equation} \label{eq:sgapprox}
%     \approxP{u}(\y):= \sum_{\vMi\in\miset} \detailOp{\vMi}[u](\y) \equiv \sum_{\vMi\in\miset} c_{\vMi} \interpOp{\vMi}[u]
% \end{equation}
% where
% \begin{equation} \label{eq:detail}
%     \detailOp{\vMi}:=\bigotimes_{\iY=1}^{\nY} \detailOp{\mi_{\iY}}, \quad \interpOp{\vMi}:=\bigotimes_{\iY=1}^{\nY} \interpOp{\mi_{\iY}}, \quad c_{\vMi}:=\sum_{\substack{\vMiAlt \in\{0,1\}^{\nY}\\ \vMi+\vMiAlt \in \miset}}(-1)^{\Vert\vMiAlt\Vert_1}.
% \end{equation}
% Denote the corresponding polynomial approximation space $\polySpace{\miset}(\Gamma;U)$.
The set of multi-indices that can be added to $\miset$ whilst maintaining admissibility is called the reduced margin
\begin{equation}\label{eq:reducedmargin}
    \reducedmargin{\miset} := \Big\{\vMiParam\in\N^{\nY} \setminus \miset \st \vMiParam - \vUnit_{\iY} \in \miset \forall \iY=1,...,\nY \st \mi_{\iY}>1 \Big\}.
\end{equation}
For an admissible multi-index set $\miset\subset\N^{\nY}$ and nested set of points $\{\collocSet{\level}\}_{\level\in\N}$, the approximation \eqref{eq:combinationtechnique} is an interpolant.
