\ah{
Another technical challenge arises from the treatment of the {saturated fidelities} $\saturatedModels$.
Blocking further refinement of these saturated fidelities may unintentionally restrict access to high-degree polynomial approximations at \emph{unsaturated} fidelity levels.}
% Another technical issue is that blocking refinements in the saturated fidelities $\saturatedModels$ may prevent other unsaturated fidelities accessing higher polynomial parametric approximations.
This \ah{issue stems from} the admissibility \ah{constraint} on the multi-index set, which is enforced by only exploring the reduced margin $\reducedmargin{\miset}$ \ah{as defined in equation} \eqref{eq:reducedmargin}.
For instance, \ah{consider} \Cref{fig:modifiedreducedmargin}\lt{:} the multi-index $\vMiFull=[3,3]$ may not be reached if the fidelities $\miModel=1,2$ are already saturated.
However, fidelity $\miModel=3$ \ah{being} less noisy, may \ah{still benefit from further parametric refinement}.
\begin{figure}\begin{center}
    % \begin{subfigure}[t]{0.49\textwidth}
        \inputfrom{figures/}{modifiedreducedmargin.tex}    
\end{center}
        % \caption{Modified reduced margin $\reducedmargin{\miset,\saturatedModels}$ and backfill set $B_{\miset,[3,3]}$ assuming saturated models $\saturatedModels=\{1,2\}$}          
        % \label{fig:submodifiedrm}
    % \end{subfigure}
    \caption{Modified reduced margin $\reducedmargin{\miset,\saturatedModels}$ defined in \eqref{eq:modifiedreducedmargin} for a multi-index set with $\nModel=1$ and $\nY=1$.
    If the saturated models are $\saturatedModels=\{1,2\}$, the multi-index $[3,3]$ is still permitted to be explored by the adaptive algorithm, whilst the multi-indices $[1,3],[2,3]$ may have their profits set to zero by \eqref{eq:filter-profits}.
    To maintain admissibility the multi-indices $B_{\miset,[3,3]}$, as defined in \eqref{eq:backfill}, must be used to `backfill` the multi-index set if $[3,3]$ is selected by the adaptive algorithm.}
    \label{fig:modifiedreducedmargin}
\end{figure}
\ah{To enable this}, we \ah{introduce} a \emph{modified reduced margin} \ah{that permits selective refinement at unsaturated fidelities}\bk{:
first define the \bk{margin} set \ah{$\margin{\miset}$}},
% \begin{equation}\label{eq:modifiedmiset}
%     {\miset}^{S} := \miset \cup \bigcup_{\vMiModel\in\saturatedModels} \{[\vMiModel, \vMiParam] \forall \vMiParam \in \N^{\nY}\},
% \end{equation}
\begin{equation}\label{eq:margin}
    \margin{\miset{}} := \Big\{\mistyle{\mu}\in\N^{\nModel+\nY} \st \mistyle{\mu} = \vMiFull + \vUnit_{\iY} \text{ for some } \{\vMiFull, \iY\} \in \miset \times \{1,2,...,\nModel+\nY\}\Big\}
\end{equation}
then the \emph{modified reduced margin} is
% \begin{equation}\label{eq:modifiedreducedmargin}
%     % \reducedmargin{\miset,\saturatedModels} := \Big\{\vMiAlt\in\N^{\nModel+\nY}\setminus\miset \st \vMiAlt - \vUnit_{\iY} \in {\miset}^{S} \forall \iY=1,...,\nModel+\nY \Big\} \setminus \Big\{\vMiFull=[\vMiModel,\vMiParam] \in \N^{\nModel+\nY} \st \alpha\in\saturatedModels\Big\}.
%     \reducedmargin{\miset,\saturatedModels} := \Big\{\vMiAlt\in\N^{\nModel+\nY}\setminus\miset \st \vMiAlt - \vUnit_{\iY} \in {\miset}^{S} \forall \iY=1,...,\nModel+\nY \Big\}.
% \end{equation} \todo{THIS MUST BE CHECKED}
\begin{equation}\label{eq:modifiedreducedmargin}
    % \reducedmargin{\miset,\saturatedModels} := \Big\{\vMiAlt\in\N^{\nModel+\nY}\setminus\miset \st \vMiAlt - \vUnit_{\iY} \in {\miset}^{S} \forall \iY=1,...,\nModel+\nY \Big\} \setminus \Big\{\vMiFull=[\vMiModel,\vMiParam] \in \N^{\nModel+\nY} \st \alpha\in\saturatedModels\Big\}.
    \reducedmargin{\miset,\saturatedModels} := \Big\{ \vMiFull \in \margin{\miset} \st [\vMiModel, \vMiParam]:= \vMiFull - \vUnit_{\iY} \in \miset \forall \iY=1,2,...,\nModel+\nY \text{ or } \vMiModel \in \saturatedModels\}.
\end{equation}
% and $\vUnit_{\iY}$ is again the unit multi-index in each dimension $\iY=1,..,\nModel+\nY$.
% Equations \eqref{eq:modifiedreducedmargin} and \eqref{eq:modifiedmiset} 
\ah{This construction ensures that each} backward neighbour $\vMiAlt - \vUnit_{\iY} $ either \ah{belongs to} the \ah{current} multi-index set $\miset$ or corresponds to a saturated fidelity in $\saturatedModels$ (i.e.\ $\vMiAlt - \vUnit_{\iY}\in \bigcup_{\vMiModel\in\saturatedModels} \{[\vMiModel, \vMiParam] \forall \vMiParam \in \N^{\nY}\}$).
\bk{Multi-indices corresponding to high polynomial degree terms in saturated fidelities are not explicitly removed from the reduced margin, however they \mg{are} ignored in the adaptive algorithm \lt{since} their profits are set to zero by \eqref{eq:filter-profits}.}
% \ah{Moreover}, equation \eqref{eq:modifiedreducedmargin} \ah{explicitly excludes} all \ah{new} multi-indices \ah{associated with} saturated fidelities from the \ah{refinement candidates}.

\ah{T}o maintain admissibility of the multi-index set when adding a multi-index from the modified reduced margin $\reducedmargin{\miset,\saturatedModels}$, we introduce a backfilling procedure.
% At refinement the multi-index set may required `backfilling'.
For $\vMiFull\in \reducedmargin{\miset,\saturatedModels}$ the indices required to backfill the multi-index set $\miset$ to maintain admissibility are denoted by
\begin{equation}\label{eq:backfill}
    B_{\miset,\vMiFull} := \{\text{minimal set of } \widehat{\vMiFull}\in\N^{\nModel+\nY} \st \miset \cup B_{\miset,\vMiFull} \cup \{\vMiFull\} \text{ satisfies admissibility property \eqref{eq:admissibile}} \},
\end{equation}
see again \Cref{fig:modifiedreducedmargin} for a visualisation.
By construction all multi-indices $\vMiFull\in B_{\miset,\vMiFull}$ can only correspond to saturated fidelities.
The refinement of the multi-index set $\miset$ with $\vMiFull\in\reducedmargin{\miset,\saturatedModels}$ \ah{is then updated as} $\miset \gets \miset \cup B_{\miset,\vMiFull} \cup \{\vMiFull\}$.
Finally, the introduction of backfilling requires that we update the definitions of the error indicator $E_{\vMiFull}$ and cost $W_{\vMiFull}$ for a multi-index $\vMiFull\in\reducedmargin{\miset,\saturatedModels}$ accounting for the backfill set $B_{\miset,\vMiFull}$.
The error indicator \eqref{eq:error-ind} is \mg{thus} updated to
\begin{equation} \label{eq:error-ind-pmisc}
    E_{\vMiFull} := \Big\lvert \Exp{\interpOp{\miset \cup B_{\miset,\vMiFull} \cup  \{\vMiFull\}}[{q}]} - \Exp{\interpOp{\miset}[q]} \Big\rvert,
\end{equation}
 and similarly the cost \eqref{eq:work-misc} is updated to
\begin{equation} \label{eq:work-pmisc}
    W_{\vMiFull} := \widehat{W}_{\vMiModel}(\nColloc{\miset\rvert_{\vMiModel} \cup\{\vMiParam\}} - \nColloc{\miset\rvert_{\vMiModel} }) + \sum_{\widehat{\vMiFull}=[\widehat{\vMiModel},\widehat{\vMiParam}]\in B_{\miset,\vMiFull}} \widehat{W}_{\widehat{\vMiModel}} (\nColloc{\miset\rvert_{\widehat{\vMiModel}} \cup\{\widehat{\vMiParam}\}} - \nColloc{\miset\rvert_{\widehat{\vMiModel} }})
\end{equation}
where the cost required to backfill the multi-index set must be included.

\begin{algorithm}[tb]
    \caption{Plateau Detection Multi-Index Stochastic Collocation}
    \label{alg:pmisc}
    \begin{algorithmic}[1]
        \Function{PlateauMISC}{$\{q^{\vMiModel}:\Gamma\subset\R^{\nY} \to \R\}_{\vMiModel \in \N^{\nModel}}$}
        \State Initial multi-index set $\miset = \{[\mistyle{1},\mistyle{1}]\}\subset \N^{\nModel+\nY}$
        \While{stopping criteria not met}
            \State{Compute approximation $\approxFinal{q}:=\sum_{\vMiFull\in\miset} c_{\vMiFull} \interpOp{\vMi}[q^{\vMiModel}]$ where $\vMiFull=[\vMiModel, \vMiParam]$.} \Comment{Solve}
            \State{Compute modified reduced margin $\reducedmargin{\miset,\saturatedModels}$ via Equation \eqref{eq:modifiedreducedmargin}.}
            \For{$\vMiFull \in \reducedmargin{\miset,\saturatedModels}$} \Comment{Estimate}
                \State Estimate multi-index contribution $E_{\vMiFull}$ via Equation \eqref{eq:error-ind-pmisc}.
                \State Estimate multi-index cost $W_{\vMiFull}$ via Equation \eqref{eq:work-pmisc}.
                \State Compute multi-index profits $\profit_{\vMiFull}=E_{\vMiFull} / W_{\vMiFull}$.
            \EndFor
            \State{}
            \For{each unsaturated active model $\vMiModel \in \modelSet\setminus\saturatedModels$} \Comment{Detect}
                \State Construct $\approxFinal{q}\rvert_{\vMiModel}$ via \eqref{eq:miscrestricted}. % and \eqref{eq:misetrestricted}.
                \State Construct spectral envelope $(i, \envelope\rvert_{\vMiModel}(i))$ via \eqref{eq:env}.
                \State $\changept\rvert_{\vMiModel}, \error{plateau}\rvert_{\vMiModel}, {isPlateau}\rvert_{\vMiModel} = \textsc{PlateauDetection}{(i, \envelope\rvert_{\vMiModel}(i), \nBurnIn, \nBurnOut, \nMin)}$
            \EndFor
            \State Update saturated models $\saturatedModels \gets \saturatedModels\cup\{\vMiModel\in \modelSet\setminus\saturatedModels \st {isPlateau}\rvert_{\vMiModel} = \texttt{true}\}$
            \State{}
            \State \mg{Set} zero profits $\profit_{\vMiFull}$ for saturated $\vMiFull$ using criteria in \eqref{eq:filter-profits}.
            \State Select $\vMiFull^* \gets \argmax_{\vMiFull\in\reducedmargin{\miset,\saturatedModels}} \profit_{\vMiFull}$ and refine $\miset \gets \miset \cup B_{\miset,\vMiAlt^*} \cup\{\vMiFull^*\}$. \Comment{Mark and Refine}
        \EndWhile
        \State{\Return $\approxFinal{q}:=\sum_{\vMiFull\in\miset} c_{\vMiFull} \interpOp{\vMi}[q^{\vMiModel}]$ where $\vMiFull=[\vMiModel, \vMiParam]$.}
        \EndFunction
        \end{algorithmic}
\end{algorithm}
The complete \plateaumisc{} algorithm is presented in \Cref{alg:pmisc}.
Note the differences \mg{with respect} to \Cref{alg:misc}: 
\begin{itemize}
    \item the \mg{plateau} detection step is introduced to identify saturated fidelities;
    \item a subset of profits may be set to zero via \eqref{eq:filter-profits};
    \item the returned approximation no longer uses the reduced margin.
\end{itemize}
This third point is to ensure that the high degree polynomial terms used to identify the spectral plateaus in the saturated fidelities are not included in the returned approximation, \bk{since they} will generally only contribute spurious oscillations to the \bk{full} approximation.
%\marginpar{This is not complete. On testing if a multi index is saturated it must have a satureated model, and only introduce polynomials of higher degree than the change point.}

