\subsection{Uncertainty quantification for unsteady advection--diffusion problem with uncertain coefficients} \label{sec:parabolic}
% We seek a surrogate model approximating the solution to the following PDE problem.
Consider the spatial domain $\spatialdomain:=(-1,1)^2$, finite time $T>0$ and parameter domain $\Gamma:=[0,1]^2$.
% \mg{For each $\y\in\Gamma$, we seek the function 
% % $u(\cdot,\cdot;\y)\in L^2(0,T;H^1(\spatialdomain))$, $\frac{\partial u(\cdot,\cdot;\y)}{\partial t}\in L^2(0,T;H^{-1}(\spatialdomain))$ (see e.g., \cite{Evans2010})
% $u(\cdot,\cdot;\y):\spatialdomain \times (0,T) \to \R$
% solving the following advection--diffusion problem:}\todo{Simple or use more details, and also define appropriate spaces?}
\mg{For each $\y\in\Gamma$, we seek the solution to the following advection--diffusion problem:}
\begin{equation}\label{eq:parabolic}
    \begin{cases}
        \displaystyle\frac{\partial u}{\partial t}(\x,t;\y) - \nabla \cdot \big(\diffFn(\y) \nabla u(\x,t;\y)\big) + \wind(\x,\y) \cdot \nabla u(\x,t;\y) = 0, & (\x,t) \in \spatialdomain \times (0,T),\\
        u(\x,t;\y) = (1-\exp(-t/0.1))(1+0.1\sin(2\pi t)), & (\x,t) \in \spatialbdry \times (0,T),\\
        u(\x,0;\y) = 0, & \x \in \overline{\spatialdomain}, 
    \end{cases}
\end{equation}
where the operator $\nabla$ acts on the spatial variable $\x$ and \ah{the diffusion coefficient $\diffFn(\y)$ and advection field $\wind(\x,\y)$ are affine functions of the parameters $\y\in\Gamma$, \mg{namely},}
\begin{equation}\label{eq:windanddiff}
        \diffFn(\y) :={} 0.1\diffFn_0 + 1.8\diffFn_0 y_1, \quad
        \wind(\x,\y) :={} \wind_0(\x) + \sum_{i=1}^{4} \wind_i(\x) (2y_2-1),
\end{equation}
with
\begin{equation}
    \begin{aligned}
        \wind_0(\x) &:={} [2x_2(1-x_1^2), -2 x_2 (1-x_1^2)], \quad 
        \wind_i(\x) &:={}
        \begin{cases}
                \wind_0(2(\x-[c_i,d_i])) & \x \in\spatialdomain_i,\\
                [0,0], & \text{otherwise},
        \end{cases}
    \end{aligned}
\end{equation}
for $\vec{c}:=[-0.5,-0.5,0.5,0.5]$, $\vec{d}:=[-0.5,0.5,-0.5,0.5]$, $\spatialdomain_i:=[c_i-0.5, d_i+0.5]\times[c_i-0.5, d_i+0.5]$.
Three realisations of the advection field $\wind(\x,\y)$ are given in \Cref{fig:windrealisations}.% \todo{Should i move advection figure here}
