\subsection{Parametric flow control in turbulent incompressible Navier--Stokes problem}
\label{example:2dwmh}
This example considers the NASA two dimensional wall mounted hump (2DWMH) benchmark test \ah{case} \cite{NASA2DWMH,Greenblatt2004,Naughton2004}, \ah{which simulates a turbulent incompressible flow over a Glauert--Goldschmied-type body} \mg{controlled by a parameter $\y\in\Gamma=[0,1]^2$}.
\mg{The problem is governed by the Reynolds-averaged Navier--Stokes equations for incompressible flows, with Spalart--Allmaras turbulence model:
\begin{equation}\label{eq:nssa}
    \begin{cases}
        \displaystyle\frac{\partial \vec{u}}{\partial t} + \nabla \cdot (\vec{u} \otimes \vec{u}) - \nabla \cdot (2(\nu+\nu_t)\nabla^{s}\vec{u}) + \nabla p = \vec{0}, & (\x,t) \in \spatialdomain \times (0,T),\\
        \nabla \cdot \vec{u} = 0, & (\x,t) \in \spatialdomain \times (0,T),\\
        \displaystyle\frac{\partial \widetilde{\nu}}{\partial t} + \nabla \cdot (\vec{u} \widetilde{\nu}) - \frac{1}{\sigma}\nabla \cdot ((\nu+\widetilde{\nu})\nabla \widetilde{\nu}) - \frac{c_{b2}}{\sigma} \nabla \widetilde{\nu} \cdot \nabla \widetilde{\nu} - c_{b1} \widetilde{S}\widetilde{\nu} + c_{w1} f_{w} \left(\frac{\widetilde{\nu}}{\widetilde{d}}\right)^2 = 0, & (\x,t) \in \spatialdomain \times (0,T),\\
    \end{cases}
\end{equation}
where $\vec{u}(\x,t;\y)$, $p(\x,t;\y)$ and $\widetilde{\nu}(\x,t;\y)$ are the parameter-dependent velocity, pressure and eddy viscosity fields.
Moreover, the turbulent viscosity is defined as
\begin{equation}
    \nu_t = \widetilde{\nu} f_{v1},
\end{equation}
and $\nu$, $\nabla^{s}\vec{u}=(\nabla \vec{u} + (\nabla \vec{u})^\top)/2$ and $\widetilde{d}$ respectively denote the physical viscosity of the fluid, the strain-rate tensor and the distance from the closest wall in the domain.
Finally, the Spalart--Allmaras model is completed with a set of closure functions \cite{Spalart1992}:
\begin{equation}\label{eq:sa}
    \begin{aligned}
    \bm{\Omega}&:=\displaystyle\frac{\nabla \vec{u} - (\nabla \vec{u})^\top}{2}, &
    \widetilde{S}&:=[2\bm{\Omega} : \bm{\Omega}]^{1/2}+\displaystyle\frac{\widetilde{\nu}}{\kappa^2\widetilde{d}^2} f_{v2}, &
    \chi &:= \displaystyle\frac{\widetilde{\nu}}{\nu},\\
    f_w&:=g\left[\displaystyle\frac{1+c_{w3}^6}{g^6+c_{w3}^6}\right]^{1/6}, &
    f_{v2}&:=1-\displaystyle\frac{\chi}{1+\chi f_{v1}}, &
    f_{v1}&:=\displaystyle\frac{\chi^3}{\chi^3 + c_{v1}^3},\\
    g&:=r+c_{w2}(r^6-r), &
    r&:=\frac{\widetilde{\nu}}{\widetilde{S} \kappa^2 \widetilde{d}^2}, &
    \end{aligned}
\end{equation}
where $\sigma=2/3$, $c_{b1}:=0.1355$, $c_{b2}=0.622$, $\kappa=0.41$, $c_{w1}=c_{b1}/\kappa^2 + (1+ c_{b2})/\sigma$, $c_{v1}=7.1$, $c_{w2}=0.34$ and $c_{w3}=2$.}

