3.& $\vecz: \text{vec[int]} \gets\vecmask(\vecx: \text{vec[int]},\vecy:\text{vec[bit]})$ 
    &  
    $\OO(nB)$   
    &  
    $\OO(1)$ / $\OO(B)$
    &
    $\vecz(i)\gets \vecx(i)$ if $\vecy(i)=1$, else $\vecz(i)\gets 0$.
    \\
4.& $\vecz: \text{vec[bit]} \gets\veciszero(\vecx: \text{vec[int]})$ 
    &  
    $\OO(nB)$    
    & 
    $\OO(B)$ / $\OO(1)$
    & 
    $\vecz(i)\gets 1$ if $\vecx(i)=0$, else $\vecz(i)\gets 0$.
    \\
5.& $\vecz: \text{vec[int]} \gets\vecadd / \vecsub (\vecx: \text{vec[int]},\vecy:\text{vec[int]})$ 
    &  
    $\OO(nB^2)$    
    &  
    $\OO(B)$
    &
    $\vecz(i)\gets \vecx(i)+\vecx(j)$ (resp. $\vecx(i)-\vecx(j)$).
    \\\hline
6.& $\vecz: \text{vec[int]} \gets\vecfills(\vecx:\text{vec[int] } ; s )$ 
    & 
    $\OO(nB)$
    &  
    $\OO(1)$ / $\OO(s)$
    &
    $\vecz(is:is+s)\gets \vecx(is),i\in\{0,\ldots,\lfloor\tfrac{n}{s}\rfloor\}$.
    \\
7.& $\vecz: \text{vec[int]} \gets\vecgathers( \vecx: \text{vec[int] } ; s )$ 
    &  
    $\OO(sB)$   
    &  
    $\OO(1)$
    &
    $\vecz(i-1) 
    \gets \vecx(si-1), i\in \{1,\ldots,\lceil\frac{n}{s}\rceil\}$.\\
8.& $\vecz: \text{vec[int]} \gets\vecscatters(\vecx: \text{vec[int] } ; s )$ 
    &  
    $\OO(sB)$   
    &  
    $\OO(1)$
    &
    $
    \vecz(si-1)\gets
    \vecx(i-1),
    i\in \{1,\ldots,\lceil\frac{n}{s}\rceil\}$.
    \\
9.& $\vecz: \text{vec[int]} \gets\vecrevspecs(\vecxbar: \text{vec[int]},\vecfbar:\text{vec[int] } ; s )$ 
    &  
    $\OO\left(
        nB(s^2+\frac{B}{s})
        \right)$   
    &  
    $\OO(s+B)$ / $\OO(sB)$
    &
    Reverts misspeculation (Lemma \ref{lemma:revert_spec_ac0}).
    \\\hline
    \end{tabular}
    }
    \endgroup
    \label{table:vector_operations}
\end{table}
