\subsection{Reverting speculative scans using (masked) vector operations}
\label{appendix:revert_spec}
%%%
%%
%
Here, we demonstrate that the $\vecrevspecs$ vector operation can be simulated using multiple masked vector operations. We present two such algorithms.
%

%
First, \Cref{alg:revertspec_basic} is simple and provides insight about the vector computations required. Its main drawback is that it performs reductions of $\OO(s)$ numbers for each segment, hence requiring $\OO(\log (s))$ steps and $\OO(ns)$ work. To further reduce the work overhead of the speculation, we present~\Cref{alg:revertspec_vec}, which has $\OO(n\log (s))$ work and $\log(s)+\OO(1)$ steps. The key difference of the two algorithms is that the latter uses a Kogge--Stone prefix masked reduction to avoid the work overhead (recomputation) compared to Algorithm~\ref{alg:revertspec_basic}.
%
%
%%
%%%
\begin{algorithm}[ht]
\begin{algorithmic}[1]
\Procedure{RevertSpecSimple}{$\vecz$, $\vecx$, $\vecf$, $s$} \Comment{Works in-place on $\vecz$}
\State $\vecfbar \gets \matmulop(\vecf, \matU_s)$
\ParFor {each $s$-block $(\vecz_s, \vecx_s, \vecfbar_s)$} \State $\mu \gets \vecfbar_s(s -1)$
    \If {$\mu == 0$ or ($\mu == 1$ and $\vecfbar_s(0)==1$)} 
    \State \Return \Comment{Speculation is correct.}
\EndIf
\If{$\mu== s$} 
    \State $\vecz_{s} \gets \vecx_{s}$ \Comment{$s$ segments, no scan required. Revert.}
    \State \Return 
\EndIf
\ParFor {$\text{idx}=\vecfbar_s(0)+1,\dots, \mu$}
\State $\text{offset} \gets \Call{Sum}{\Call{LessThan}{\vecfbar_s, \text{idx}}} - 1$ 
\State $\vecz_s \gets \vecz_s - (\vecfbar_s == \text{idx}) \cdot \vecz_s(\text{offset})$
\EndParFor
\EndParFor
\EndProcedure
\end{algorithmic}
\caption{Revert Speculative Prefix Sums}\label{alg:revertspec_basic}
\end{algorithm}
%%%
%%
%
%
%
%%
%%%
\begin{algorithm}[ht]
\begin{algorithmic}[1]
\Procedure{RevertSpecMMVRAM}{$\vecz$, $\vecx$, $\vecf$, $s$} \Comment{Works in-place on $\vecz$}
\State $\vecfbar \gets \matmulop(\vecf, \matU_s)$
\ParFor{each $s$-block $(\vecz_s, \vecx_s, \vecfbar_s)$} \State $\mu \gets \vecfbar_s(s -1)$
    \If {$\mu == 0$ or ($\mu == 1$ and $\vecfbar_s(0)==1$)} 
    \State \Return \Comment{Speculation is correct.}
\EndIf
\If{$\mu== s$} 
    \State $\vecz_{s} \gets \vecx_{s}$ \Comment{$s$ segments, return input.}
    \State \Return 
\EndIf
\State $\vecq_s \gets \vecxor \left(
    \vecshiftl\left(
        \vecfbar,1
    \right), 
    \vecf 
\right)$
\State $\vecm_s \gets\vecshiftr(\vecq_s,1)$ 
\State $\vecw_s \gets\vecshiftr\left(
    \vecmask\left(\vecz_s, \vecq_s\right),
1\right)$ \Comment{Correction vector.}
\For {$j=0,\dots,\lceil \log(s)\rceil$}
\State $b \gets 2^j $ 
\State $\vecmbar_s\gets\vecshiftr\left(\vecm_s, b\right)$
\State $\vecwbar_s \gets\vecshiftr\left(\vecw_s, b\right)$
\State $filter_s \gets \vecleq\left( \vecadd\left(\vecm_s , \vecmbar_s\right), 2 \right)$
\State $\vecm_s \gets \vecmask\left(
    \vecadd\left(
        \vecm_s, \vecmbar_s 
    \right)
    ,  
    filter_s
\right)$
\State $\vecw_s \gets \vecmask\left(
    \vecadd\left(
        \vecw_s, \vecwbar_s
        \right), 
    filter_s
\right)$
\EndFor
\State $\vecz_s \gets \vecsub\left(\vecz_s, \vecw_s\right)$
\EndParFor
\EndProcedure
\end{algorithmic}
\caption{Revert Speculative Scans with MMV-RAM Vector instructions}\label{alg:revertspec_vec}
\end{algorithm}
