\begin{equation}\label{eq:diff_mat}
\matD_s:=\begin{bmatrix}
1 & -1 & 0 &\dots & 0\\
0 & 1 & -1 &  \dots & 0 \\
0 & 0 & 1 &  \dots & 0 \\
\vdots & 0 & 0 &\ddots& -1 & \\
0 & 0 & \dots & 0 & 1 
\end{bmatrix}_{s\times s}.
\end{equation}
