\subsection{The hierarchical partition tree}

Lemma~\ref{lem:partitiontree} guarantees the crossing numbers for the hyperplanes in $H$. To make it work for any hyperplane in $\bbR^d$, we use the following lemma, which was known before, e.g.,~\cite{ref:ChanOp12}.

% \begin{lemma}\label{lem:test}{\em (Test Set Lemma)}
% For a set $P$ of $n$ points in $\bbR^d$ and a parameter $r$, we can compute in $O(nr^{1-1/d})$ time a set of at most $r$ hyperplanes with the following property: for any set of cells each containing at least $s$ points of $P$, if $\kappa_0$ is the maximum number of cells crossed by any hyperplane of $Q$, then the maximum number of cells crossed by any arbitrary plane is $O(a_0+n/(s\cdot r^{1/d}))$.
% \end{lemma}
% \begin{proof}
% This is done by computing a $(1/t)$-cutting $\Xi$ for the dual lines of the points of $P$ such that $\Xi$ has at most $r$ vertices in total, where $t$ can be chosen so that $t = \Theta(r^{1/d})$. $H$ is the just the set of hyperplanes in the primal plane dual to the vertices of $\Xi$. By the cutting lemma, this can be done in $O(nr^{1-1/d})$ time.
% Refer to Lemma 3.3 of \cite{ref:MatousekEf92} for the proof that $H$ has the desired property of the lemma.
% \end{proof}

\begin{lemma}\label{lem:test20}{\em(Test Set Lemma~\cite{ref:ChanOp12})}
For a set $P$ of $n$ points in $\bbR^d$, we can compute in $O(n^d)$ time a set $H$ (called {\em test set}) of $O(n^d)$ hyperplanes with the following property: for any set of cells each containing at least one point of $P$, if $\kappa$ is the maximum number of cells crossed by any hyperplane of $H$, then the maximum number of cells crossed by any hyperplane is $O(\kappa)$.
\end{lemma}
\begin{proof}
As discussed in \cite{ref:ChanOp12}, we can take all $O(n^d)$ hyperplanes that contain all $d$-tuple of points of $P$, which has the desired property of the lemma. These hyperplanes are dual to the vertices of the arrangement of all dual hyperplanes of the points of $P$. As the arrangement can be computed in $O(n^d)$ time~\cite{ref:EdelsbrunnerCo86}, the lemma follows. \end{proof}

Lemmas \ref{lem:partitiontree} and \ref{lem:test20} together lead to the following result.

%\begin{theorem}\label{theo:partition}
%{\em (Hierarchical Partition Theorem)}
%Given a set $P$ of $n$ points in $\bbR^d$ and a parameter $r$ with $r_0\leq r\leq n$ for a sufficiently large constant $r_0$, for $b=\log^\rho r$ for a sufficiently large constant $\rho>0$, there exists a sequence  $\Pi_0,\Pi_1,\ldots,\Pi_{k+1}$ with $k=\lceil \log_b r\rceil$ and $b'=\lceil r/b^{k}\rceil$, where each $\Pi_i$ is a collection of disjoint simplicial cells (i.e., each cell is a simplex) whose union covers $P$ with the following properties: (1) $\Pi_0$ has only one cell that is $\bbR^d$ and the number of cells of $\Pi_i$ is $O(b'\cdot b^{i-1})$ for $i\geq 1$ (in particular, $\Pi_{k+1}$ has $O(r)$ cells; the total number of cells in all collections is also $O(r)$);
%(2) each cell of $\Pi_i$ contains at least one point and at most $2n/(b'\cdot b^{i-1})$ points of $P$ for all $i\geq 0$ (in particular, each cell of $\Pi_{k+1}$ contains at most $2n/r$ points); (3) each cell in $\Pi_{i+1}$ is contained in a single cell of $\Pi_i$; (4) each cell of $\Pi_i$ contains $O(b)$ cells of $\Pi_{i+1}$ for $i\geq 1$ and the cell of $\Pi_0$ contains $O(b')$ cells of $\Pi_1$; (5) any hyperplane crosses at most $O((b'\cdot b^{i-1})^{1-1/d}+\log^{O(1)}n)$ cells of $\Pi_i$ for all $i\geq 1$.
%All collections of cells can be constructed in $O(n^{d^2}\cdot (r^{2-2/d}+\log^{O(1)}n))$ time.
%\end{theorem}
\begin{theorem}\label{theo:partition}
{\em (Hierarchical Partition Theorem)}
Given a set $P$ of $n$ points in $\bbR^d$ and a parameter $r$ with $r_0\leq r\leq n$ for a sufficiently large constant $r_0$, for $b=\log^\rho r$ for a sufficiently large constant $\rho>0$, there exists a sequence  $\Pi_0,\Pi_1,\ldots,\Pi_{k+1}$ with $k=\lfloor \log_b r\rfloor$ and $b'=\lceil r/b^{k}\rceil$, where each $\Pi_i$ is a collection of disjoint simplicial cells (i.e., each cell is a simplex) whose union covers $P$ with the following properties:
\begin{enumerate}
  \item $\Pi_0$ has only one cell that is $\bbR^d$ and the number of cells of $\Pi_i$ is $O(b'\cdot b^{i-1})$ for $i\geq 1$ (in particular, $\Pi_{k+1}$ has $O(r)$ cells; the total number of cells in all collections is also $O(r)$).
  \item Each cell of $\Pi_i$ contains at least one point and at most $2n/(b'\cdot b^{i-1})$ points of $P$ for all $i\geq 0$ (in particular, each cell of $\Pi_{k+1}$ contains at most $2n/r$ points).
  \item Each cell in $\Pi_{i+1}$ is contained in a single cell of $\Pi_i$.
  \item Each cell of $\Pi_i$ contains $O(b)$ cells of $\Pi_{i+1}$ for $i\geq 1$ and the cell of $\Pi_0$ contains $O(b')$ cells of $\Pi_1$.
  \item Any hyperplane crosses at most $O((b'\cdot b^{i-1})^{1-1/d}+\log^{O(1)}n)$ cells of $\Pi_i$ for all $i\geq 1$.
\end{enumerate}
All collections of cells can be constructed in $O(n^{d^2}\cdot (r^{2-2/d}+\log^{O(1)}n))$ time.
\end{theorem}
\begin{proof}
We just apply Lemma~\ref{lem:partitiontree} with $H$ as the test set given in Lemma~\ref{lem:test20}, which can be computed in $O(n^d)$ time. Since $m=O(n^d)$ and $r\leq n$, we obtain the theorem from Lemma~\ref{lem:partitiontree}.
\end{proof}

The collections of cells of Theorem~\ref{theo:partition} naturally form a tree structure, called a {\em hierarchical partition tree}, in which each node corresponds to a cell. More specifically, the only cell in $\Pi_0$ is the root. Cells of $\Pi_{k+1}$ are the leaves. If a cell $\Delta\in \Pi_i$ contains another cell $\Delta'\in \Pi_{i+1}$, then $\Delta$ is the parent of $\Delta'$ and $\Delta'$ is a child of $\Delta$. As such, each node of the tree has $O(b)$ children (the root has $O(b')$ children).
Although the construction time of Theorem~\ref{theo:partition} is relatively large, it can usually be reduced (e.g., to $O(n^{1+\epsilon})$ time) in applications by constructing an ``upper'' partition tree using other techniques (e.g., \cite{ref:MatousekEf92}) and then processing the leaves (each containing a small number of points) using Theorem~\ref{theo:partition}, as will be demonstrated in the subsequent sections.

%Note that the total number of cells is $O(r)$.

\section{Simplex range counting}
\label{sec:simcount}

Given a set $P$ of $n$ points in $\bbR^d$, the problem is to construct a data structure so that the number of points of $P$ inside a query simplex can be quickly computed.
If we set $r=n$ in Theorem~\ref{theo:partition}, we can have a data structure of $O(n)$ space and $O(b\cdot n^{1-1/d})$ query time, which is not $O(n^{1-1/d})$ as $b=\Theta(\log n)$.
%the query time is not optimal.
In the following, we reduce the query time to $O(n^{1-1/d}/\log^{\Omega(1)} n)$.

For any region $R$ in the plane, let $P(R)$ denote the subset of points of $P$ in $R$.

Setting $r=n/b^{2d/(d-1)}$ with $b=\log^\rho n$, we apply Theorem~\ref{theo:partition} to obtain a partition tree $T$ with collections $\Pi_i$, $0\leq i\leq k+1$. The total number of cells is $O(r)$. For each cell $\Delta$, we store $|P(\Delta)|$. By Theorem~\ref{theo:partition}, each cell in $\Pi_{k+1}$ contains $O(n/r)=O(b^{2d/(d-1)})=O(\log^{2d\rho/(d-1)} n)$ points of $P$. The runtime to construct $T$ is $O(n^{d^2+2})$.

Given a query simplex $\sigma$, starting from the root of $T$, for each cell $\Delta$ of $T$, if $\Delta$ is contained in $\sigma$, then we add $|P(\Delta)|$ to a total count. If $\Delta$ is completely outside $\sigma$, then we ignore it. Otherwise, a bounding halfplane of $\sigma$ must cross $\Delta$ and we proceed on all children of $\Delta$ unless $\Delta$ is a leaf. In this way, we obtain a set $V$ of $O(r^{1-1/d})$ leaf cells that are crossed by the bounding halfplanes of $\sigma$. The runtime is $O((r/b)^{1-1/d}\cdot  b)$, which is $O(r^{1-1/d}\cdot  b^{1/d})$.
%bounded by $O(n^{1-1/d}/b)$ as $r=n/b^{2d/(d-1)}$.

We now build the data structure recursively on the points in $P(\Delta)$ for each leaf cell $\Delta$ of $T$.
%Let $S(n)$ and $Q(n)$ be the space (number of cells) and query time, respectively.
If $Q(n)$ is the query time, we have the following recurrence relation:
\begin{equation}\label{equ:new10}
    %\begin{split}
    Q(n)  = O(r^{1-1/d}\cdot b^{1/d}) + O(r^{1-1/d})\cdot Q_1(n/r),
    %& = O\left(\frac{n^{1-1/d}}{\log^\rho n}\right)+O\left(\frac{n^{1-1/d}}{\log^{2\rho}n}\right)\cdot Q_1(\log^{2d\rho/(d-1)} n),
    %\end{split}
\end{equation}
%$$Q(n)=O\left(\frac{n^{1-1/d}}{\log^\rho n}\right)+O\left(\frac{n^{1-1/d}}{\log^{2\rho}n}\right)\cdot Q_1(\log^{2d\rho/(d-1)} n),$$
where $Q_1(\cdot)$ is the query time for each leaf cell $\Delta$, which contains $O(n/r)=O(\log^{2d\rho/(d-1)} n)$ points of $P$.

To solve $Q_1(n/r)$, we preprocess $P(\Delta)$ for each leaf cell $\Delta\in T$ recursively as above by using different parameters. Specifically, let $n_1=|P(\Delta)|$, which is $O(n/r)$. Let $\tau>0$ be an arbitrarily small constant to be set later. Setting $r_1=n_1/\log^{\tau}n$ with $b_1=\log^{\rho}n_1$, we apply Theorem~\ref{theo:partition} to construct a partition tree $T(\Delta)$ in $O(n_1^{d^2+2})$ time. The total time for constructing $T(\Delta)$ for all leaf cells $\Delta$ of $T$ is bounded by $O(n^{d^2+2})$.  Using $T(\Delta)$ to handle queries on $P(\Delta)$ and following the same analysis as above, we obtain
\begin{equation}\label{equ:new20}
    %\begin{split}
    Q_1(n_1) = O(r_1^{1-1/d}\cdot b_1^{1/d}) + O(r_1^{1-1/d})\cdot Q_2(n_1/r_1),
    %& = O\left(\frac{n^{1-1/d}}{\log^\rho n}\right)+O\left(\frac{n^{1-1/d}}{\log^{2\rho}n}\right)\cdot Q_1(\log^{2d\rho/(d-1)} n),
    %\end{split}
\end{equation}
where $Q_2(\cdot)$ is the query time for each leaf cell of $T(\Delta)$, which contains $O(n_1/r_1)$ points of $P$.

Combining \eqref{equ:new10} and \eqref{equ:new20} leads to
\begin{equation*}
    \begin{split}
        Q(n) & = O(r^{1-1/d}\cdot b^{1/d}) + O(r^{1-1/d})\cdot Q_1(n/r)\\
             & = O(r^{1-1/d}\cdot b^{1/d}) + O(r^{1-1/d}\cdot r_1^{1-1/d}\cdot b_1^{1/d}) + O(r^{1-1/d}\cdot r_1^{1-1/d})\cdot Q_2(n_1/r_1)\\
             & = O(r^{1-1/d}\cdot b^{1/d}) + O\left(r^{1-1/d}\cdot \left(\frac{n_1}{\log^{\tau} n}\right)^{1-1/d}\cdot b_1^{1/d}\right) + O\left(r^{1-1/d}\cdot \left(\frac{n_1}{\log^{\tau} n}\right)^{1-1/d}\right)\cdot Q_2(n_1/r_1)\\
             & = O(r^{1-1/d}\cdot b^{1/d}) + O\left(r^{1-1/d}\cdot \left(\frac{n}{r\cdot \log^{\tau} n}\right)^{1-1/d}\cdot b_1^{1/d}\right) + O\left(r^{1-1/d}\cdot \left(\frac{n}{r\cdot \log^{\tau} n}\right)^{1-1/d}\right)\cdot Q_2(n_1/r_1)\\
             & = O(r^{1-1/d}\cdot b^{1/d}) + O\left(\left(\frac{n}{\log^{\tau} n}\right)^{1-1/d}\cdot b_1^{1/d}\right) + O\left(\left(\frac{n}{\log^{\tau} n}\right)^{1-1/d}\right)\cdot Q_2(n_1/r_1)\\
             & =  O\left(\frac{n^{1-1/d}}{\log^{(2-1/d)\cdot \rho} n}\right) + O\left(\left(\frac{n}{\log^{\tau} n}\right)^{1-1/d}\cdot \log^{\rho/d}\log n\right) + O\left(\left(\frac{n}{\log^{\tau} n}\right)^{1-1/d}\right)\cdot Q_2(\log^{\tau}n)\\
             & =  O\left(\frac{n^{1-1/d}}{\log^{\Omega(1)} n}\right) + O\left(\left(\frac{n}{t}\right)^{1-1/d}\right)\cdot Q_2(t),\\
    \end{split}
\end{equation*}
where $t=\log^{\tau}n$.

%Recursing one more time leads to:
%$$Q(n)=O\left(\frac{n^{1-1/d}}{\log^\rho\log n}\right)+O\left(\frac{n^{1-1/d}}{\log^{2\rho}\log n}\right)\cdot Q_1(\log^{2d\rho/(d-1)} \log n)$

In summary, the above first builds a partition tree $T$ and then builds a partition tree $T(\Delta)$ for each leaf $\Delta$ of $T$ (so there are two recursive steps but with different parameters). For notational convenience, we still use $T$ to refer to the entire tree (by attaching $T(\Delta)$ for all leaves $\Delta$), which has $O(n/t)$ leaves, each containing $O(t)$ points. The total space is bounded by $O(n)$ since there are only two recursive steps. In Section~\ref{sec:simcountsub}, by using the property that $t$ is very small, we show that after $O(n)$ space and $O(n\log n)$ time preprocessing, each simplex range counting query on any leaf cell of $T$ can be answered in $O(\log t)$ time (i.e., $Q_2(t)=O(\log t)$, which is $O(\log\log n)$; we consider the query on each leaf cell a {\em subproblem}). As such, we obtain that $Q(n)=O(n^{1-1/d}/\log^{\Omega(1)} n)$. The total preprocessing time is $O(n^{d^2+2})$, dominated by the time for constructing $T$. We thus have the following result.


\begin{lemma}\label{lem:counting}
Given a set $P$ of $n$ points in $\bbR^d$, there is a data structure of $O(n)$ space that can compute the number of points of $P$ in any query simplex in $O(n^{1-1/d}/\log^{\Omega(1)} n)$ time. The data structure can be built in $O(n^{d^2+2})$ time.
\end{lemma}


We will further reduce the preprocessing time to $O(n^{1+\epsilon})$ in Section~\ref{sec:simcountpretime}.

\subsection{Solving the subproblems}
\label{sec:simcountsub}

We first consider halfspace range counting queries and then extend the technique to the simplex case.

\paragraph{A basic data structure.}
Let $A$ be a set of $t$ points in $\bbR^d$. We first build a straightforward data structure (called a {\em basic data structure}) of $O(t^d)$ space in $O(t^{d+1})$ time that can answer each halfspace range counting query on $A$ in $O(\log t)$ time.

Let $H$ be the set of dual hyperplanes of $A$. We compute the arrangement $\calA$ of $H$ in $O(t^d)$ time and space~\cite{ref:EdelsbrunnerCo86}. We then build a point location data structure on $\calA$, which can be done in $O(t^d)$ time and supports $O(\log t)$-time point location queries~\cite{ref:ChazelleCu93}. In addition, for each face $f$ of $\calA$, we compute the number of hyperplanes above $f$ (resp., below $f$) and store these two numbers at $f$, e.g., by checking every hyperplane of $A$. This finishes our preprocessing, which can be done in $O(t^{d+1})$ time and uses $O(t^d)$ space. The preprocessing time can be reduced to $O(t^d)$, e.g., by taking an Eulerian tour of the dual graph of the arrangement.

Given a query halfspace $\sigma$, the goal is to compute the number of points of $A$ inside $\sigma$. Without loss of generality, we assume that $\sigma$ is an upper halfspace.
Then, it is equivalent to computing the number of hyperplanes of $H$ below $p$, where $p$ is the dual point of the bounding hyperplane of $\sigma$. Using the point location data structure, we find the face $f$ of $\calA$ that contains $p$; $f$ stores the number of hyperplanes of $H$ below it and we return that number as our answer to the query. The query time is thus $O(\log t)$.

\paragraph{Handling halfspace queries.}
Next, we show that after $O(n\log n)$ time and $O(n)$ space preprorcessing we can answer each halfspace range counting query  in $O(\log t)$ time on $P(\Delta)$ for each leaf cell $\Delta$ of our partition tree $T$.

We build an algebraic decision tree $T_D$ for the arrangement construction algorithm~\cite{ref:EdelsbrunnerCo86} on a set of $t$ hyperplanes in $\bbR^d$ so that each node of $T_D$ corresponds to a comparison in the algorithm. The height of $T_D$ is $O(t^d)$ and $T_D$ has $2^{O(t^d)}$ leaves. Each leaf $v$ of $T_D$ corresponds to a ``configuration'' of a set of $t$ hyperplanes in the following sense. Let $A$ be a set of $t$ hyperplanes with indices from $1$ to $t$. Following the decision tree $T_D$ in a top-down manner, we can reach a leaf $v$ such that all comparisons of the nodes in the path of $T_D$ from the root to $v$ are consistent with $A$; we say that $A$ has the same configuration as $v$. Let $A$ and $B$ are two sets of $t$ hyperplanes each. Let $\calA_A$ and $\calA_B$ be the arrangements of $A$ and $B$, respectively.
If the configurations of $A$ and $B$ are both the same as a leaf $v$ of $T_D$, then
there is a one-to-one correspondence between faces of $\calA_A$ and faces of $\calA_B$ such that if a face $f$ of $\calA_A$ corresponds to a face $f'$ of $\calA_B$, then the $i$-th hyperplane of $A$ is above $f$ if and only if the $i$-th hyperplane of $B$ is above $f'$.

In light of the above observation, we do the following preprocessing. For each leaf $v$ of $T_D$, let $A_v$ be a set of $t$ hyperplanes whose configuration corresponds to that of $v$ (note that the sets $A_v$'s for all leaves $v$ can be constructed in $t^d\cdot 2^{O(t^d)}$ time by following $T_D$, which basically enumuerates all possible configurations for the arrangements of a set of $t$ hyperplanes). We construct the above basic data structure on $A_v$, denoted by $\calD_v$. Doing this for all leaves of $T_D$ takes $t^d\cdot 2^{O(t^d)}$ time and space, which is bounded by $O(n)$ since $t=\log^{\tau}n$ if we choose a small enough $\tau$.

% Let $A=\{a_1,a_2,\ldots,a_t\}$ and $B=\{b_1,b_2,\ldots,b_t\}$ be two sets of $t$ hyperplanes each in $\bbR^d$. at the same point.
% Following the literature, e.g.,\cite{ref:AronovSu21,ref:ChanHo23}, the {\em order type} of $A$ (resp., $B$) refers to for each intersection line formed by $d-1$ hyperplanes of $A$ (resp., $B$) the order of its intersections with other hyperplanes. As such, $A$ and $B$ have the same order type if the following is true: for each intersection line $\ell$ formed by $d-1$ hyperplanes of $A$ with indices $i_1,i_2,\ldots,i_{d-1}$ and another intersection $\ell'$ formed by $d-1$ hyperplanes of $B$ also with indices $i_1,i_2,\ldots,i_{d-1}$, if $j_1,j_2,\ldots,j_{t-d+1}$ are the indices of the other hyperplanes of $A$ ordered by their intersections with $\ell$ and $j'_1,j'_2,\ldots,j'_{t-d+1}$ are the indices of the other hyperplanes of $B$ ordered by their intersections with $\ell'$, then $j_i=j_i'$ for all $1\leq i\leq t-d+1$.

