	\hspace*{3.125cm}\includegraphics[trim = 4cm 2cm 0 0, scale=0.6]{Figures/FinalFigures/sphInterpolation.png}
	\caption{Illustration of the SPH numerical discretization of a periodic field function, $\bm{f}(\bm{x})$, over domain, $\Omega$, with boundary, $\partial \Omega$. The discretization of the field function is projected on to a two-dimensional plane, where each blue particle represents a subdomain, $\Omega_i$, with diameter, $\Delta x$, that has a kernel support, $\Omega_s$. } 
	\centering
	\label{fig:sphInterpolation_figure}
\end{figure}

