\subsection{The $\delta^{+}-$SPH formulation for the weakly compressible Navier--Stokes equations}
%===================================================================================
The SPH approximation and discretization presented in the previous subsection can be employed to numerically model a variety of partial differential equations, including elasticity, magnetohydrodynamics, fluid-dynamics, among many more \cite{price2012smoothed,liu2003smoothed,violeau2012fluid,dominguez2022dualsphysics}. The current work focuses on fluid dynamic problems where the weakly compressible Navier--Stokes  (WCNS) equations are discretized using the $\delta^{+}-$SPH formulation presented in \cite{sun2019consistent}. The derivation of the adopted SPH formulation is beyond the scope of this work, but a brief description is presented. More detail can be found in \cite{sun2019consistent, antuono2021smoothed}. The governing system of equations employed in this work read as follows:

\vspace*{0.5cm}
\noindent \textbf{Continuity}
\begin{equation}
	\begin{split}
		\frac{\text{d}\rho_i}{\text{d}t} =&- \rho_i \sum\limits_{j} [(\bm{u}_j+\delta\bm{u}_j)-(\bm{u}_i+\delta\bm{u}_i)]\cdot\nabla_iW_{ij}V_j\\&+\sum_j(\rho_j\delta\bm{u}_j+\rho_i\delta\bm{u}_i)\cdot\nabla_iW_{ij}V_j+\delta h c_0\mathcal{D}_i,
	\end{split}
	\label{eqn:sph_wcns_continuity}
\end{equation}
%
\noindent \textbf{Momentum}
\begin{equation}
	\begin{split}
		\frac{\text{d}\bm{u}_i}{\text{d}t} =&-\frac{1}{\rho_i}\sum_{j} \left(p_i+p_j\right) \nabla W_{ij}V_j + \frac{\rho_0}{\rho_i}\sum_{j}\pi_{ij}\nabla W_{ij}V_j \\
		&+\frac{\rho_0}{\rho_i}\sum_{j}(\bm{u}_j\boldsymbol{\otimes}\delta\bm{u}_j+\bm{u}_i\boldsymbol{\otimes}\delta\bm{u}_i)\cdot\nabla_iW_{ij}V_j
		\\&-\frac{\rho_0}{\rho_i}\bm{u}_i\sum_{j}(\delta\bm{u}_j-\delta\bm{u}_i)\cdot\nabla_iW_{ij}V_j+\bm{b}_i,
	\end{split}
	\label{eqn:sph_wcns_momentum}
\end{equation}
%
%
\noindent \textbf{Particle advection, equation of state, and particle volume evolution}
\begin{equation}
	\begin{split}
		\frac{\text{d}\bm{x}_i}{\text{d}t} =& \bm{u}_i+\delta\bm{u}_i, \hspace*{0.5cm} p_i = c_0^2 \left(\rho_i-\rho_0\right), \hspace*{0.5cm} 	V_i = \frac{m_i}{\rho_i}.
	\end{split}
	\label{eqn:sph_wcns_advection_eos_volume}
\end{equation}

In the present work, we employ the $C^2$ quintic Wendland kernel \cite{wendland1995piecewise, violeau2012fluid} and a cell-linked list algorithm is used to enable an efficient neighbor search, presented later in Section \ref{Section:PBROM}. Here, $\lVert \bm{x}_{ij}\rVert:=\lVert \bm{x}_{i}-\bm{x}_{j}\rVert$ and $t\in\left[0, T_f \right]$ denotes time with the final time $T_f\in\mathbb{R}_+$. For particle $i$, the density of a particle is defined by $\rho_i\in\mathbb{R}_{+}$, its velocity is defined by $\bm{u}_i\in\mathbb{R}^n$, and its position in Cartesian space is $\bm{x}_i\in\mathbb{R}^n$. The velocity perturbation, $\delta\bm{u}_i\in\mathbb{R}^n$, is defined as a regularization technique known as particle shifting, which enables regular particle distribution during simulations to avoid tensile instabilities and improve fidelity \cite{sun2019consistent, sun2017deltaplus}. The current framework imbues the SPH material derivative with this velocity perturbation such that for an arbitrary field variable, $f$, 
\begin{equation}
	\frac{\text{d} f}{\text{d} t}:=\frac{\partial f}{\partial t}+\nabla f \cdot \left(\bm{u}+\delta \bm{u}\right)=\frac{D f}{D t}+\nabla f \cdot \delta \bm{u}.
\end{equation}
The particle shifting formulation will be defined momentarily. Next, we adopt a linear equation of state to define particle pressure, $p_i\in\mathbb{R}$ in a weakly compressible sense. Here,  $c_0\in\mathbb{R}_+$ is the speed of sound (assumed constant), and is chosen so that density variations stay within a weakly compressible range, i.e., below a 1\% density variation from its reference density $\rho_0\in\mathbb{R}_+$. The speed of sound is defined by $c_0:=\frac{U_{\text{max}}}{M_a}$, where $U_{\text{max}}$ is the maximum expected velocity in a simulation and $M_a\in\mathbb{R}_+$ is the mach number taken to be $M_a=0.1$ for the adopted weakly compressible assumption, unless stated otherwise. The mass of all particles is assumed fixed and determined by the initialized volume, $V_0\in\mathbb{R}_+$, and reference density, such that $m_i=\rho_0 V_0$. The initialized volume is determined by the subdomain volume where, $V_0:=\Delta x^2$ for two-dimensional problems or $V_0:=\Delta x^3$ in three-dimensions. The particle volume $V_i$ is then updated according to Eq. \ref{eqn:sph_wcns_advection_eos_volume}. 

Equation \ref{eqn:sph_wcns_continuity} contains a numerically diffusive component, $\delta h c_0 \mathcal{D}_i$, to reduce spurious numerical artifacts from the weak-compressibility assumption. Here, $\delta\in\mathbb{R}_+$ is a tuning parameter conventionally taken to be 0.1, and a diffusive smoothing operator, $\mathcal{D}_i$, defined by
\begin{equation}
	\mathcal{D}_i:=2 \sum_j \left[(\rho_j-\rho_i)-\frac{1}{2}\left(\langle\nabla \rho\rangle_j^L+\langle\nabla \rho\rangle_i^L\right)\cdot(\bm{x}_{j}-\bm{x}_{i})\right]\frac{(\bm{x}_{j}-\bm{x}_{i})}{\lVert \bm{x}_{ij} \rVert^2}\cdot\nabla_i W_{ij}V_j,\\
\end{equation}
%
where
\begin{equation}
	\langle\nabla \rho\rangle_i^L:=\sum_j(\rho_j-\rho_i)\bm{L}_i\nabla_iW_{ij}V_j, \:\:\text{and}\:\: \bm{L}_i:=\left[\sum_j(\bm{x}_{j}-\bm{x}_{i})\boldsymbol{\otimes}\nabla_iW_{ij}V_j\right] ^{-1}.
\end{equation}
%
Equation \ref{eqn:sph_wcns_momentum} contains the viscous operator, 
\begin{equation}
	\pi_{ij}:=K\frac{(\bm{u}_{j}-\bm{u}_{i})\cdot(\bm{x}_{j}-\bm{x}_{i})}{\lVert \bm{x}_{ij} \rVert^2},\:\: \text{where} \:\: K:=2(n+2) \frac{\mu}{\rho_0} . 
\end{equation}
%
The coefficient, $\mu\in\mathbb{R}_+$, is the dynamic viscosity, where $\nu=\frac{\mu}{\rho_0}$ is known as the kinematic viscosity. The presented work only considers laminar viscosity, but recent works on large eddy simulation (LES) for the current framework can be referenced in \cite{antuono2021smoothed}. Future work will consider LES-SPH modeling. 

Finally, the particle shifting velocity, $\delta\bm{u}_i$, is defined by 
\begin{equation}
	\delta\bm{u}_i:=\text{min}\left(\lVert \delta\tilde{\bm{u}}_i \rVert, \frac{U_{\text{max}}}{2} \right)\frac{\delta\tilde{\bm{u}}_i}{\lVert \delta\tilde{\bm{u}_i} \rVert},
\end{equation}
%
where, 
\begin{equation}
	\delta\tilde{\bm{u}}_i :=-2h c_0 M_a \sum_j\left[1+\chi\left(\frac{W_{ij}}{W(\Delta x)}\right)\right]^{\xi}\nabla_i W_{ij}V_j.
\end{equation}
%
The constants $\chi$ and $\xi$ are set to 0.2 and 4, respectively. The kernel that takes in the subdomain length is defined similarly to Eqs.~\ref{eqn:smothed_function} and \ref{eqn:smothed_function_gradient} except $W(\Delta x):=W(\Delta x,h)$ for all particles. Careful consideration must be taken and corrections must be implemented for particle shifting at and near domain boundaries including free-surfaces, where details on these corrections can be found in \cite{sun2019consistent}. 
%
%===================================================================================
\subsection{Boundary conditions}
%===================================================================================
For wall-bounded domains, we adopt the formulation presented by \cite{adami2012generalized}. The present work does not consider dynamic boundaries. In the adopted approach, walls or boundaries are discretized by ``ghost" particles with the same initial spacing of the subdomain for each particle, $\Delta x$. Each ghost particle stays fixed in space but inherits fluid properties of the internal flow by means of interpolation over particles within their kernel support.  Specifically, let the set of ghost particles be defined by $\mathcal{N}_{g}$ where $\mathcal{N}_{g}\cap\mathcal{N}=\emptyset$, then for $i\in\mathcal{N}_g$ and $j\in\mathcal{N}$

\begin{equation}	
	\bm{u}_i=\frac{\sum\limits_j \bm{u}_jW_{ij}}{\sum\limits_j W_{ij}}, \:\:\: p_i=\frac{\sum\limits_j p_jW_{ij}+\bm{b}\cdot\sum\limits_j \rho_j(\bm{x}_i-\bm{x}_j)W_{ij}}{\sum\limits_j W_{ij}},
\end{equation}
%
where the density of the ghost particles can be back-tracked by the equation of state, such that
\begin{equation}	
	\rho_i=\frac{p_i}{c_0^2}+\rho_0.
\end{equation}
%
The velocity of the boundary particles can be split into tangent and normal components, $\bm{u}_i:=\bm{u}_i^{\tau} + \bm{u}_i ^{n} $. For slip boundary conditions the directions of both tangent and normal components remains untouched. For no-slip boundary conditions, the tangent component is negated, such that $\bm{u}_i=-\bm{u}_i^{\tau} + \bm{u}_i ^{n}  $.

%===================================================================================
\subsection{Dynamical system abstraction}
%===================================================================================
The current work rewrites Eqs.~\ref{eqn:sph_wcns_continuity}-\ref{eqn:sph_wcns_advection_eos_volume} in vector form, as it becomes a primary construct in presenting the proposed meshless PMOR method later.  Here, the vector $\bm{w}_i:=\left\{\rho_i, \bm{u}_i^T, \bm{x}_i^T\right\}$, contains $d-$states or $d-$degrees-of-freedom of each particle, where $d=5$ in the current work. Then the FOM state vector reads as $\bm{w}:=\left\{\bm{w}_1,\ldots, \bm{w}_N\right\}\in\mathbb{R}^{N_d}$, where $N_d=dN$. Using this notation, Eqs.~\ref{eqn:sph_wcns_continuity}-\ref{eqn:sph_wcns_advection_eos_volume}, can be rewritten as
\begin{equation}
	\frac{\text{d}\bm{w}}{\text{d}t}=\bm{f}(\bm{w}, t; \bm{\mu}),\:\:\: \bm{w}(0,\bm{\mu})=\bm{w}^0(\bm{\mu}),
	\label{eqn:sph_dynamical_system}
\end{equation}
where $\bm{w}:[0, T_f] \times \mathcal{P} \rightarrow \mathbb{R}^{N_d}$ is the time-dependent, parameterized state that is implicitly defined as the solution to Eq.~\ref{eqn:sph_dynamical_system}, with parameters $\bm{\mu}\in\mathcal{P}$. The parametric space of $n_{\mu}$ parameters is denoted by $\mathcal{P}\subseteq \mathbb{R}^{n_{\mu}}$ and $\bm{w}^0:\mathcal{P}\rightarrow\mathbb{R}^{N_d}$ is the parametrized initial condition. Finally, $\bm{f}: \mathbb{R}^{N}\times[0, T_f]\times\mathcal{P}\rightarrow\mathbb{R}^{N_d}$ denotes the semi-discrete SPH functional, i.e., the right-hand side of Eqs.~\ref{eqn:sph_wcns_continuity}-\ref{eqn:sph_wcns_advection_eos_volume} in vector form.

%===================================================================================
\subsection{Time integration}
%===================================================================================
The present work adopts a fourth-order Runge--Kutta (RK4) time integration scheme. For notational convenience, the temporal and parametric arguments of the SPH functional are suppresed. The time-discrete form of Equation \ref{eqn:sph_dynamical_system} reads as

\begin{equation}
	\begin{split}
		&\bm{w}^{\tilde{n},0}=\bm{w}^{\tilde{n}},\\
		&\bm{w}^{\tilde{n},1}=\bm{w}^{\tilde{n},0}+\frac{\Delta t}{2}\bm{f}(\bm{w}^{\tilde{n},0}),\\
		&\bm{w}^{\tilde{n},2}=\bm{w}^{\tilde{n},0}+\frac{\Delta t}{2}\bm{f}(\bm{w}^{\tilde{n},1}),\\
		&\bm{w}^{\tilde{n},3}=\bm{w}^{\tilde{n},0}+{\Delta t}\bm{f}(\bm{w}^{\tilde{n},2}),\\
		&\bm{w}^{\tilde{n},4}=\bm{w}^{\tilde{n},0}+\frac{\Delta t}{6}\left[\bm{f}(\bm{w}^{\tilde{n},0}) + 2\bm{f}(\bm{w}^{\tilde{n},1}) + 2\bm{f}(\bm{w}^{\tilde{n},2}) + \bm{f}(\bm{w}^{\tilde{n},3})\right],\\
		&\bm{w}^{{\tilde{n}+1}}=\bm{w}^{\tilde{n},4}.
	\end{split}
	\label{eqn:sph_rungekutta}
\end{equation}
%
where the first superscript in $\bm{w}^{\tilde{n},k}$ denotes the $\tilde{n}$\textsuperscript{th} time-step, where $\tilde{n}\in\mathbb{N}(N_t)$, $N_t\in\mathbb{N}$ denotes the final number of time-steps taken, and $\mathbb{N}(N_t):=\{1,\ldots,N_t\}$. The second superscript, $k\in\mathbb{N}$, in the state vector denotes the $k$\textsuperscript{th} Runge-Kutta sub-step. The absence of a second superscript denotes a whole time step. Finally, the current work adopts uniform time-steps and a conservative CFL condition

\begin{equation}
	\Delta t\leq CFL \frac{h}{c_0},
\end{equation}
%
where $CFL=1.5$. Future work will investigate employing adaptive time-stepping in PMORs as it is traditionally done for SPH. 
%
%===================================================================================
% 					S.3: PROJECTION BASED REDUCED-ORDER MODELING
%===================================================================================
\section{Projection-based reduced order modeling} \label{Section:PBROM}
%===================================================================================
The objective of the proposed work is to transform the $N_d$-dimensional dynamical system presented in Eq.~\ref{eqn:sph_dynamical_system} into a $M$-dimensional dynamical system, where $M\ll N_d$. However, a main challenge with constructing a transformation on a low-dimensional subspace is the unstructured, dynamic, and mixing numerical topology, namely the particle positions, $\bm{x}:=\{\bm{x}_1^T, \ldots, \bm{x}_N^T\}$, where $\bm{x}:[0, T_f] \times\mathcal{P}\rightarrow \mathbb{R}^n$. As particles mix, their trajectories may follow a chaotic path, where a perturbation to the velocity field or pressure can lead to significant trajectory deviations between initial neighbors. Thereby, initial neighboring particles may encounter vastly different flow characteristics as time evolves, which severely impacts the subspace dimensionality in which the dynamical system evolves; this will be quantitatively shown in Section \ref{Section:NumericalExperiments}. To combat the unstructured, dynamic, and mixing particle behavior, the proposed framework treats particles as topological field probes, separate from the low-dimensional subspace where the density and velocity field evolve. Thereby, the low-dimensional manifold that is to be discovered \emph{excludes} the dynamic contributions of the particles themselves. 

The reformulated dynamical system is now presented. However, before proceeding, it is important to note that while the presented SPH equations are in Lagrangian form, the model reduction framework projects the low-dimensional dynamics onto an Eulerian reference frame, which requires advecting modal information through the reference space - more on this momentarily. In the reformulated dynamical system, let the vector $\bm{\omega}_i:=\{\rho_i,\bm{u}_i^T\}$ contain $\bar{d}$-states for particle $i$, where $\bar{d}=3$ in the current work for two dimensions. Then the restructured state vector reads as $\bm{\omega}:=\{\bm{\omega}_1, \ldots, \bm{\omega}_N\}\in\mathbb{R}^{N_{\bar{d}}}$ and the resulting dynamical system reads:
\begin{equation}
	\frac{\text{d}\bm{\omega}}{\text{d}t}=\bar{\bm{f}}(\bm{x}, \bm{\omega},t;\bm{\mu}),\:\:\: \bm{\bm{\omega}}(\bm{x}^0,0,\bm{\mu})=\bm{\bm{\omega}}^0(\bm{x}^0,\bm{\mu}).
	\label{eqn:reference_dynamical_system}
\end{equation}
%
where the particle advection is updated by
\begin{equation}
	\frac{\text{d} \bm{x}_i}{\text{d} t}=\bm{u}_i+\delta \bm{u}_i, \:\:\: \bm{x}(0)=\bm{x}^0.
\end{equation}
%
Here, $\bm{\omega}: [0, T_f]\times \mathcal{P} \rightarrow \mathbb{R}^{N_{\bar{d}}}$ is the restructured state and $\bar{\bm{f}}: \mathbb{R}^{{nN}}\times \mathbb{R}^{\bar{d}} \times [0, T_f] \times \mathcal{P} \rightarrow \mathbb{R}^{N_{\bar{d}}}$ denotes equations Eqs.~\ref{eqn:sph_wcns_continuity}-\ref{eqn:sph_wcns_advection_eos_volume} \emph{excluding} particle advection but \emph{includes field variable advection}. Finally, $\bm{\omega}^0:\mathcal{P}\rightarrow\mathbb{R}^{N_{\bar{d}}}$ is the parametrized initial condition of the reference state, and $\bm{x}^0 \in \mathbb{R}^{nN}$ is the initial particle configuration.

As previously mentioned, the dynamics are projected onto a low-dimensional Eulerian reference space, which means that modal advection must be subtracted from the SPH functional form defined by the material derivative. For an arbitrary field variable in the consisten $\delta^{+}$-SPH method \cite{sun2019consistent}, the quasi-Lagrangian material derivative is expressed as 
\begin{equation}
	\frac{\text{d} f}{ \text{d} t}=\frac{\partial f}{\partial t}+\nabla f \cdot \left(\bm{u}+\delta \bm{u}\right).
\end{equation}
%
Thereby, to solve the low-dimensional equations in reference space, the advection components of the quasi-Lagrangian material derivative must be subtracted from the SPH equations. In other words,

\begin{equation}
\underbrace{\frac{\partial f}{\partial t}}_{\text{reference space dynamics}}=\underbrace{\frac{\text{d} f}{ \text{d} t}}_{\delta^+\text{SPH ODE}}-\underbrace{\nabla f \cdot \left(\bm{u}-\delta \bm{u}\right)}_{\text{field advection terms}}.
\end{equation}
%
However, particle shifting advection is maintained to enforce regular particle distribution. The following advection equations are subtracted from \ref{eqn:sph_wcns_continuity} and \ref{eqn:sph_wcns_momentum} \\

\noindent \textbf{Continuity advection}
\begin{equation}
	\begin{split}
		\nabla \rho_i \cdot \bm{u}_i=\sum_{j}\left(\rho_j\bm{u}_j+\rho_i\bm{u}_i\right)\cdot \nabla W_{ij}V_j - \rho_i\sum_{j}\left(\bm{u}_j-\bm{u}_i\right)\cdot \nabla W_{ij}V_j 
	\end{split}
	\label{eqn:continuity advection}
\end{equation}

\noindent \textbf{Momentum advection}
\begin{equation}
	\begin{split}
			\nabla \bm{u}_i \cdot \bm{u}_i=\sum_{j}\left(\bm{u}_j\otimes\bm{u}_j+\bm{u}_i\otimes\bm{u}_i\right)\cdot \nabla W_{ij}V_j -\bm{u}_i\sum_{j}\left(\bm{u}_j-\bm{u}_i\right)\cdot \nabla W_{ij}V_j .
	\end{split}
	\label{eqn:momentum advection}
\end{equation}
%
Subtracting Eqs.~\ref{eqn:continuity advection} and \ref{eqn:momentum advection} from \ref{eqn:sph_wcns_continuity} and \ref{eqn:sph_wcns_momentum}, respectively, therefore defines the meshless reference space dynamics functional, $\bar{\bm{f}}$.

Next, the proposed PMOR seeks an approximate solution to the restructured dynamical system in Eq.~\ref{eqn:reference_dynamical_system}. Namely, $\tilde{\bm{\omega}}\approx\bm{\omega}$, where the approximate solution can be represented by a linear combination between a trial basis, $\bm{\Phi}\in\mathbb{R}^{N_{\bar{d}}\times M}$, and generalized coordinates, $\hat{\bm{\omega}}\in\mathbb{R}^{M}$,
\begin{equation}
	\tilde{\bm{\omega}}=\bm{\Phi}\hat{\bm{\omega}}.
	\label{eqn:affine_approximation}
\end{equation}	
% 
The trial basis exists in the Stiefel manifold, i.e., for a full-column-rank matrix, $\bm{\mathcal{A}}\in\mathbb{R}^{q\times p}$, the Stiefel manifold is defined by $\mathcal{V}_p(\mathbb{R}^q)\equiv\{\bm{\mathcal{A}}\in\mathbb{R}^{q\times p}\vert \bm{\mathcal{A}}^T\bm{\mathcal{A}}=\bm{I}\}$, where ${\bm{\Phi}}\in\mathcal{V}_M(\mathbb{R}^{N_{\bar{d}}})$ and is comprised of $M$ orthonormal basis vectors,
\begin{equation}
	{\bm{\Phi}}\equiv\left[\bm{\phi}_1,\ldots, \bm{\phi}_M\right],
	\label{eqn:trial_basis}
\end{equation}
where $\bm{\phi}\in\mathbb{R}^{N_{\bar{d}}}$. Next, a test basis, $\bm{\Psi}\in{\mathbb{R}^{N_{\bar{d}}\times M}}$, is introduced and is assumed to also exist in the Stiefel manifold, ${\bm{\Psi}}\in\mathcal{V}_M(\mathbb{R}^{N_{\bar{d}}})$. The test basis is also comprised of $M$ orthonormal basis vectors,
\begin{equation}
	{\bm{\Psi}}\equiv\left[\bm{\psi}_1,\ldots, \bm{\psi}_M\right],
\end{equation}
%
where $\bm{\phi}\in\mathbb{R}^{N_{\bar{d}}}$. Substituting Eq.~\ref{eqn:affine_approximation} in Eq.~\ref{eqn:reference_dynamical_system} and taking the $L^2$ inner product with $\bm{\Psi}$ yields, 
\begin{equation}
	\bm{\Psi}^T\bm{\Phi}\frac{\partial \hat{\bm{\omega}}}{\partial t}=\bm{\Psi}^T\bar{\bm{f}}(\bm{\Phi}\hat{\bm{\omega}},t;\bm{\mu}).
	\label{eqn:L2_projected_RFOM}
\end{equation}
After some algebraic manipulation of Eq.~\ref{eqn:L2_projected_RFOM}, a low-dimensional dynamical system of equations is obtained, 
\begin{equation}
	\frac{\partial \hat{\bm{\omega}}}{\partial t}=	\hat{\bm{f}}(\bm{\Psi},\bm{\Phi}\hat{\bm{\omega}},t;\bm{\mu}),
	\label{eqn:mPMOR}
\end{equation}
where $\hat{\bm{f}}:=\lbrack\bm{\Psi}^T\bm{\Phi}\rbrack^{-1} \bm{\Psi}^T\bar{\bm{f}}(\bm{\Phi}\hat{\bm{\omega}},t;\bm{\mu})$. Finally, the particle advection is enforced by the velocity vector, $\tilde{\bm{u}}_i$, from the approximate solution in Eq.~\ref{eqn:affine_approximation}, 
\begin{equation}
	\frac{\text{d} \bm{x}_i}{\text{d} t}=\tilde{\bm{u}}_i+\delta \tilde{\bm{u}}_i.
	\label{eqn:mPMOR_particleAdvection}
\end{equation}
%
To evolve the low-dimensional system in Eq.~\ref{eqn:mPMOR} and Eq.~\ref{eqn:mPMOR_particleAdvection} in time, both equations can be integrated separately by the RK4 method presented in Eq.~\ref{eqn:mPMOR}.  

%===================================================================================
\subsection{Reference space}
%===================================================================================

To construct the trial basis we employ the POD. Traditionally, data snapshots of the solution vector are collected and stored in a matrix, $\bm{\mathcal{S}}\in\mathbb{R}^{N_{\bar{d}}\times N_{\mathcal{S}}}$, where  $N_{\mathcal{S}}\in\mathbb{N}$ denotes the number of snapshots stored. In the current work, temporal snapshots at some uniform spacing are considered where $N_{\mathcal{S}}\in[1, N_t]$. For instance, the snapshot tensor for a uniform spacing of one time step reads, 
\begin{equation}
	\bm{\mathcal{S}}:=\left[\bm{\omega}^1, \bm{\omega}^2, \ldots, \bm{\omega}^{N_{t}-1}, \bm{\omega}^{N_{t}} \right].
	\label{eqn:snapshot_normal}
\end{equation}
%
However, because the numerical topology of the solution snapshots evolves dynamically and mixes, the proposed work introduces a composition operator, $\mathcal{G}:\mathbb{R}^{nN} \times \mathbb{R}^{N_{\bar{d}}}\rightarrow\mathbb{R}^{N_{\bar{d}}}$, that maps the snapshots onto a fixed, discrete, meshless domain, defined as the reference space. This space is defined by interpolation points belonging to the set, $\mathcal{N}_{\mathcal{G}}$, with position vector, $\bm{x}_{\mathcal{G}}\in\mathbb{R}^{nN}$. The configuration of the reference space can theoretically be arbitrary, but the proposed work chooses either the initial configuration of SPH particles from the snapshot data or any ``relaxed" configuration, i.e., $\bm{x}_{\mathcal{G}}=\bm{x}^{0}$ or $\bm{x}_{\mathcal{G}}=\bm{x}^{\tilde{n}}$. Then the snapshot tensor in Eq.~\ref{eqn:snapshot_normal} can be expressed in the reference domain as, 
\begin{equation}
	\bm{\mathcal{S}}_{\mathcal{G}}:=\left[\mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^1, \mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^2, \ldots, \mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^{N_{t}-1}, \mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^{N_{t}} \right].
	\label{eqn:snapshot_reference}
\end{equation}
%
The composition operator is defined by an interpolation of the FOM state vector, $\bm{\omega}$, onto the reference space via the SPH discrete approximation in Eq.~\ref{eqn:smoothing_function_interpolation} \cite{magargal2022lagrangian}. For instance, let, $\mathcal{G}(\bm{x}_{i,\mathcal{G}},\bm{\omega}_i):=\{\rho_{i,\mathcal{G}}, \bm{u}_{i,\mathcal{G}}^T \}$, where
\begin{equation}
	\begin{split}
		\rho_{i,\mathcal{G}}:=&\frac{\sum_j\rho_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n}{\sum_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n},\\
		\bm{u}_{i,\mathcal{G}}:=&\frac{\sum_j \bm{u}_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n}{\sum_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n},
	\end{split}
	\label{eqn:reference_operator}
\end{equation}
%
where the Shepard filter is employed to normalize particles with incomplete support, which normally exist near boundaries. Here, $i\in\mathcal{N}_{\mathcal{G}}$ and $j\in\mathcal{N}$. Notice that Eq.~\ref{eqn:reference_operator} employs a fixed $n$-dimensional weight, $\Delta x^n$, equal to the subdomain diameter of the SPH discretization chosen for the reference domain. An illustration of the reference space mapping is shown in Fig.~\ref{fig:LEMmapping}. A trial basis can now be defined by factoring the reference space snapshot matrix via the singular value decomposition, 

\begin{figure}[t!]
\includegraphics[trim = -2.5cm 8cm 0cm 7cm, scale=0.5]{Figures/FinalFigures/referenceSpace.png}
	\caption{Illustration of the SPH reference space on a periodic domain.} 
	\centering
	\label{fig:LEMmapping}
\end{figure}

\begin{equation}
	\bm{\mathcal{S}}_{\mathcal{G}}=\bm{U}\bm{\Sigma}\bm{V}^T,
\end{equation}
where , $\bm{U}\in\mathcal{V}_{N_{\bar{d}}}(\mathbb{R}^{N_{\bar{d}}})$, $\bm{\Sigma}\equiv\text{diag}(\sigma_i)\in\mathbb{R}^{N_{\bar{d}}\times N_{\mathcal{S}}}$ has monotonocally decreasing diagonal entries, and $\bm{V}\in\mathcal{V}_{N_{\mathcal{S}}}(\mathbb{R}^{N_{\mathcal{S}}})$. Finally, the trial basis is defined by taking the $M$ left singular vectors of $\bm{U}$, such that $M\ll\text{min}(N_d,N_{\mathcal{S}})$, where Eq.~\ref{eqn:trial_basis} is equivalent to $\bm{\Phi}\equiv\lbrack\bm{U}^1,\dots,\bm{U}^M\rbrack$. Pseudo-code for the reference space mapping is provided in Algorithm \ref{alg:reference space trial basis}.


\begin{algorithm}
	\caption{Constructing a trial basis of from reference space}\label{alg:reference space trial basis}
	\SetAlgorithmName{Algorithm}{}{}
	\SetKwInput{Input}{Input}
	\SetKwInput{Output}{Output}
	\SetKwFunction{FMain}{PolyharmonicSpline}
	\SetKwProg{Fn}{function}{:}{}
	\SetKwArray{State}{name}
	\Input{SPH simulation data, $\bm{x},\bm{\rho},\bm{u}\:\in\mathbb{R}^N$, and reference space domain, $\bm{x}_{\mathcal{G}}\in\mathbb{R}^N$.}
	\Output{Reference trial basis, $\bm{\Phi}$}
	\begin{doublespace}
		\vspace*{-.1cm}
		\tcp{Map SPH data onto reference space \vspace*{-.2cm}}
		\For
		{$n=0$ \KwTo $N_t$}{
			\For{$i=0$ \KwTo $N$} 
			{
				\ForEach{$j$ \textbf{in} $\mathcal{N}_{\Omega_s}^i$} 
				{
				\begin{equation*}
					\begin{split}
						\rho_{i,\mathcal{G}}:=&\frac{\sum_j\rho_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n}{\sum_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n}\\
					\bm{u}_{i,\mathcal{G}}:=&\frac{\sum_j \bm{u}_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n}{\sum_jW(\lVert \bm{x}_{i,\mathcal{G}}-\bm{x}_{j}\rVert, h)\Delta x^n}\\
					\end{split}
				\end{equation*}		
									\vspace*{-0.8cm} 
				}
			}

	    }
	\tcp{Collect reference snapshot matrix}
	$\bm{\mathcal{S}}_{\mathcal{G}}:=\left[\mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^1, \mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^2, \ldots, \mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^{N_{t}-1}, \mathcal{G}(\bm{x}_{\mathcal{G}},\bm{\omega})^{N_{t}} \right].$\vspace*{0.125cm}

	\tcp{Compute singular value decomposition of reference snapshot matrix}
	$\bm{U}\bm{\Sigma}\bm{V}^T=\textup{SVD}\left(\bm{\mathcal{S}}_{\mathcal{G}}\right)$.\vspace*{0.125cm}

	\tcp{Define low-dimensional reference trial basis}
	$\bm{\Phi}\equiv\lbrack\bm{U}^1,\dots,\bm{U}^M\rbrack.$
	\end{doublespace}

\end{algorithm}

%===================================================================================
\subsection{Approximation of the trial basis}
%===================================================================================
The present work leverages the notion that as  $N\rightarrow\infty$, the empirical trial basis becomes a function of space (i.e., there is an interpolation point at every point in space). Clearly, it is not possible to construct a trial basis with infinitely many particles or interpolation points. So, the present work instead approximates the infinite dimensional trial basis as a function of space. Specifically, scattered data approximation \cite{wendland2004scattered} via polyharmonic spline interpolation (PSI) is adopted, but a myriad meshless interpolants can be employed such as the moving least-squares method or radial basis functions, and even deep learning methods could be used to learn spatially continuous functions. The proposed trial basis approximation enables the unstructured, dynamic, and mixing numerical topology to inheret modal quantities from reference space. 

To construct a polyharmonic spline, data from the reference space trial basis is used to derive the interpolant weights. For each column, $m$, of the trial basis at the reference space point location, ${\bm{\phi}}^m(\bm{x}_{i, \mathcal{G}})$, the following interpolation is defined:

\begin{equation}
	{\bm{\phi}}^m(\bm{x}_{i, \mathcal{G}}):=\sum_{j}^{N}\xi_j^m\gamma(\lVert \bm{x}_{i, \mathcal{G}}- \bm{x}_{j, \mathcal{G}}\rVert)+\bm{\eta}^m\cdot\bm{q}_i,
	\label{eqn:PSI}
\end{equation}
%
where, $m\in\mathbb{N}(M)$. Here, $i\in\mathcal{N}_{\mathcal{G}}$ and $j\in\mathcal{N}_{\mathcal{G}}$. The scalar values $\xi_j^m \in \mathbb{R}$ are the unknown interpolation weights of the radial basis function,  $\bm{\eta}^m:=\lbrace \eta_1^m,\ldots, \eta_{n+1}^m \rbrace^T$ is a $(n+1)$-tuple of the unknown real-valued weights of the polynomial basis, and $\bm{q}_i:=\lbrace 1, \bm{x}_{i,\mathcal{G}}^T \rbrace$ is the polynomial basis constructed from the interpolation points in reference space. The function, $\gamma: \lbrack0,\infty)\rightarrow\mathbb{R}$, is taken to be a polyharmonic radial basis function, 
\begin{equation}
	\gamma(\lVert \bm{x}_i- \bm{x}_{j, \mathcal{G}}\rVert)=
	\begin{cases}
		\lVert \bm{x}_i- \bm{x}_{j, \mathcal{G}}\rVert^k & \text{when} \:\: k=1,3,5, \ldots\\
		\lVert \bm{x}_i- \bm{x}_{j, \mathcal{G}}\rVert^k \ln(	\lVert \bm{x}_i- \bm{x}_{j, \mathcal{G}}\rVert)& \text{when} \:\: k=2,4,6, \ldots
	\end{cases}.
\end{equation}
%
Obtaining the unknown interpolant weights, $\bm{\xi}^m:=\lbrace\xi_1^m,\ldots,\xi_{N}^m\rbrace^T$ and $\bm{\eta}^m$, in Eq.~\ref{eqn:PSI} requires solving a linear system of equations in the reference space for known modal quantities at the locations of the reference particles. The linear system reads as 

\begin{equation}
	\left[
	\begin{matrix}
		\bm{\Gamma} & \bm{{Q}} \\ 
		\bm{{Q}}^T &\bm{0}
	\end{matrix}
	\right]
	\left[
	\begin{matrix}
		\bm{\xi}^m \\ 
		\bm{\eta}^m 
	\end{matrix}
	\right]=
	\left[
	\begin{matrix}
		\bm{\phi}^m \\ 
		\bm{0}			
	\end{matrix}
	\right],
	\label{eqn:PSI_linear}
\end{equation}
where $\bm{\Gamma}_{ij}:=\gamma(\lVert \bm{x}_{i, \mathcal{G}}- \bm{x}_{j, \mathcal{G}}\rVert)$, $\bm{Q}:=\lbrace \bm{q}_1, \ldots, \bm{q}_N  \rbrace^T$, and $\bm{\phi}^m\equiv \bm{\phi}^m(\bm{x}_{\mathcal{G}})$. Once the weights are defined for each mode, the full trial basis can be approximated, that is, $\tilde{\bm{\Phi}}\approx{\bm{\Phi}}$, and $\tilde{\bm{\Phi}}(\bm{x}):=\lbrack \tilde{\bm{\phi}}(\bm{x})^1, \ldots, \tilde{\bm{\phi}}(\bm{x})^M\rbrack$. To approximate modal quantities, one simply calls Eq.~\ref{eqn:PSI} for each mode at arbitrary locations in space, $\bm{x}_{i}$, where $i\in\mathcal{N}$, such that 

\begin{equation}
	\tilde{\bm{\phi}}^m(\bm{x}_{i}):=\sum_{j}^{N}\xi_j^m\gamma(\lVert \bm{x}_{i}- \bm{x}_{j, \mathcal{G}}\rVert)+\bm{\eta}^m\cdot\bm{q}_i.
	\label{eqn:PSI_approximate}
\end{equation}
\begin{remark}
	\normalfont{Computing the weights in Eq.~\ref{eqn:PSI_linear} for the full $N$-dimensional reference domain is computationally expensive. The presented work avoids computing the dense linear system of equations over the global set of particles by leveraging the cell linked-list data structure used in the neighbor search algorithm for all simulations to construct local PSI systems. Specifically, local data points within the neighboring cells of a particle $i$ contribute to the PSI construction. Several local PSI systems are then constructed rather than one large and expensive PSI. Furthermore, adopting a local approach reduces the summation cost in Eq.~\ref{eqn:PSI} for online computations, where the summation is no longer done over the whole $N$-particle reference space, but online over a compact support of data points. For convenience, the cell linked-list algorithm employed is presented in Algorithm \ref{alg:cell linked-list}. An illustration and pseudo-code of the local PSI approach is also given in Fig.~\ref{fig:phsCells}. and Algorithm \ref{alg:polyharmonic spline}, respectively.}
\end{remark}

\begin{algorithm}[h!]
	\caption{Cell linked-list \cite{viccione2007fast}}\label{alg:cell linked-list}
	\SetAlgorithmName{Algorithm}{}{}
	\SetKwInput{Input}{Input}
	\SetKwInput{Output}{Output}
	\Input{Particle positions, $\bm{x}$; cell linked-list data structure, $\mathcal{\bm{C}}\in\mathbb{N}^K$ and $\mathcal{\bm{C}}^k\subset \mathcal{\bm{C}}$, where $K$ is the number of cells in the data structure and $k$ is the index of the $k$\textsuperscript{th} cell in the data structure. Note: the width of each cell is twice the smoothing length, i.e., $\alpha=2h$.}
	\Output{Populated cell data structure, $\mathcal{\bm{C}}$.}
	\begin{doublespace}
	\vspace*{-.1cm}
	\tcp{Populating cells with particle indices	\vspace*{-.2cm}}
			\For{$i=0$ \KwTo $N$} {
			{$\mathcal{\bm{C}}(i)=K\cdot\texttt{int}\left(\frac{x_i}{\alpha}\right)+\texttt{int}\left(\frac{y_i}{\alpha}\right)+1$}\\
			$\mathcal{\bm{C}}^k\leftarrow \mathcal{\bm{C}}(i)$ \Comment{Update the $k$\textsuperscript{th} cell index with the $i$\textsuperscript{th} particle} index}	
	\end{doublespace}   
{Note: to execute an efficient neighbor search, only search for neighboring particles in neighboring cells of the cell containing particle $i$.}
\end{algorithm}


\begin{algorithm}
	\caption{Trial basis polyharmonic spline construction}\label{alg:polyharmonic spline}
	\SetAlgorithmName{Algorithm}{}{}
	\SetKwInput{Input}{Input}
	\SetKwInput{Output}{Output}
	\SetKwFunction{FMain}{PolyharmonicSpline}
	\SetKwProg{Fn}{function}{:}{}
	\Input{Reference space particle positions, $\bm{x}$; cell linked-list data structure, $\mathcal{\bm{C}}$, reference space trial basis, $\bm{\Phi}$.}
	\Output{Interpolant weights, $\bm{\xi}$ and $\bm{\eta}$}
	\begin{doublespace}
		\vspace*{-.1cm}
		\tcp{Construct polyharmonic spline interpolants \vspace*{-.2cm}}
	\ForEach{Cell \normalfont{\textbf{in}} {$\mathcal{C}$}}
	{
		\For{$m=0$ \KwTo $M$} 
		{
			Solve Eq.~\ref{eqn:PSI_linear} using reference neighboring points in neighboring cells
		}
	}
						\vspace*{-0.25cm}
	\end{doublespace}
\end{algorithm}

