\subsection{A meshless Galerkin POD and adjoint Petrov--Galerkin PMOR}
%===================================================================================
The presented work adopts the traditional Galerkin POD and the adjoint Petrov--Galerkin PMOR \cite{parish2020adjoint}. In this work, the former employs the trial basis as the test basis itself, i.e., $\bm{\Psi}=\bm{\Phi}$. By employing the trial basis approximation, $ \tilde{\bm{\Phi}}\approx\bm{\Phi}$, the proposed meshless PMOR in Galerkin POD form reads as
%
\begin{equation}
	\frac{\partial \hat{\bm{\omega}}}{\partial t}=	 \tilde{\bm{\Phi}}^+\bar{\bm{f}}(\tilde{\bm{\Phi}}\hat{\bm{\omega}},t;\bm{\mu}),
	\label{eqn:mGPMOR}
\end{equation}
Here, the superscript, $+$, denotes the Moore-Penrose pseudo-inverse. 

For the adjoint Petrov--Galerkin PMOR, the test basis presented in \cite{parish2020adjoint} is adopted, where $\bm{\Psi}=\left[\left(\bm{I}-\tau\bm{\Pi}^{\prime T} \bm{J}^T\right)\bm{\Phi}\right]$, where $\bm{J}:=\frac{\partial \bar{\bm{f}}}{\partial \tilde{\bm{\omega}}}$ is the Jacobian of the SPH functional in the restructured dynamical system, of Eq.~\ref{eqn:reference_dynamical_system}, $\bm{\Pi}^{\prime}:=\left(\bm{I}-\bm{\Phi}\bm{\Phi}^{+}\right)$. The proposed meshless PMOR in adjoint Petrov--Galerkin form reads as
\begin{equation}
	\frac{\partial \hat{\bm{\omega}}}{\partial t}=	\tilde{\bm{\Phi}}^+\left(\bar{\bm{f}}(\tilde{\bm{\Phi}}\hat{\bm{\omega}},t;\bm{\mu})+\tau \bm{J}\bm{\Pi}^{\prime } \bar{\bm{f}}(\tilde{\bm{\Phi}}\hat{\bm{\omega}},t;\bm{\mu}) \right)
	\label{eqn:mAPGPMOR}
\end{equation}
%
The present work approximates the action of the Jacobian and orthogonal projection onto the SPH funcational via $ \bm{J}\bm{\Pi}^{\prime } \bar{\bm{f}}(\tilde{\bm{\omega}})\approx \frac{1}{\varepsilon}\left[\bar{\bm{f}}(\tilde{\bm{\omega}}+\varepsilon\bm{\Pi}^{\prime } \bar{\bm{f}}(\tilde{\bm{\omega}}))-\bar{\bm{f}}(\tilde{\bm{\omega}})\right]$, where $\varepsilon\sim O(10^{-5})$ is a perturbation, and the temporal and parametric arguments have been omitted for notational convenience. This approximation enables tractable computations of the APG method which would otherwise be expensive for an SPH framework, even with an analytical Jacobian, due to the non-local support of the SPH kernel. 

For both Galerkin and Petrov--Galerkin approaches, the particle advection is enforced by the velocity vector, $\tilde{\bm{u}}_i$, obtained from the back-projected approximate solution in Eq.~\ref{eqn:affine_approximation}, 
\begin{equation}
	\frac{\text{d} \bm{x}_i}{\text{d} t}=\tilde{\bm{u}}_i+\delta \tilde{\bm{u}}_i.
	\label{eqn:mGPMOR_particleAdvection}
\end{equation}
%
Again, to evolve the low-dimensional system in Eqs.~\ref{eqn:mGPMOR}, \ref{eqn:mAPGPMOR}, and Eq.~\ref{eqn:mGPMOR_particleAdvection} in time, both equations the RK4 method presented in Eq.~\ref{eqn:mGPMOR} can be employed. Finally, Eq.~\ref{eqn:mGPMOR}/\ref{eqn:mAPGPMOR} and Eq.~\ref{eqn:mGPMOR_particleAdvection} together present a \emph{meshless} PMOR framework, which is the \textbf{\emph{main contribution}} of the presented work. Algorithm \ref{alg:meshlessPMOR} provides pseudo code for the presented framework.


\begin{remark}
	\normalfont{The operator, $\bar{\bm{f}}$, has preserved all SPH operations in their meshless form. The operator $\tilde{\bm{\Phi}}$, derived from a reference space, also serves as a scattered-data interpolant, which is a meshless construct. It is important to note that the advection of the particles plays a significant role in enabling inherent numerical adaptivity, which is why the system maps the low-dimensional system in Eq.~\ref{eqn:mGPMOR} back to the meshless state via Eq.~\ref{eqn:affine_approximation}. However, the operational complexity to map back to the meshless state scales with $N_d$, and will require hyper-reduction to avoid expensive back-projection. Unfortunately, hyper-reduction techniques for meshless methods are also severely underdeveloped and are beyond the scope of the presented work. Current efforts to develop these techniques are underway and will be the focus for future work.}
\end{remark}

\begin{algorithm}
	\caption{Meshless PMOR algorithm}\label{alg:meshlessPMOR}
	\SetAlgorithmName{Algorithm}{}{}
	\SetKwInput{Input}{Input}
	\SetKwInput{Output}{Output}
	\SetKwFunction{FMain}{ProjectDynamics}
	\SetKwFunction{FMainBasis}{TrialBasisApproximation}
	\SetKwProg{Fn}{function}{(te):}{}
	\Input{Trial basis approximation, $\tilde{\bm{\Phi}}$, initial conditions $\hat{\bm{\omega}}^0$.}
	\Output{Low-dimensional state history $\hat{\bm{\omega}}^1, \hat{\bm{\omega}}^2, \ldots, \hat{\bm{\omega}}^{N_t}$ }
\begin{doublespace}
	\vspace*{-.2cm}
	\For
	{$n=0$ \KwTo $N_t$}{
			\tcp{RK 4 Stage 1}
			{1. Get approximate trial basis, $\tilde{\bm{\Phi}}(\bm{x}^{\tilde{n},0})$, via Eq.~\ref{eqn:PSI_approximate}.}\\
			{2. Compute the full SPH state vector: $\tilde{\bm{w}}^{\tilde{n},0}=\tilde{\bm{\Phi}}\hat{\bm{\omega}}^{\tilde{n},0}$.}\\
			{3. Compute the SPH functional: $\bar{\bm{f}}(\bm{x}^{\tilde{n},0}, \tilde{\bm{w}}^{\tilde{n},0})$.}\\
			{4. $\hat{\bm{f}}\:$= \FMain{$\tilde{\bm{\Phi}}$,$\bar{\bm{f}}(\bm{x}^{\tilde{n},0}, \tilde{\bm{w}}^{\tilde{n},0})$} See Alg.~\ref{alg:ProjectDynamics}.}\\
			{5. Stage 1 integration: $\hat{\bm{\omega}}^{\tilde{n},1}=\hat{\bm{\omega}}^{\tilde{n},0}+\frac{\Delta t}{2}\hat{\bm{f}}(\hat{\bm{\omega}}^{\tilde{n},0})$ and ${\bm{x}}^{\tilde{n},1}={\bm{x}}^{\tilde{n},0}+\frac{\Delta t}{2}\left(\tilde{\bm{u}}+\delta\tilde{\bm{u}}\right)^{\tilde{n},1}$}.

			\tcp{RK 4 Stage 2}
			{1. Get approximate trial basis, $\tilde{\bm{\Phi}}(\bm{x}^{\tilde{n},1})$, via Eq.~\ref{eqn:PSI_approximate}.}\\
			{2. Compute the full SPH state vector: $\tilde{\bm{w}}^{\tilde{n},1}=\tilde{\bm{\Phi}}\hat{\bm{\omega}}^{\tilde{n},1}$.}\\
			{3. Compute the SPH functional: $\bar{\bm{f}}(\bm{x}^{\tilde{n},1}, \tilde{\bm{w}}^{\tilde{n},1})$.}\\
			{4. $\hat{\bm{f}}\:$= \FMain{$\tilde{\bm{\Phi}}$,$\bar{\bm{f}}(\bm{x}^{\tilde{n},1}, \tilde{\bm{w}}^{\tilde{n},1})$} See Alg.~\ref{alg:ProjectDynamics}.}\\
			{5. Stage 2 integration: $\hat{\bm{\omega}}^{\tilde{n},2}=\hat{\bm{\omega}}^{\tilde{n},0}+\frac{\Delta t}{2}\hat{\bm{f}}(\hat{\bm{\omega}}^{\tilde{n},1})$ and ${\bm{x}}^{\tilde{n},2}={\bm{x}}^{\tilde{n},0}+\frac{\Delta t}{2}\left(\tilde{\bm{u}}+\delta\tilde{\bm{u}}\right)^{\tilde{n},1}$}.

				\tcp{RK 4 Stage 3}
			{1. Get approximate trial basis, $\tilde{\bm{\Phi}}(\bm{x}^{\tilde{n},2})$, via Eq.~\ref{eqn:PSI_approximate}.}\\
			{2. Compute the full SPH state vector: $\tilde{\bm{w}}^{\tilde{n},2}=\tilde{\bm{\Phi}}\hat{\bm{\omega}}^{\tilde{n},2}$.}\\
			{3. Compute the SPH functional: $\bar{\bm{f}}(\bm{x}^{\tilde{n},2}, \tilde{\bm{w}}^{\tilde{n},2})$.}\\
			{4. $\hat{\bm{f}}\:$= \FMain{$\tilde{\bm{\Phi}}$,$\bar{\bm{f}}(\bm{x}^{\tilde{n},2}, \tilde{\bm{w}}^{\tilde{n},2})$} See Alg.~\ref{alg:ProjectDynamics}.}\\
			{5. Stage 3 integration: $\hat{\bm{\omega}}^{\tilde{n},3}=\hat{\bm{\omega}}^{\tilde{n},0}+{\Delta t}\hat{\bm{f}}(\hat{\bm{\omega}}^{\tilde{n},2})$ and ${\bm{x}}^{\tilde{n},3}={\bm{x}}^{\tilde{n},0}+{\Delta t}\left(\tilde{\bm{u}}+\delta\tilde{\bm{u}}\right)^{\tilde{n},2}$}.

				\tcp{RK 4 Stage 4}
			{1. Get approximate trial basis, $\tilde{\bm{\Phi}}(\bm{x}^{\tilde{n},3})$, via Eq.~\ref{eqn:PSI_approximate}.}\\
			{2. Compute the full SPH state vector: $\tilde{\bm{w}}^{\tilde{n},3}=\tilde{\bm{\Phi}}\hat{\bm{\omega}}^{\tilde{n},3}$.}\\
			{3. Compute the SPH functional: $\bar{\bm{f}}(\bm{x}^{\tilde{n},3}, \tilde{\bm{w}}^{\tilde{n},3})$.}\\
			{4. $\hat{\bm{f}}\:$= \FMain{$\tilde{\bm{\Phi}}$,$\bar{\bm{f}}(\bm{x}^{\tilde{n},3}, \tilde{\bm{w}}^{\tilde{n},3})$} See Alg.~\ref{alg:ProjectDynamics}.}\\
			{5. Stage 4 integration:\\ $\hat{\bm{\omega}}^{\tilde{n},4}=\hat{\bm{\omega}}^{\tilde{n},0}+\frac{\Delta t}{6}\left[\bm{f}(\hat{\bm{\omega}}^{\tilde{n},0}) + 2\bm{f}(\hat{\bm{\omega}}^{\tilde{n},1}) + 2\bm{f}(\hat{\bm{\omega}}^{\tilde{n},2}) + \bm{f}(\hat{\bm{\omega}}^{\tilde{n},3})\right]$ and \\
				 ${\bm{x}}^{\tilde{n},4}={\bm{x}}^{\tilde{n},0}+\frac{\Delta t}{6}\left[\left(\tilde{\bm{u}}+\delta\tilde{\bm{u}}\right)^{\tilde{n},0} + 2\left(\tilde{\bm{u}}+\delta\tilde{\bm{u}}\right)^{\tilde{n},1} + 2\left(\tilde{\bm{u}}+\delta\tilde{\bm{u}}\right)^{\tilde{n},2} + \left(\tilde{\bm{u}}+\delta\tilde{\bm{u}}\right)^{\tilde{n},3}\right]$ }.

	}
	\end{doublespace}
	\vspace*{-0.5cm}
\end{algorithm}

\begin{algorithm}
	\caption{Algorithm for Projecting Dynamics}\label{alg:ProjectDynamics}
	\SetAlgorithmName{Algorithm}{}{}
	\SetKwInput{Input}{Input}
	\SetKwInput{Output}{Output}
	\SetKwFunction{FMain}{ProjectDynamics}
	\SetKwFunction{FMainBasis}{TrialBasisApproximation}
	\SetKwProg{Fn}{function}{($\tilde{\bm{\Phi}}$, $\bar{\bm{f}}$):}{}
	\Input{Trial basis approximation, $\tilde{\bm{\Phi}}$ and SPH functional, $\bar{\bm{f}}$.}
	\Output{Projected low-dimensional SPH functional, $\hat{\bm{f}}$.}
	\begin{doublespace}
		\vspace*{-.1cm}

			\Fn\FMain{
					\eIf{\normalfont{\texttt{Galerkin projection}}}
					{
						{Projected low-dimensional SPH functional: $\hat{\bm{f}}=\tilde{\bm{\Phi}}^+\bar{\bm{f}}$}
					}
					(\normalfont{\texttt{Adjoint Petrov-Galerkin projection}}\cite{parish2020adjoint})
					{				
						{1. Compute projection of the SPH functional, $\tilde{\bm{\Pi}}\bar{\bm{f}}:=\tilde{\bm{\Phi}}\tilde{\bm{\Phi}}^+\bar{\bm{f}}$.}\\
						{2. Compute orthogonal projection of the SPH functional, ${\bm{\Pi}}^{\prime}\bar{\bm{f}}:=\bar{\bm{f}}-\tilde{\bm{\Pi}}\bar{\bm{f}}$.}\\
						{3. Compute the approximation, $ \bm{J}\bm{\Pi}^{\prime } \bar{\bm{f}}(\tilde{\bm{\omega}})\approx \frac{1}{\varepsilon}\left[\bar{\bm{f}}(\tilde{\bm{\omega}}+\varepsilon\bm{\Pi}^{\prime } \bar{\bm{f}}(\tilde{\bm{\omega}}))-\bar{\bm{f}}(\tilde{\bm{\omega}})\right]$.}\\
						{4. Projected low-dimensional SPH functional, $\hat{\bm{f}}:={\bm{\Phi}}^{+}\left(\bar{\bm{f}}+\tau\bm{J}{\bm{\Pi}}^{\prime}\bar{\bm{f}}\right)$.}\\
         				\vspace*{-0.5cm}
					}
					}
	\end{doublespace}
	\vspace*{-0.35cm}
\end{algorithm}

