%We conclude this section with a monotonicity result for a restricted type of drawing with $n$ \colonename and $n$ \coltwoname vertices, which generalizes a result of Soukup~\cite[Remark after Theorem~1]{Soukup24}. 
We conclude this section with a monotonicity result for a restricted type of drawing.
In the following, we associate the two partition classes of a complete bipartite graph with two color classes, which we refer to as \colonename and \coltwoname, and color the vertices accordingly.
Our result
%, which 
generalizes the following result of Soukup (rephrased in terms of drawings):
If a geometric complete bipartite graph $H$ with $n$ \colonename vertices and $n$ \coltwoname vertices has a set of \coltwoname vertices that contains  in the interior of its convex hull all \colonename vertices but no \coltwoname vertex, then $H$ contains a plane Hamiltonian cycle~\cite[Remark after Theorem~1]{Soukup24}.


\begin{restatable}{theorem}{ThmNestedColor}\label{thm:nestedColor}
	Let $H$ be a geometric complete bipartite graph with $n$ vertices of each color.
	If there exists a set of \coltwoname vertices that contains  in the interior of its convex hull all \colonename vertices but no \coltwoname vertex, then for each $t\in \{2,\ldots, n\}$, $H$ contains a plane cycle of length~$2t$.
\end{restatable}

\begin{proof}
	Let $B$ be the set of \coltwoname vertices that contains  in the interior of its convex hull all \colonename vertices but no \coltwoname vertex.
	Consider some $t\in \{2,\ldots, n\}$.
	Let $I$ denote the set of \colonename vertices.
	We can assume that $B$ contains all \coltwoname vertices.
	If this is not the case, we can repeatedly remove one \coltwoname vertex not in $B$ and one \colonename vertex in $I$ until either exactly $t$ vertices in $I$ remain or we run out of \coltwoname vertices not in $B$.
	In the former case, also exactly $t$ \coltwoname vertices remain and we apply Soukup's result to find a cycle of length~$2t$.
	In the latter case, we use the following strategy.

	Let $b_1, \ldots, b_k$ be the vertices in $B$ in counterclockwise order along the convex hull of $B$ ($k > t$).
	We call the interior of the triangle spanned by $b_{i - 1}, b_i, b_{i + 1}$ the \lightdfn{boundary triangle~$t_i$}.
	Here we use $b_{k + 1} = b_1$ and $b_0 = b_k$, and we also set $t_{k + 1} = t_1$ and $t_{0} = t_k$.
	Note that among the boundary triangles, $t_i$ has a nonempty intersection only with $t_{i - 1}$ and $t_{i + 1}$.
	We call $t_{i} \cap t_{i - 1}$ the \lightdfn{edge-zone}~$z_i$.
	Note that all edge-zones are disjoint.	
	We distinguish two cases:

	\begin{proofcases}
		\item\label{case:almost-empty-ear}
		\caseheading{There exists a boundary triangle $t_i$ containing at most one vertex $p$ from $I$.}

		Let $B' = B \setminus \{b_i\}$.
		If there is a vertex $p \in t_i$, then we set $p'=p$, otherwise we pick an arbitrary vertex from $I$ as $p'$.
		Next, we set $I' = I \setminus \{p'\}$.
		Because $t_i$ contains no vertices from $I'$, $I'$ lies in the interior of $B'$.
		The resulting set $P' = B' \cup I'$ has size $2k - 2$.
		We can therefore recurse on the geometric complete multipartite graph with vertex set $P'$ until we get to $t$ vertices on the convex hull and apply Soukup's result, or until we end in \cref{case:no-almost-empty-ears}.

		\item\label{case:no-almost-empty-ears}
		\caseheading{Every triangle $t_i$ contains two or more vertices from $I$.}

		We first argue that in this case every boundary triangle $t_i$ contains exactly two vertices from $I$.
		Let $G$ be a bipartite graph whose vertices represent the boundary triangles $T = \{t_1, \ldots, t_k\}$ as one partition class and the vertices in $I = \{p_1, \ldots, p_k\}$ as the other partition class.
		Whenever a triangle $t_i$ contains a vertex $p_j$, we add the edge $t_ip_j$ to $G$.
		On the one hand, because the triangle $t_i$ has nonempty intersection only with two other triangles, no vertex $p_j$ from $I$ can be in more than two triangles of $T$, so the degree of $p_j$ is at most two and $G$ has at most $2k$ edges.
		On the other hand, by our case assumption, every $t_i$ contains at least two vertices, so the degree of $t_i$ is at least two and $G$ has at least $2k$ edges.
		Thus $G$ has exactly $2k$ edges.
		As a consequence, every vertex $t_i$ or $p_j$ has degree exactly two, and thus every triangle $t_i$ contains exactly two vertices and every vertex $p_j$ from $I$ lies in two triangles simultaneously.
		In particular, each vertex from $I$ lies in an edge-zone.

		Given these insights about how the drawing can look locally, we now show that there are only two possible drawings.
		As a first case, assume that there is an edge-zone $z_i$ containing no vertex from $I$.
		Then the two vertices that need to lie in $t_i$ have to lie in $z_{i + 1}$.
		The two vertices in $t_{i + 1}$ are now already in $z_{i + 1}$, and thus $z_{i + 2}$ has to be empty.
		We can repeat this argument until we arrive at $t_{i - 1}$.
		If $k$ is odd, we get a contradiction, since $z_{i - 1}$ would then contain no vertex from $I$ and so would $t_{i - 1}$.
		However, if $k$ is even, we get a feasible drawing, which we call~$\mathcal{C}_1$.
		As a second case, assume that every edge-zone contains at least one vertex from $I$.
		As the edge-zones are disjoint, we have that each edge-zone contains exactly one vertex from $I$.
		This gives another valid drawing, which we call $\mathcal{C}_2$.
		Both drawings are depicted in \cref{fig:nestedColor-second-case-configurations}.

		\begin{figure}
			\centering
			\includegraphics[width=\textwidth]{separated-knn-second-case-configurations}
			\caption[The two possible drawings if every triangle contains two or more vertices]
			{The two possible drawings in the proof of \cref{thm:nestedColor}, \cref{case:no-almost-empty-ears}.}
			\label{fig:nestedColor-second-case-configurations}
		\end{figure}



		We can now finally show the existence of a plane cycle of length $2t$, by deriving it from a plane cycle $C_{2k}$ of length $2k$.
		For drawing $\mathcal{C}_1$, a possible $C_{2k}$ is given by connecting the vertices as follows.
		For every edge-zone $z_i$ that contains two vertices $p_1, p_2 \in I$, assume without loss of generality that $b_{i - 1}$ sees the vertices $b_i$, $p_1$, $p_2$ and $b_{i - 2}$ in counterclockwise order.
		We connect both $b_{i - 1}$ and $b_i$ to $p_1$ and both $b_{i - 1}$ and $b_{i - 2}$ to $p_2$ to get $C_{2k}$; see \cref{fig:aphc-in-second-configuration}.
		A plane cycle $C_{2k - 2}$ of length $2k - 2$ can be obtained from $C_{2k}$ by picking a nonempty edge-zone $z_i$ and skipping the vertex $b_{i - 1}$ and one vertex in $z_i$.
		For smaller cycle lengths, we prune $\mathcal{C}_1$ by repeatedly removing the vertices in some nonempty $z_i$ together with $b_i$ and $b_{i - 1}$ until we reach a drawing $\mathcal{C}'_1$ of the same type as $\mathcal{C}_1$, with $2t$ or $2t + 2$ vertices.
		We can then find the desired cycle with the strategy that defined $C_{2k}$ or $C_{2k - 2}$ above.

		\begin{figure}
			\centering
			\includegraphics{aphc-in-second-configuration}
			\caption[A plane cycle of length 2k in case there are empty edge-zones]
			{A plane cycle of length $2k$ (black) in the drawing $\mathcal{C}_1$.}
			\label{fig:aphc-in-second-configuration}
		\end{figure}

		For $\mathcal{C}_2$, a possible $C_{2k}$ is given by connecting each vertex $b_i$ to the vertices within the boundary triangle $t_i$.
		For smaller cycles we can again prune $\mathcal{C}_2$, this time by simply taking $2t$ consecutive vertices in $C_{2k}$.
		By doing this, we introduce only one new edge, which lies in the interior of $C_{2k}$ and thus does not cross $C_{2k}$.\qed
	\end{proofcases}
\end{proof}

