\end{figure}



We also use the following properties of plane Hamiltonian cycles which are straightforward to check.


\begin{observation}\label{lem:propertiesHC}
	Let $C$ be a plane Hamiltonian cycle in $H$.
	\begin{properties}
%		\item For each edge $w_iw_j$ in $C$ we have $j= i\pm 1$.\label[property]{enum:HCnochord} \TODO{Where is this used?}
		\item There are at most $k$ critical vertices of the first kind.\label[property]{enum:HCcriticalpoint}
		\item The cycle $C$ visits the boundary vertices in a cyclic order along $B$.\label[property]{enum:HCcyclicorder}
	\end{properties}
\end{observation}


%We now describe the desired algorithm.
The idea of the algorithm is to iterate over all spanning cycles of the interior vertices $I$ (there are $O(k!)$ many) and check if
one of them can be extended to the whole graph $H$. 
Observe that the assumption $k\geq 2$ ensures that there are at least two critical arcs.

An \lightdfn{initial cycle} $F$ of $I$ is a not-necessarily plane, geometric directed spanning cycle with vertex set $I$ (that may use oriented edges from $H$ as well as edges not in $H$), together with a nonempty subset $G_F$ of the edges of $F$, called \lightdfn{gaps}, such that the edges of $F$ not in $G_F$ (called \lightdfn{fixed edges}) are in $H$ and do not cross each other.
The gaps represent those edges in $F$ that should be replaced with longer paths using boundary vertices from~$B$. 
In particular, every gap $uv$ will be replaced by a path $u,w_i,w_{i+1},\ldots,w_{i+j},v$, where $w_i$, $w_{i+1},\ldots,w_{i+j}\in B$.
Our definition includes that in case $k=2$, $F$ is the directed cycle with just two edges between the two vertices in $I$.
%Note that by~\cref{lem:propertiesHC} each such path needs to form an interval along $B$.
For technical reasons, if two gaps are adjacent in~$F$, we insert into $F$ a fixed zero-length dummy edge at the common endpoint and color the new vertices with the color of the replaced vertex.
Note that dummy edges have both endpoints of the same color.
%We also adjust $H$ to include all bichromatic edges adjacent to the endpoints of dummy edges.
We hence can assume for the rest of the section that each endpoint of a gap is incident to only this one gap.
We call the endpoints of gaps in $G_F$ \lightdfn{gap vertices}. % and denote the gap vertices as 
%$u_1,\ldots u_g$ in the order as they appear in $F$ (for some arbitrary starting point).


To extend $F$ to $B$, for every gap vertex $u$ we select a critical arc $A(u)$, and try to place a (new) neighbor for $u$ in $A(u)$. 
The crucial observation is that we do not need to check all individual vertices from the selected critical arcs to decide whether $F$ can be extended to $B$ in this way.
Instead, we find necessary and sufficient conditions for the selection of arcs alone to be \enquote{feasible}.
This gives a running time per selection that is independent of $n$ as needed.

%Assume we have selected a critical arc $A_i$ for each gap vertex $u_i$, where each arc might be selected multiple times.
%The selection defines an ordered sequence $\mathcal{A} = A_{1},\ldots,A_{g}$ of the arcs, where $A_i= A(u_i)$.
%By \cref{enum:HCcyclicorder} (\cref{lem:propertiesHC}) $\mathcal{A}$ describes a counterclockwise ordering of the selected arcs along $B$ (where repeatedly selected arcs form an interval in the ordering).
%
%Let $A_{1},\ldots,A_{g}$ denote a counterclockwise ordering of the selected arcs along $B$ (where repeatedly selected arcs form an interval in the ordering), such that if $A_{i}=A_{i+1}$ (and $u_iu_{i+1}$ is not a dummy edge pair), then $A_{i}$ lies to the right of the line through $u_i$ in direction $u_{i+1}$, where $u_i$ and $u_{i+1}$ are the gap vertices with $A_i=A(u_i)$ and $A_{i+1}=A(u_{i+1})$.
Assume we have selected a critical arc $A(u)$ for each gap vertex $u$, where each arc might be selected multiple times.
We call the selection of critical arcs \lightdfn{feasible} if a labeling $u_1,\ldots,u_g$ of the gap vertices along $F$ exists, such that the following conditions hold (where $A_i=A(u_i)$):
\begin{conditions}
	\item 
	The selected arcs $A_1,\ldots,A_g$ appear counterclockwise along $B$ in this order.
	Each repeatedly selected arc forms an interval in this ordering.
	If $A_{i}=A_{i+1}$ for some $i$ (and $u_iu_{i+1}$ is not a dummy edge pair), then $A_{i}$ lies to the right of the line through $u_i$ in direction $u_{i+1}$.
\label[condition]{enum:feasibleOrder}

	\item For each $i$, the line segments between $u_i$ and $A_{i}$ do not cross fixed edges from $F$.\label[condition]{enum:feasibleCrossF}

	\item If $A_{i} \neq A_{j}$, then the line segments between $u_i$ and $A_i$ do not cross line segments between $u_j$ and $A_{j}$.\label[condition]{enum:feasibleCrossArcs}

	\item If $u_iu_{i+1}$ is a gap, then there is no critical vertex of the first kind between $A_i$ and $A_{i+1}$, that is, the union of all critical arcs from $A_i$, counterclockwise along $B$ up to $A_{i+1}$ (including the first and the latter) is alternately colored.\label[condition]{enum:feasibleAlternatingPaths}

	\item If $u_iu_{i+1}$ is not a gap and both vertices are of the same color, then \mbox{$A_i\neq A_{i+1}$}.\label[condition]{enum:feasibleMonoGap}

	\item If $u_iu_{i+1}$ is not a gap and $A_i\neq A_{i+1}$, then $A_i$ and $A_{i+1}$ are adjacent along~$B$, the (counterclockwise) last vertex in $A_i$ is of opposite color to~$u_i$, and the first vertex in $A_{i+1}$ is of opposite color to $u_{i+1}$.\label[condition]{enum:feasibleNongap}

	\item For each selected critical arc $A$ we have $\lvert A\rvert \geq g(A) - \mathrm{mc}(A) + \varepsilon(A),$
	where $g(A)$ is the number of gap vertices $u$ with $A(u)=A$, $\mathrm{mc}(A)$ is the number of gaps $uv$ with $uv\not\in H$ and $A(u)=A(v)=A$, and $\varepsilon(A)=1$ if the (counterclockwise) first vertex in $A$ is of the same color as the (counterclockwise) first gap vertex with $A(u)=u$ and $\varepsilon(A)=0$ otherwise.\label[condition]{enum:feasibleSize}
\end{conditions}

The following \lcnamecref{lem:FPTfeasible} shows that these conditions are sufficient and necessary.
We say that $F$ and the selected arcs are \lightdfn{Hamiltonian} if there is a plane Hamiltonian cycle $C$ in $H$ such that a counterclockwise traversal of $C$ visits the vertices in $I$ in the order given by $F$ and for each gap vertex $u$ there is an edge $uw$ in $C$ with $w\in A(u)$.

\begin{restatable}{lemma}{feasibleSelection}\label{lem:FPTfeasible}
	An initial cycle and a selection of critical arcs are Hamiltonian if and only if the selection is feasible.
\end{restatable}
\begin{proof}
	Let $F$ denote an initial cycle and let $A:u\mapsto A(u)$ denote a selection of critical arcs.

	First assume that $F$ and the selected critical arcs are Hamiltonian and let $C$ denote a corresponding plane Hamiltonian cycle in $H$.
	We prove that the selection is feasible by individually checking the feasibility conditions.
	Consider a counterclockwise traversal of $C$ such that the second vertex in this traversal is some arbitrary critical vertex.
	Let $u_1,\ldots,u_g$ denote the gap vertices of $F$ as they appear in this traversal of $C$ (which visits all vertices from $F$ as it is Hamiltonian), where we introduced dummy edges for adjacent gaps as described above.	
	Let $A_i=A(u_i)$ and observe that $C$ contains an edge between $u_i$ and $A_i$ by definition.
	\begin{conditions}%[label=(C\arabic*), wide=0pt, leftmargin=\parindent]
		\item By \cref{enum:HCcyclicorder}, the sequence $A_1,\ldots,A_g$ of selected critical arcs appears counterclockwise along $B$, where each repeatedly selected arc forms an interval.
		Indeed, the latter is clearly true for all arcs (for any counterclockwise traversal of $C$) except the ones selected for $u_1$ and $u_g$, which might be identical.
		Because the second vertex in the traversal of $C$ which defines the order $u_1,\ldots,u_g$ is some critical vertex, we have $A_1=A_g$ only if all selected arcs are equal and hence they form an interval as well.
		Finally, if $A_i=A_{i+1}$ and $u_iu_{i+1}$ is not a dummy edge, then $C$ contains edges $u_iw$ and $u_{i+1}w'$ with $w$, $w'\in A_i$ which do not cross, and hence, by \cref{enum:criticalSameCrossing}, $A_i$ lies to the right of the straight line through $u_i$ in direction of $u_{i+1}$.
		%		
		\item As $C$ is plane, Hamiltonian, and contains all fixed edges from $F$, there is an edge $u_iw$ in $C$, with $w\in A_i$, not crossing any fixed edge from $F$.
		Consider an arbitrary fixed edge $e$ and the straight line through $u_i$ and an endpoint of $e$ such that $w$ and $e$ lie on opposite sides of the line.
		By \cref{enum:criticalOrderType}, each vertex from $A_i$ lies on the same side of this line as $w$ lies (hence, on the side opposite to $e$).
		Hence, all the line segments between $u_i$ and $A_i$ do not cross $e$.

		\item As $C$ is plane, its edge between $u_i$ and $A_i$ and its edge between $u_j$ and $A_{j}$ do not cross each other.
		By \cref{enum:criticalDistinctCrossing}, all the line segments between $u_i$ and $A_i$ do not cross the line segments between $u_j$ and $A_j$.

		\item If $u_iu_{i+1}$ is a gap, then, by \cref{enum:HCcyclicorder}, $C$ contains a path from some vertex $w\in A_i$ to some vertex $w'\in A_{i+1}$ which visits all boundary vertices between $w$ and $w'$ along $B$.
		In particular, there is no critical vertex of the first kind between $A_i$ and $A_{i+1}$.

		\item If $u_iu_{i+1}$ is not a gap, then $C$ contains edges $u_iw_j$ and $u_{i+1}w_{j+1}$, with $w_{j}\in A_i$ and $w_{j+1}\in A_{i+1}$ by \cref{enum:HCcyclicorder} ($w_j$ and $w_{j+1}$ are adjacent in $B$).
		If $u_i$ and $u_{i+1}$ are of the same color, then $w_j$ and $w_{j+1}$ are of the same color.
		Hence, $w_{j+1}$ is a critical vertex of the first kind.
		Thus, $w_j$ and $w_{j+1}$ are in distinct critical arcs, that is, $A_i\neq A_{i+1}$.

		\item If $u_iu_{i+1}$ is not a gap, then $C$ contains edges $u_iw_j$ and $u_{i+1}w_{j+1}$, with $w_{j}\in A_i$ and $w_{j+1}\in A_{i+1}$ by \cref{enum:HCcyclicorder} ($w_j$ and $w_{j+1}$ are adjacent in $B$).
		So, if $A_i\neq A_{i+1}$, then these critical arcs are adjacent along $B$.
		Moreover, $w_i$ is the last vertex in $A_i$ (and hence this vertex is of opposite color to $u_i$ as $C$ is in $H$) and $w_{i+1}$ is the first vertex in $A_{i+1}$ (and hence this vertex is of opposite color to $u_{i+1}$).

		\item For each gap vertex $u$ there is an edge between $u$ and $A(u)$ in $C$.
		As $C$ is a cycle, each vertex in $B$ has in $C$ at most two neighbors from $I$.
		If a vertex in $B$ has two distinct neighbors $u$, $v\in I$ in $C$, then $u$ and $v$ are of the same color and $A(u)=A(v)$.
		Since \cref{enum:feasibleMonoGap} holds, $uv\in G_F$.
		This already shows that for every arc $A$ we have $\lvert A\rvert \geq g(A)-\mathrm{mc}(A)$.
		If the  first vertex $w$ in $A$  (in counterclockwise direction) is of the same color as the first gap vertex (in the order $u_1,\ldots, u_g$) with $A(u)=A$, then $w$ has, in $C$, no neighbor from $I$ and hence $\lvert A\rvert \geq g(A)-\mathrm{mc}(A)+1$ in this case.
	\end{conditions}

	Now assume that the selection is feasible.
	We shall prove that $F$ and the selection are Hamiltonian.
	To this end we give a construction of a suitable plane Hamiltonian cycle of $H$.
	For this we process the selected arcs in counterclockwise order.
	%	 along the order $u_1,\ldots,u_g$ given by \cref{enum:feasibleOrder}.
	For each selected arc $A$, the gap vertices with selected arc $A$ form an interval $u_j,\ldots,u_{j+t}$ in the order of gap vertices given by \cref{enum:feasibleOrder}.
	For each $u_i$, with $j\leq i \leq j+t$, we determine a neighbor $w_{x_i}$ in $A$.
	We choose the vertices $w_{x_j},\ldots,w_{x_{j+t}}$ in ascending order with the following strategy:
	First assume that $t=0$, so $A$ is selected for $u_j$ only.
	If $u_{j-1}u_{j}$ is not a gap, let $w_{x_j}$ be the (counterclockwise) first vertex in $A$.
	If $u_{j-1}u_{j}$ is a gap, then let $w_{x_j}$ be the (counterclockwise) last vertex in $A$.
	In both cases, $w_{x_j}$ is of opposite color to $u_j$ by \cref{enum:feasibleNongap}.

	Now assume that $t>0$.
	If $u_{j-1}u_{j}$ is not a gap (see \cref{fig:assign}(ii)), let $w_{x_j}$ be the (counterclockwise) first vertex in $A$ as above.
	Again, $w_{x_j}$ is of opposite color to $u_j$ by \cref{enum:feasibleNongap}.
	If $u_{j-1}u_{j}$ is a gap (see \cref{fig:assign}(iii--iv)) we choose $w_{x_j}$ as the first or second vertex in $A$ such that $w_{x_j}$ is of opposite color to $u_j$.
	Such a vertex exists by \cref{enum:feasibleSize,enum:criticalArcAlternately}.
	Consider $i$ with $j< i<j+t$ and assume that $x_j,\ldots,x_{i-1}$ are already chosen.
	If $u_{i-1}u_{i}$ is not a gap (see \cref{fig:assign}(v)), then choose $x_{i}=x_{i-1}+1$.
	Note that the colors of $u_{i-1}$ and $u_i$ differ due to \cref{enum:feasibleMonoGap} and the colors of $u_{i-1}$ and $w_{x_{i-1}}$ differ by construction.
	Hence, the colors of $w_{x_{i}}$ and $u_i$ differ as well.
	Otherwise (see \cref{fig:assign}(vii--viii)) choose $x_{i}\in \{x_{i-1},x_{i-1}+1\}$ such that $w_{x_{i}}$ is of opposite color to $u_{i}$.
	Again, this choice is possible by \cref{enum:feasibleSize,enum:criticalArcAlternately}.
	Finally consider $i=j+t$ and assume that $x_j,\ldots,x_{j+t-1}$ are already chosen.
	If $u_{j+t-1}u_{j+t}$ is not a gap, choose $x_{j+t}=x_{j+t-1}+1$.
	Again, this choice is possible by \cref{enum:feasibleSize,enum:criticalArcAlternately}.
	If $u_{j+t-1}u_{j+t}$ is a gap, choose $w_{x_{j+t}}$ as the (counterclockwise) last vertex in $A$.
	Then $w_{x_{j+t}}$ is of opposite color to $u_{j+t}$ by \cref{enum:feasibleNongap}, as $u_{j+t}u_{j+t+1}$ is a gap and $A(u_{j+t})\neq A(u_{j+t+1})$.

	\begin{figure}
		\centering
		\includegraphics{arcsassignment}
