\subsection{The Algorithm}

The following two lemmas describe how to compute the critical arcs and how to check whether a selection of critical arcs is feasible.

\begin{lemma}\label{lem:FPTcomputeCritical}
	The set of critical arcs can be computed in $O(nk^2 + n\log n)$ time.	
\end{lemma}
\begin{proof}
	First compute the convex hull of $V(H)$ and label the boundary vertices as $w_1,\ldots,w_m$ in $O(n\log n)$ time~\cite{BCKO08} in order of their appearance.
	For each $w_i$, check whether $w_{i}$ and $w_{i-1}$ are of the same color and whether some line through two vertices from $I$ separates $w_i$ from $w_{i-1}$.	
	This can be done in $O(nk^2)$ time.
	\qed
\end{proof}



\begin{lemma}\label{lem:FPTalgorithm}
	There is an algorithm checking whether a selection of critical arcs for an initial cycle is feasible in time $O(k^2)$, provided that $B$ contains at most $k$ critical vertices of the first kind.
\end{lemma}
\begin{proof}
	We are given an initial cycle $F$ of $I$ and a selection of critical arcs $A$.
	The algorithm checks whether the selection of critical arcs is feasible in the following steps.
	\begin{conditions}
		\item For each gap vertex $u$ consider the sequence $u=u_1,\ldots,u_g$ of gap vertices starting at $u$ and following the direction of $F$.
		Then check whether the corresponding sequence of selected arcs $A_1,\ldots,A_g$ appears counterclockwise along $B$ and whether, in case $A_i=A_{i+1}$, the arc $A_i$ lies to the right of the line through $u_i$ in direction $u_{i+1}$.
		By assumption on the number of critical vertices of the first kind, there are at most $k+k^2$ many critical arcs.
		Hence, this check needs $O(k^2)$ time (as $g\leq 2k$, where the factor $2$ accounts for the dummy edges).

		\item Consider each $i$ with $1\leq i \leq g$ and each fixed edge $e$ in $F$.
		By \cref{enum:criticalOrderType}, either all line segments between $u_i$ and $A_i$ cross $e$, or none do.
		So it suffices to check whether the line segment between $u_i$ and the (counterclockwise) first vertex in $A_i$ crosses $e$.
		This needs time $O(k^2)$ in total.

		\item Consider each pair $i$, $j$, with $1\leq i < j \leq g$.
		By \cref{enum:criticalDistinctCrossing}, either all line segments between $u_i$ and $A_i$ cross all line segments between $u_j$ and $A_{j}$, or none do.
		So if $A_i\neq A_{j}$, it suffices to check whether the line segment between $u_i$ and the (counterclockwise) first vertex in $A_i$ crosses the line segment between $u_j$ and the first vertex in $A_{j}$.
		This needs time $O(k^2)$ in total.

		\item Consider each $i$ with $1\leq i \leq g$.
		If $u_iu_{i+1}\in G_F$, then check whether there is a critical vertex of the first kind between $A_i$ and $A_{i+1}$.
		This can be done in $O(k^2)$ time in total by checking the critical vertices along $B$.

		\item Consider each $i$ with $1\leq i \leq g$.
		If $u_iu_{i+1}\not\in G_F$ and both vertices are of the same color, then check $A_i\neq A_{i+1}$.
		This needs $O(k)$ time in total.

		\item Consider each $i$ with $1\leq i \leq g$.
		If $u_iu_{i+1}\not\in G_F$ and $A_i\neq A_{i+1}$, check whether $A_i$ and $A_{i+1}$ are adjacent along $B$, the (counterclockwise) last vertex in $A_i$ is of opposite color to $u_i$, and the first vertex in $A_{i+1}$ is of opposite color to $u_{i+1}$.
		This needs $O(k)$ time in total.

		\item Determine for each selected arc $A$ the numbers $g(A)$, $\mathrm{mc}(A)$, and $\varepsilon(A)$ by iterating the sequence $u_1,\ldots,u_g$ once.
		Then check whether $\lvert A\rvert \geq g(A)-\mathrm{mc}(A)+\varepsilon(A)$ holds for each~$A$.
		This needs $O(k)$ time.
		\qed
	\end{conditions}
\end{proof}


The final algorithm for the case $k\geq 2$ works as follows.
We compute the critical arcs in $O(n\log n + n k^2)$ time as described in \cref{lem:FPTcomputeCritical}.
%
%via \cref{lem:FPTcomputeCritical} from \cref{app:FPT} and 
We check whether there are more than $k$ critical vertices of the first kind (cf.~\cref{enum:HCcriticalpoint} from Observation~\ref{lem:propertiesHC}).
If not, we generate all $O(k!)$ directed spanning cycles of~$I$.  
We then iterate, for each cycle, over all possible sets of gaps ($O(2^k)$ many) and check if this forms an initial cycle (fixed edges are noncrossing and in~$H$) in $O(k^2)$ time for each.
For each initial cycle, we separate adjacent gaps by dummy edges in $O(k)$ time, iterate over all $O(k^{4k})$ selections of critical arcs, and check feasibility for each selection in $O(k^2)$ time as described in \cref{lem:FPTalgorithm}.
%via \cref{lem:FPTalgorithm} from \cref{app:FPT}.
Altogether, this needs $O(n\log n + n k^2) + O(k^{5k})$ time, as desired.
%Correctness follows from \cref{enum:HCcriticalpoint} together with the fact that a geometric complete bipartite graph contains a plane Hamiltonian cycle if and only if there is an initial cycle of $I$ with a feasible selection of critical arcs (cf. \cref{lem:FPTgeneralHC}), which is stated and proven in \cref{app:ssec:FPTgeneralHC}).
%Correctness is provided by \cref{enum:HCcriticalpoint} and \cref{lem:FPTgeneralHC}. 
%Correctness is provided by \cref{enum:HCcriticalpoint} and \cref{lem:FPTgeneralHC} from \cref{app:FPT}. 
%We conclude with the following
%\lcnamecref{thm:FPT}.
In summary, the following \lcnamecref{thm:FPT} holds.
%A correctness proof is given in \cref{app:ssec:FPTthm}.

\begin{restatable}{theorem}{ThmFPT}\label{thm:FPT}
	There is an algorithm to check whether a geometric complete bipartite graph with $k$ interior vertices contains a plane Hamiltonian cycle in $O(n \log n + nk^2) + O(k^{5k})$ time.
\end{restatable}
\begin{proof}
	The upper bound on the running time is derived above.
	It remains to show correctness of the algorithm.

	First assume that $H$ contains a plane Hamiltonian cycle $C$.
	Let $F$ denote the directed cycle on $I$ obtained by skipping all vertices from $B$ during a counterclockwise traversal of $C$ and let $G_F$ denote the set of edges in $F$ corresponding to skipped paths from~$C$.
	Then $F$ is an initial cycle of $I$ where $G_F$ is the set of gaps.
	As above, replace each gap vertex that is incident to two gaps with a zero-length dummy edge.
	For each gap vertex $u$ in $F$ let $A(u)$ denote the critical arc in $B$ which contains a neighbor of $u$ in~$C$.
	Then $F$ and the selection of critical arcs given by $A$ are Hamiltonian and hence $A$ is feasible by \cref{lem:FPTfeasible}.
	This means, that the algorithm described in \cref{sec:FPT} correctly shows that $H$ has a plane Hamiltonian by identifying the initial cycle $F$ and the feasible selection $A$.

	If, the other way round, the algorithm finds an initial cycle of $I$ with a feasible selection of critical arcs, then these are Hamiltonian by \cref{lem:FPTfeasible} and, hence, $H$ contains a plane Hamiltonian cycle.
	\qed
\end{proof}


\section{Completing disjoint bicolored line segments to a plane Hamiltonian cycle is \np-complete}\label{sec:NP}

In 1989, Rappaport~\cite{DBLP:journals/siamcomp/Rappaport89} proved that completing a set of nonintersecting simple polylines to a plane simple Hamiltonian cycle is \np-complete, by reduction from the Hamiltonian path problem on planar cubic graphs~\cite{DBLP:journals/siamcomp/GareyJT76}.
In 2019, Akitaya et al.~\cite{DBLP:conf/compgeom/AkitayaKRST19} and independently in 2021, Jiang, Jiang, and Jiang~\cite{DBLP:journals/corr/abs-2108-12812} showed that this holds for disjoint line segments as well.
We show that both results generalize for a bicolored version of the problem.

\begin{restatable}{theorem}{ThmNPCSegments}\label{thm:npc-segments}
	It is \np-complete to decide if a set of edges of a geometric complete bipartite graph $H$ can be completed to a plane Hamiltonian cycle in $H$.
\end{restatable}

\begin{proof}
We show that the gadgets of Rappaport and Jiang, Jiang, and Jiang still work if they are embedded in a geometric complete bipartite graph.
In particular, we show how to color the vertices in the gadgets such that yes-instances of the uncolored version will become yes-instances of the bipartite graph version (no-instances will remain no-instances in any case).
For our arguments we briefly review the main ideas of the aforementioned reductions.

\begin{figure}
	\centering
	\includegraphics[page=3]{rappaport-modules-v2.pdf}
	\hspace{2ex}
	\includegraphics[page=4]{rappaport-modules-v2.pdf}
	\caption[Rappaport's modules]
	{
		Rappaport's modules.
%		
		\subcaptionheading{Left:} A schematic drawing of the module.
		\subcaptionheading{Right:} The three possible completions for a door and the supporting coloring.
	}
	\label{fig:rappaport-modules}
\end{figure}

%In a rectilinear drawing of a graph, vertices are drawn as horizontal line segments, and edges as vertical line segments.
%Though \np-complete for general planar graphs~\cite{DBLP:journals/siamcomp/GargT01}, for triconnected planar graphs such as planar cubic graphs, such a drawing always exists, even on integer coordinates, is planar, and is computable in linear time~\cite{DBLP:journals/dcg/RosenstiehlT86}.
We begin with Rappaport's~\cite{DBLP:journals/siamcomp/Rappaport89} reduction from the Hamiltonian path problem on planar cubic graphs. 
The input graph is drawn such that vertices and edges are represented by noncrossing horizontal and vertical line segments, respectively, such that each vertical line segment connects two horizontal line segments corresponding to adjacent vertices.
Such a drawing exists for every planar cubic graph~\cite{DBLP:journals/dcg/RosenstiehlT86}.
Next, the horizontal segments are replaced by so-called \lightdfn{modules}.
Each module is based on a pair of nested polygons consisting solely of axis-parallel segments, see \cref{fig:rappaport-modules} (left).
Small gaps are cut into both polygons at the three \enquote{attachment points}, where the original horizontal segment connects to vertical segments (recall that the input graph is cubic).
This splits all polygons into polylines.
Each pair of gaps belonging to the same attachment point defines a \lightdfn{door}; see \cref{fig:rappaport-modules} (right).
Finally, all vertical segments are removed.



Rappaport~\cite{DBLP:journals/siamcomp/Rappaport89} proved that the final set of segments can be completed to a plane Hamiltonian cycle if and only if the input graph has a Hamiltonian path.
Also, for any such completion the endpoints at every door can be connected in only three different ways (closed, open, T-shaped); see \cref{fig:rappaport-modules} (right).

In our setting each endpoint of a polyline becomes a vertex of the bipartite host graph $H$ (we will add more vertices to the host later).
We now introduce a coloring for the polyline endpoints, processing each module and each polyline in the module independently.
For polylines of the outer polygon, color the counterclockwise first vertex of the polyline \colonename and the last vertex \coltwoname.
For polylines of the inner polygon, color the counterclockwise first vertex \coltwoname and the last vertex \colonename; see \cref{fig:rappaport-modules} (right).
% leftmost polyline endpoint (if any) on the top line \colonename and the leftmost polyline endpoint (if any) on the bottom line \coltwoname.
%For the polylines coming from the inner polygon, color the leftmost polyline endpoint (if any) on the top line \coltwoname and the leftmost polyline endpoint (if any) on the bottom line \colonename.
%Finally, color all other polyline endpoints of the inner (resp.\ outer) polygon in an alternating fashion \colonename or \coltwoname as indicated in~\cref{fig:rappaport-modules} (right).
We claim that any segment (connecting two polyline endpoints) that might be used by a completion to a plane Hamiltonian cycle is an edge in $H$.
By construction, it is clear that closed and open doors use only edges from $H$.
For each pair of doors from distinct modules one door comes from the upper part of its module and the other from the lower part of its module.
In this case, the colorings of the two doors are inverted to each other, as if they were rotated by $180^\circ$.
So, doors connected via a T-shaped completion use edges from $H$ (joining two modules) as well.
So  we showed that the endpoints of the polylines in resulting yes-instances of Rappaport's reduction can be colored such that any completion to the desired cycle adds only edges from $H$.

\begin{figure}
	\centering
	\includegraphics[page=2]{jiang-construction-v2}
	\caption[Jiang, Jiang and Jiang's gadget]
	{
		Jiang, Jiang and Jiang's gadget with a suitable coloring.
		In each such coloring, the gadget always passes the color of $p$ on to $p'$.
	}
	\label{fig:jiang-construction}
\end{figure}


Jiang, Jiang, and Jiang~\cite{DBLP:journals/corr/abs-2108-12812} give a reduction from Rappaport's polyline version of the problem to a version that consists only of disjoint line segments.
The reduction replaces each bend of every polyline with a (suitably rotated) gadget consisting of five disjoint line segments; see \cref{fig:jiang-construction}.
Then the authors show that each completion to a noncrossing Hamiltonian cycle adds only segments within the gadgets, or segments already used in the original polyline version.
Again, we reuse the gadget of their reduction.
We add the endpoints of these segments as further vertices to our host graph $H$.
The segments in the gadgets will form the set of edges from our host $H$ that should be completed to a plane Hamiltonian cycle in $H$.
We show that we can color the endpoints of the segments such that yes-instances lead to yes-instances in the bipartite graph version.
%The new line segments have restricted mutual visibility, which imposes a fixed traversal order within any partial non-crossing simple cycle.
%(This is sufficient because all line segments in Rappaport's modules are axis-parallel and thus all corners are right-angle corners.)
We start with a coloring of the polyline endpoints as described above.
The replacements are carried out one by one for every polyline, and the bends in every polyline are processed from one end to the other.
Thus, for each bend that is currently processed, we have one incident segment whose other endpoint $p$ is already colored.
To color the vertices from the gadget, we traverse the segments of the gadget as in \cref{fig:jiang-construction} and color the vertices alternating.
Note that the vertex last colored in the gadget (called $p'$ in \cref{fig:jiang-construction}) receives the same color as $p$.
Hence, the last edge of the polyline(-replacement) is colored correctly, i.e. is from $H$.
This shows that the derived edge set in $H$ can be completed to a plane Hamiltonian cycle in $H$ if and only if the polyline version can be completed to a plane Hamiltonian cycle.
This finishes the proof.
\qed
\end{proof}

\section{Conclusion and open problems}
We have shown that geometric complete multipartite graphs which contain a plane cycle $C$ also admit a shorter plane cycle of at least half the size of $C$.
For some restricted geometric complete bipartite graphs, we have shown that they contain plane cycles of each possible even length.
This prompts the following question (distinguishing between two or more colors).

\begin{problem}
	Let $H$ be a geometric complete multipartite graph that contains a plane cycle of length~$t$. Does $H$ contain a plane cycle of length $t'$ for any (even) $t'$ with $3\leq t'\leq t$?
\end{problem}

%We remark that while \cref{fig:no-c4-chord} shows that it might not be possible to obtain the wanted cycle of length $2(t-1)$ via a chord in~$C$, the point set does admit such a cycle.

We have also given an FPT algorithm to decide whether a geometric complete bipartite graph has a plane Hamiltonian cycle. 
It is open whether this problem is NP-hard, which is related to an open question stated by Claverol et al.~\cite{COGST18}.
%Due to our proof that it is NP-complete to decide whether some fixed segments in $P$ can be extended to a plane Hamiltonian cycle and the general NP-completeness of most Hamiltonian cycle questions, we conjecture the following.

\begin{problem}\label{conj:ConjectureNP}
	Is it \np-complete to decide if a given geometric complete multipartite graph contains a plane Hamiltonian cycle?
\end{problem}

