\subsection{ML Classifier}
Neural networks capture intricate relationships between features, solve complex problems, and mimic human-like intelligence. They have a wide range of applications, including image recognition, fraud detection, medical diagnosis, and sentiment classification. Therefore, we use Deep Neural Network (DNN) to train and test the generated advanced features in the proposed work. We use `\textit{StandardScaler}' to normalize the features,`\textit{Adam}' as an optimizer, and `\textit{binary cross entropy}' as the loss function. We use the DNN model with thirteen layers (DNN13), where all the hidden layers are fully connected. We do batch normalization and node dropout before passing them to the next layer to speed up the training time and avoid overfitting \cite{overfast}, respectively. The number of output neurons in each layer of DNN13, starting from layer-1 to layer-13, is 5608, 5096, 4584, 4072, 3560, 3048, 2536, 2024, 1012, 512, 256, 128, and 1, respectively. We utilize ``\textit{Sigmoid}" as the activation function in the final layer as the chosen problem is a binary classification problem, whereas ``\textit{ReLU}" in the previous levels. The complete framework of the DNN is shown in Algorithm \ref{algorithm1}, and the descriptions of the notations used in Algorithm \ref{algorithm1} are mentioned in Table \ref{notationsss}.
\begin{algorithm}[]
\scriptsize
\caption{Neural Network Training Algorithm}\label{algorithm1}
% \algorithmfootnote{\scriptsize{\textit{l}: Number of layers, $n_i$: Neurons in the $i^{th}$ layer, $Z_j^i$: Weighted sum for $j^{th}$ neuron in $i^{th}$ layer, $W_{j,k}^{i}$: Weight of edge $k$ of neuron $j$ at layer $i$, $X_k$: Element $k$ of input $X$, \textit{s}: Length of input $X$, $b_j^i$: Bias of $j^{th}$ neuron at layer $i$, $a_j^i$: Activation output of neuron $j$ at layer $i$, $\underset{loss}{L}$: Binary cross-entropy loss, $y_j$: Actual output of neuron $j$, $\delta_j^i$: Gradient at $j^{th}$ neuron in layer $i$, $\triangle W_{j,:}^{i}$: Weight update for $j^{th}$ neuron at $i^{th}$ layer for each element in a batch, $Wsum_j^i$: Sum of weight updates for $j^{th}$ neuron for a batch - at the beginning of each batch it is set to zero, $\triangle b_j^i$: Bias update for $j^{th}$ neuron at $i^{th}$ layer for each element in a batch, $bsum_j^i$: Sum of bias updates for $j^{th}$ neuron for a batch - at the beginning of each batch it is set to zero, $\eta$: Learning rate, \textit{m}: Batch size}}
\KwData{Random Waits \textit{W}, Random Biases \textit{b}, Input \textit{X}}
\KwResult{Trained Model}
\For{each training epoch}
{
    \For{each batch}
    {
        \For{each element in the batch}
        {
            \For{layer \textit{i} from \textit{1} to \textit{l}}
            {
                \For{neuron \textit{j} in layer \textit{i} ($j = 1$ to $n_i$)}
                {   
                    \If{i==1}
                    {
                        $Z_j^i = \sum_{k=1}^{s} W_{j,k}^i.X_k+b_j^i$\;
                        $a_j^{i} = ReLU(Z_j^i)$\;
                    }
                    \ElseIf{i==l}
                    {
                        $Z_j^i = \sum_{k=1}^{n_{i-1}} W_{j,k}^i.a_k^{i-1}+b_j^i$\;
                        $a_j^{i} = Sigmoid(Z_j^i)$\;
                    }
                    \Else
                    {
                        $Z_j^i = \sum_{k=1}^{n_{i-1}} W_{j,k}^i.a_k^{i-1}+b_j^i$\;
                        $a_j^{i} = ReLU(Z_j^i)$\;
                    }

                }
            } 

            $\underset{loss}{L} = -\frac{1}{n_l}\sum_{j=1}^{n_l}(y_j.\log(a_j^l)+(1-y_j).\log(1-a_j^l))$\;

            \For{layer \textit{i} from \textit{l} to \textit{1}}
            {
                \For{neuron \textit{j} in layer \textit{i} ($j = 1$ to $n_i$)}
                {
                    \If{i==l}
                    {
                        $\delta_j^i = (a_j^i-y_j).Sigmoid'(Z_j^i)$\;
                    }
                    \Else
                    {
                        \If{$Z_j^i>0$}
                        {
                            $\delta_j^i = (W_{j,:}^{i+1})^T.\delta^{i+1}.1$\;
                        }
                        \Else
                        {
                            $\delta_j^i = 0$\;
                        }

                    }
                    $\triangle W_{j,:}^{i} = \delta_j^i.(a^{i-1})^T$\;
                    $Wsum_j^i = Wsum_j^i + \triangle W_{j,:}^{i}$\;
                    $\triangle b_{j}^{i} = \delta_j^i$\;
                    $bsum_j^i = bsum_j^i + \triangle b_{j}^{i}$\;
                }
            }
        }

        \For{layer \textit{i} from \textit{l} to \textit{1}}
            {
                \For{neuron \textit{j} in layer \textit{i} ($j = 1$ to $n_i$)}
                {
                    $W_{j,:}^{i} = W_{j,:}^{i} - \eta.\frac{Wsum_j^i}{m}$\;
                     $b_j^i = b_j^i - \eta.\frac{bsum_j^i}{m}$\;
                    \
                }
            }
    }
}
\end{algorithm}
