\subsection{Graph Search Algorithm}
Any graph search algorithm can be applied to a bur-tree. This work adapts the ARA$^\ast$ algorithm described previously. The algorithm we propose is presented in algorithms \ref{alg:proposed} and \ref{alg:improve}.

\begin{algorithm}
{\scriptsize
    \caption{ARA$^{\ast}$ search with burs}
    \begin{algorithmic}[1]
        \renewcommand{\algorithmicrequire}{\textbf{Input:}}
        \renewcommand{\algorithmicensure}{\textbf{Output:}}
        \REQUIRE{\phantom{j}\\
        $s_{start}$: start node,\\
        $s_{goal}$: goal node,\\
        $\varepsilon > 1$}: suboptimality bound,\\
        $t_{allowed}$: allowed planning time \\    
        \ENSURE{\phantom{j}\\$(sub)optimal\_path$ from $s_{start}$ to $s_{goal}$\\\phantom{j}} \\

\STATE $g(s_{goal}) \leftarrow \infty$, $g(s_{start}) \leftarrow 0$ \\
\STATE $open\_set \leftarrow \{start\}$ \\
\STATE $closed\_set \leftarrow \emptyset$, $incons\_set \leftarrow \emptyset$ \\
\STATE $f(s_{start}) \leftarrow g(s_{start}) + \varepsilon \cdot h(s_{start})$ \\
\STATE \textbf{call} \texttt{ImprovePathUsingBurs()} \\
\STATE $\varepsilon' \leftarrow \min\left\{\varepsilon, \frac{g(s_{goal})}{\min_{s \in open\_set \cup incons\_set}(g(s)+h(s))}\right\}$ \\
\WHILE{\texttt{getElapsedTime()} $< t_{allowed}$} { \label{elaps}
\STATE save the latest $\varepsilon'$-suboptimal solution \\

\WHILE{$\varepsilon' > 1$}{
    \STATE $\varepsilon \leftarrow \varepsilon - \Delta\varepsilon$ \\
    \STATE move nodes from $incons\_set$ to $open\_set$ \\
    \STATE sort $open\_set$ based on $f(s)$ \\
    \STATE $closed\_set \leftarrow \emptyset$ \\
    \STATE \textbf{call} \texttt{improvePathUsingBurs()} \\
    \STATE $\varepsilon' \leftarrow \min\left\{\varepsilon, \frac{g(s_{goal})}{\min_{s \in open\_set \cup incons\_set}(g(s)+h(s))}\right\}$ \\
    \STATE save the latest $\varepsilon'$-suboptimal solution \\
}\ENDWHILE
\RETURN $(sub)optimal\_path$
}\ENDWHILE
\RETURN $(sub)optimal\_path$
    \end{algorithmic} 
    \label{alg:proposed}
}
\end{algorithm}

