\section{Directed Graph Application}

In the main text, we mentioned that our algorithm can be easily adapted to directed graphs. This is because, by simply removing the symmetry condition in the definition of the Noisy Adjacency Matrix, it can be seamlessly applied to directed graphs while still preserving all its properties.

Here, we provide the definition of the noisy adjacency matrix for directed graphs:

\begin{definition}[Noisy adjacency matrix] 
    \(\hat{A}\) is the noisy adjacency matrix of directed graph \(G\in \mathcal{G}\), if \(\hat{A}\) satisfies:
    \begin{center}
    \(\mathbb{E} \left[ \hat{A} \right] = A; \text{ }\hat{a}_{ii}=0, \text{ for any } i \in [n]\);

    \(\hat{a}_{ij}\bot \hat{a}_{kl}, \text{ for any } i<j, \text{ } k<l,\text{ }(i,j) \ne (k,l)\).
    \end{center}
    where \(A\) is the adjacency matrix of graph \(G\), \(n\) is the number of nodes.
\end{definition}

It still retains the properties stated in Theorem 1. Moreover, the subsequent algorithm design is largely similar to that for undirected graphs, with the only necessary adjustment being the consideration of directionality. Here, if we define triangles and quadrangles in directed graphs as 3/4-step loops without traversing the same edge more than once, the corresponding algorithms are as follows:


\begin{algorithm}[H]
\caption{GNAM'}
\begin{algorithmic}[1]
\Statex \textbf{Input:} \(\epsilon \in \mathbb{R}_{\geq 0}\), graph \(G\)’s adjacency list \(\mathbf{a}_1\),\(\mathbf{a}_2\),...,\(\mathbf{a}_n\) \(\in\) \(\left\{ 0,1 \right\} ^n\) .
\Statex \textbf{Output:} Noisy adjacency matrix of graph \(G\).
\For{\textit{each user} \(u=1\) to \(n\)}\textbf{:}
    \State \(\tilde{\mathbf{a}}_u \gets \textit{local randomizer}\left( \mathbf{a}_u, \epsilon \right) \)
    \State \textbf{send} \(\tilde{\mathbf{a}}_u\) to \textit{data collector}
\EndFor
\Statex \textbf{Data collector do:}
\State \( \hat{A} \gets \textit{estimate algorithm}\left(\tilde{A}\right) \)
\State \textbf{return} \(\hat{A}\)
\end{algorithmic}
\end{algorithm}




\begin{algorithm}[H]
\caption{TriOR'}
\begin{algorithmic}[1]
\Statex \textbf{Input:} \(\epsilon \in \mathbb{R}_{\geq 0}\), graph \(G\) .
\Statex \textbf{Output:} Estimate  \(\hat{f}^{\bigtriangleup}\left( G \right)\)  of \(f^{\bigtriangleup}\left( G \right)\).
\State \(\hat{A} \gets \text{GNAM}(G,\epsilon)\)
\State \textbf{return} \( \text{tr}\left( \hat{A}^3 \right) /3 \)
\end{algorithmic}
\end{algorithm}




\begin{algorithm}[H]
\caption{TriTR'}
\begin{algorithmic}[1]
\Statex \textbf{Input:} Graph \(G\), \(\epsilon_1, \epsilon_2 \in \mathbb{R}_{\geq 0} \).
\Statex \textbf{Output:} Estimate \( \hat{f}^{\bigtriangleup}\left( G \right) \) of \(f^{\bigtriangleup}\left( G \right)\).
\Statex \#First round:
\State \(\hat{A} \gets \text{GNAM}(G,\epsilon_1)\)
\Statex \#Second round:
\For{\textbf{each} \textit{user} \(u=1\) to \(n\)}\textbf{:}
    \State \textbf{download} \(\hat{A}\)
    \State \(sum_u \gets \sum_{\left( i,j \right):a_{ui}=a_{ju}=1}{\hat{a}_{ij}}\)
    \State \(\hat{T}_u \gets \textit{second randomizer}\left( sum_u, \epsilon_2 \right) \)
    \State \textbf{upload} \(\hat{T}_u\) to \textit{data collector}
\EndFor
\Statex \textit{data collector} \textbf{do:}
\State \(\hat{f}^{\bigtriangleup}\left( G \right) \gets \frac{1}{3}\sum_{i=u}^n{\hat{T}_u}\)
\State \textbf{return} \(\hat{f}^{\bigtriangleup}\left( G \right)\)
\end{algorithmic}
\end{algorithm}



\begin{algorithm}[H]
\caption{TriMTR'}
\begin{algorithmic}[1]
\Statex \textbf{Input:} Graph \(G\), \(\epsilon_1, \epsilon_2 \in \mathbb{R}_{\geq 0} \).
\Statex \textbf{Output:} Estimate \( \hat{f}^{\bigtriangleup}\left( G \right) \) of \(f^{\bigtriangleup}\left( G \right)\).
\Statex \#First round:
\State \(\hat{A} \gets \text{GNAM}(G,\epsilon_1)\)
\State \textit{Data collector} \textbf{calculate:} \(\hat{B} \gets \hat{A}^2\)
\Statex \#Second round:
\For{\textbf{each node} \(u=1\) to \(n\)}\textbf{:}
    \State \textbf{download} the \(u\)-th column of \(\hat{B}\)
    \State \(sum_u \gets \sum_{i: a_{ui}=1}{\hat{b}_{iu}}\)
    \State \(\hat{T}_u \gets \textit{second randomizer}\left( sum_u, \epsilon_2 \right) \)
    \State \textbf{upload} \(\hat{T}_u\) to \textbf{data collector}
\EndFor
\Statex \textbf{Data collector do:}
\State \(\hat{f}^{\bigtriangleup}\left( G \right) \gets \frac{1}{3}\sum_{u=1}^n{T_u}\)
\State \textbf{return} \(\hat{f}^{\bigtriangleup}\left( G \right)\)
\end{algorithmic}
\end{algorithm}




\begin{algorithm}[H]
\caption{QuaTR'}
\begin{algorithmic}[1]
\Statex \textbf{Input:} Graph \(G\), \(\epsilon_1, \epsilon_2 \in \mathbb{R}_{\geq 0} \).
\Statex \textbf{Output:} Estimate \( \hat{f}^{\Box}\left( G \right) \) of \(f^{\Box}\left( G \right)\).
\Statex \#First round:
\State \(\hat{A} \gets \text{GNAM}(G,\epsilon_1)\)
\State \textit{Data collector} \textbf{calculate:} \(\hat{B} \gets \hat{A}^2\)
\Statex \#Second round:
\For{\textbf{each node} \(u=1\) to \(n\)}\textbf{:}
    \State \textbf{download} \(\hat{B}\)
    \State \(sum_u \gets \sum_{\left( i,j \right):a_{ui}=a_{ju}=1}{ \hat{b}_{ij}}\)
    \State \(\hat{Q}_u \gets \textit{second randomizer}\left( sum_u, \epsilon_2 \right) \)
    \State \textbf{upload} \(\hat{Q}_u\) to \textbf{data collector}
\EndFor
\Statex \textbf{Data collector do:}
\State \(\hat{f}^{\Box}\left( G \right) \gets \frac{1}{4}\sum_{u=1}^n{\hat{Q}_u}\)
\State \textbf{return} \(\hat{f}^{\Box}\left( G \right)\)
\end{algorithmic}
\end{algorithm}

Among these changes, there are only three modifications: (1) the coefficient by which each algorithm divides at the end is adjusted to account for the single directionality of edges in directed graphs, as opposed to the bidirectional nature in undirected graphs; (2) in the quadrangle algorithm, there is no need to subtract 1 in line 5, as the directed nature of the edges prevents traversal back along the original path; and (3) in TriTR and QuaTR, when calculating \( \text{sum}_u \), the noise relationship added changes from \( a_{ui} = a_{uj} = 1 \) to \( a_{ui} = a_{ju} = 1 \).

Furthermore, although their variances do not match the specific expressions in undirected graphs, they still satisfy the Variance in Matrix Form when coefficients are ignored. The proofs for directed graphs are not elaborated in detail here, as the proof methodology closely resembles that used for undirected graphs.



