To facilitate subsequent proofs, let us get Lemma 1.

\begin{lemma}
Let \(Z_1, Z_2, \ldots\) be a sequence of mutually independent random variables, and for each \(i\), \(\mathbb{E}\left[Z_i\right]=0 \). Then, for two finite integer sequences \(\alpha=(\alpha_1, \alpha_2, \ldots, \alpha_{n1})\) and \(\beta=(\beta_1, \beta_2, \ldots, \beta_{n2})\), and their corresponding exponent sequences \(k=(k_1,...,k_{n_1}) \in \left\{1,2\right\}^{n_1}\), \(l=(l_1,...,l_{n_2}) \in \left\{1,2\right\}^{n_2}\) satisfies:
\[\mathbb{E} \left( \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} \right)=0, \mathbb{E} \left( \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right)=0\]
And there exists a number \(m \in \alpha \cup \beta\), \(m \notin \alpha \cap \beta\), and the corresponding exponent \(q\) for that number \(m\) is \(1\), it holds that:
\[
\mathbb{V} \left( \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} + \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right) = \mathbb{V} \left( \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} \right) + \mathbb{V} \left( \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right)
\]
\end{lemma}

\textbf{Proof.} 

\begin{align*}
&\mathbb{V} \left( \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} + \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right)\\
&=\mathbb{E} \left( \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} + \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right)^2\\
&=\mathbb{E} \left[ \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} \right]^2 + \mathbb{E} \left[\prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right]^2 + 2\mathbb{E}\left[ \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} \cdot  \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right]\\
&=\mathbb{V} \left( \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} \right) + \mathbb{V} \left( \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right)
\end{align*}


The expectation \(\mathbb{E}\left[ \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} \cdot  \prod_{i=1}^{n_2}{Z_{\beta_i}^{k'_i}} \right]=0\) holds because there exists an \(m \in \alpha \cup \beta\), \(m \notin \alpha \cap \beta\) and the exponent of \(Z_m\) is 1. Because the independence among \(Z_i\), \(Z_m\) can be factored out. Let \(Q\) denote the remaining product. Then we have:

\[
\mathbb{E}\left[ \prod_{i=1}^{n_1}{Z_{\alpha_i}^{k_i}} \cdot  \prod_{i=1}^{n_2}{Z_{\beta_i}^{l_i}} \right] = \mathbb{E}\left[ Z_m \right] \cdot \mathbb{E}\left[ Q \right] = 0
\]












\subsection{Proof of Theorem 4}

In the proof that follows, we continue to use the notation in Theorem 1, denoting \(\hat{A} = A + X\).

The proof of unbiasedness follows easily from the second clause of Theorem 3:

\[
\mathbb{E} \left[ \frac{\text{tr}\left( \hat{A}^3 \right)}{6} \right] = \frac{\text{tr}\left( A^3 \right)}{6} = f^{\bigtriangleup}\left( G \right)
\]

Then the MSE:

\begin{center}
\(\text{MSE}(\hat{f}^{\bigtriangleup}(G))=\mathbb{E}\left[\hat{f}^{\bigtriangleup}(G)-\mathbb{E}\left[\hat{f}^{\bigtriangleup}(G)\right]\right]^2\)

\(=\mathbb{E}\left[\hat{f}^{\bigtriangleup}(G)-f^{\bigtriangleup}(G)\right]^2=\mathbb{V}(\hat{f}^{\bigtriangleup}(G))\).
\end{center}

On the diagnal:
\begin{align*}
\hat{c}_{ii}=&c_{ii}+\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}x_{ki}}}+\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}x_{jk}a_{ki}}}+\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}a_{jk}a_{ki}}}\\
&+\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}x_{jk}x_{ki}}}+\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}a_{jk}x_{ki}}}+\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}x_{jk}a_{ki}}}\\
&+\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}x_{jk}x_{ki}}}
\end{align*}

Therefore:
\begin{align*}
\mathbb{V}\left( \text{tr}\left(\hat{A}^3\right) \right)&=\mathbb{V}\left(\sum_{i=1}^n{\hat{c}_{ii}}\right)\\
&=\begin{aligned}[t]
&\mathbb{V}\bigg(\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}a_{ki}}}}+3\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}x_{ki}}}} \\
&+3\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}x_{jk}x_{ki}}}}+\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}x_{jk}x_{ki}}}}\bigg)
\end{aligned}
\end{align*}


According to Lemma 1, the variance of the aforementioned expression is equal to the sum of the variances of its individual components:
\begin{align*}
&\mathbb{V}\left( \text{tr}\left(\hat{A}^3\right) \right)=\\
&\begin{aligned}[t]
&\mathbb{V}\left(\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}a_{ki}}}}\right)+9\mathbb{V}\left(\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}x_{ki}}}}\right) \\
&+9\mathbb{V}\left(\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}x_{jk}x_{ki}}}}\right)+\mathbb{V}\left(\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}x_{jk}x_{ki}}}}\right)
\end{aligned}
\end{align*}

Next, the overall variance can be calculated by determining the variance of these four components. The first:
\[\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}a_{ki}}}}\]

This is a constant, equal to \(\text{tr}(A^3)\), and its variance is 0.

The second item:
\[\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}x_{ki}}}}\]

From the perspective of the graph, \(a_{ij}a_{jk}\) means that there exist a path starting from \(v_i\) and passing through \(v_j\) to \(v_k\) in the actual graph. If this path exists, then \(x_{ki}\) will be added to this term. So \( x_{ij} \) will be added \( b_{ij} \) times. Since this is in an undirected graph, \( x_{ji} \) will also be added \( b_{ij} \) times, and \( x_{ij}=x_{ji} \), therefore:

\[\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}x_{ki}}}}=2\sum_{i=1}^n{\sum_{j=i+1}^n{b_{ij}x_{ij}}}\]

Given that \( \mathbb{V}(x_{ij}) = \mathbb{V}(a_{ij}) = \sigma^2 \), we have:

\[
\mathbb{V}\left( \sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}a_{jk}x_{ki}}}} \right)=4\sigma^2\sum_{i=1}^n{\sum_{j=i+1}^n{b_{ij}^{2}}}
\]

Next, we analyze the third term:
\[\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}x_{jk}x_{ki}}}}=\sum_{i=1}^n{\sum_{j=1}^n{a_{ij}\sum_{k=1}^n{x_{jk}x_{ki}}}}\]

If there exists an undirected edge \((v_i, v_j)\) in the graph, then \(\sum_{k=1}^n{x_{jk}x_{ki}}\) will be added into the third term. Let \( I_{\text{proposition}} = 1 \) if the proposition holds true, and \( I_{\text{proposition}} = 0 \) otherwise. In addition, beacuse \(x_{ii}=0\), therefore:
\[\sum_{i=1}^n{\sum_{j=1}^n{a_{ij}\sum_{k=1}^n{x_{jk}x_{ki}}}}=2\sum_{i=1}^n{\sum_{j=i+1}^n{ \left(I_{\left( v_i,v_j \right) \in E} \cdot \sum_{k=1,k \ne i,j}^n{x_{ik}x_{kj}} \right)}}
\]

According to Lemma 1, and \(\mathbb{V}(x_{ik}x_{kj})=\mathbb{V}(x_{ik}) \cdot \mathbb{V}(x_{kj})=\sigma^4\). Therefore:
\[
\mathbb{V}\left( \sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{a_{ij}x_{jk}x_{ki}}}}\right)=4\sigma^4(n-2)|E|
\]

The fourth term:
\[\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}x_{jk}x_{ki}}}}\]

Since in an undirected graph, \(x_{ij}=x_{ji}\), \(x_{ii}=0\), thus:
\[\sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}x_{jk}x_{ki}}}}=6\sum_{i=1}^n{\sum_{j=i+1}^n{\sum_{k=j+1}^n{x_{ij}x_{jk}x_{ki}}}}
\]
Based on Lemma 1, and \(\mathbb{V}(x_{ij}x_{jk}x_{ki})=\mathbb{V}(x_{ij}) \cdot \mathbb{V}(x_{jk}) \cdot \mathbb{V}(x_{ki})=\sigma^6\), we get:

\[
\mathbb{V}\left( \sum_{i=1}^n{\sum_{j=1}^n{\sum_{k=1}^n{x_{ij}x_{jk}x_{ki}}}}\right)=6 \sigma^6 n\left( n-1 \right) \left( n-2 \right)
\]

According to all the above equations, we get:
\begin{align*}
&\text{MSE}(\hat{f}^{\bigtriangleup}\left( G \right))\\
&=\mathbb{V}(\hat{f}_1^{\bigtriangleup}\left( G \right))=\mathbb{V}\left( \text{tr}\left(\hat{A}^3\right)/6 \right)\\
&=\sigma^2\sum_{i=1}^n{\sum_{j=i+1}^n{b_{ij}^{2}}}+\sigma^4(n-2)|E|+\frac{1}{6} \sigma^6 n\left( n-1 \right) \left( n-2 \right)
\end{align*}

Even if each node has \(d_{\max}\) edges, there can be at most \(n \cdot d_{\max}^2\) paths of the form \(v_i \rightarrow v_j \rightarrow v_k\) in the graph. Each \(b_{ij} \leqslant d_{\max}\). Given a fixed number of paths like \(v_i \rightarrow v_j \rightarrow v_k\), concentrating all the paths on \(nd_{\max}\) \(b_{ij}\), each \(b_{ij} = d_{\max}\), can maximize \(\sum_{i=1}^n{\sum_{j=i+1}^n{b_{ij}^{2}}}\) to \(nd_{\max}^3\). In undirected graph, \(|E| = \frac{1}{2}nd_{\text{avg}} \leqslant  \frac{1}{2}nd_{\max}\), and \(n(n-1)(n-2) \leqslant  n^3\). Therefore:
\[\text{MSE}\left( \hat{f}^{\bigtriangleup}\left( G \right) \right) \leqslant \sigma^2nd_{\max}^3+\frac{1}{2}\sigma^4n^2d_{\max}+\frac{1}{6}\sigma^6n^3\]

Therefore,
\[\text{MSE}\left( \hat{f}^{\bigtriangleup}\left( G \right) \right) \leqslant O(nd_{\max}^3+n^3).\]



