\subsection{Proof of Theorem 15}

Given the assumption that the clustering coefficient of a graph remains constant, the number of triangles in the graph is proportional to the number of 2-stars in the graph. This relationship can be denoted as \( f^{\bigtriangleup}(G) = k \#\text{2-star} \).

Considering a 2-star to be composed of a central node and its two incident edges, the total number of 2-stars in the graph can be calculated by the following formula:

\[
\#\text{2-star}=\sum_{i=1}^{n} d_i \cdot (d_i - 1) = \sum_{i=1}^{n} d_i^2 - 2|E| \approx \sum_{i=1}^{n} d_i^2
\]

Therefore, \(f^{\bigtriangleup}(G) \approx k\sum_{i=1}^{n} d_i^2\).

Here, we focus specifically on the impact of the privacy budget and the structure of the graph (number of nodes \( n \) and the degree values \( d_i \)) on convergence. We primarily consider the order of magnitude and treat other terms as constant coefficients. Therefore, we get \(f^{\bigtriangleup}(G) = O(\sum_{i=1}^{n} d_i^2)\).

First, we address TriTR, whose more precise expression for MSE is:

\[\text{MSE} \leqslant O\left(\frac{\sum_{i=1}^n{\sum_{j=i+1}^n{b_{ij}^2}}}{\epsilon_1^2}+ \frac{|E|}{\epsilon_1^2\epsilon_2^2}+\frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2} \right)\]

Because \(b_{ij}=\sum_{k=1}^n{a_{ik}a_{kj}} \leqslant \sum_{k=1}^n{a_{ik}}=d_i\), Therefore:

\[\sum_{i=1}^n{\sum_{j=i+1}^n{b_{ij}^2}} \leqslant \sum_{i=1}^n{\sum_{j=i+1}^n{d_i^2}} \leqslant n\sum_{i=1}^n{d_i^2}\]

Therefore:

\[\text{MSE} \leqslant O\left(\frac{n\sum_{i=1}^n{d_i^2}}{\epsilon_1^2} + \frac{\sum_{i=1}^n{d_i}}{\epsilon_1^2\epsilon_2^2} + \frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2} \right)\]

According to Jensen's inequality, we have:

\[ABE \leqslant O\left(\sqrt{\frac{n\sum_{i=1}^n{d_i^2}}{\epsilon_1^2} + \frac{\sum_{i=1}^n{d_i}}{\epsilon_1^2\epsilon_2^2} + \frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2}} \right)\]

Then the RE:

\begin{align*}
RE &\leqslant O\left(\frac{\sqrt{\frac{n\sum_{i=1}^n{d_i^2}}{\epsilon_1^2} + \frac{\sum_{i=1}^n{d_i}}{\epsilon_1^2\epsilon_2^2} + \frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2}} }{\sum_{i=1}^{n} d_i^2} \right)\\
&=O\left(\sqrt{\frac{\frac{n\sum_{i=1}^n{d_i^2}}{\epsilon_1^2} + \frac{\sum_{i=1}^n{d_i}}{\epsilon_1^2\epsilon_2^2} + \frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2}}{ \left( \sum_{i=1}^{n} d_i^2 \right)^2 } } \right)\\
&\leqslant O\left( \sqrt{ \frac{n}{\epsilon_1^2\sum_{i=1}^n{d_i^2}}} + \sqrt{\frac{\sum_{i=1}^n{d_i}}{\epsilon_1^2\epsilon_2^2\left( \sum_{i=1}^{n} d_i^2 \right)^2}} + \sqrt{\frac{1}{\epsilon_2^2\sum_{i=1}^n{d_i^2}}} \right)
\end{align*}

Because \( nd_{\text{avg}}^2=\sum_{i=1}^n{d_{\text{avg}}^2} \leqslant \sum_{i=1}^n{d_i^2}\), with equality if and only if \( d_i = d_{\text{avg}} \) for any \(i \in [n]\). Therefore:

\begin{align*}
RE & \leqslant O\left( \sqrt{ \frac{n}{\epsilon_1^2nd_{\text{avg}}^2}} + \sqrt{\frac{nd_{\text{avg}}}{\epsilon_1^2\epsilon_2^2 n^2d_{\text{avg}}^4 }} + \sqrt{\frac{1}{\epsilon_2^2nd_{\text{avg}}^2}} \right)\\
&\leqslant O\left( \sqrt{ \frac{1}{\epsilon_1^2d_{\text{avg}}^2}} + \sqrt{\frac{1}{\epsilon_1^2\epsilon_2^2 nd_{\text{avg}}^3 }} + \sqrt{\frac{1}{\epsilon_2^2nd_{\text{avg}}^2}} \right)\\
&= O\left( \frac{1}{\epsilon_1d_{\text{avg}}} + \frac{1}{\epsilon_1\epsilon_2 \sqrt{n}d_{\text{avg}}^{\frac{3}{2}} } + \frac{1}{\epsilon_2\sqrt{n}d_{\text{avg}}} \right)
\end{align*}



Next, we address TriMTR. Because \(nd_{\text{avg}}=2|E|\), the more precise expression for the MSE of TriTR is:


\[\text{MSE} \leqslant O\left(\frac{\sum_{i=1}^n{\sum_{j=i+1}^n{b_{ij}^2}}}{\epsilon_1^2}+ \frac{n^2d_{\text{avg}}}{\epsilon_1^4} + \frac{n^2}{\epsilon_1^4\epsilon_2^2}+\frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2} \right)\]

Using a similar scaling method as TriTR, we obtain:

\[\text{MSE} \leqslant O\left(\frac{n\sum_{i=1}^n{d_i^2}}{\epsilon_1^2}+ \frac{n^2d_{\text{avg}}}{\epsilon_1^4} + \frac{n^2}{\epsilon_1^4\epsilon_2^2}+\frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2} \right)\]

Therefore, the Relative Err:

\begin{align*}
RE &\leqslant O\left(\sqrt{ \frac{ \frac{n\sum_{i=1}^n{d_i^2}}{\epsilon_1^2}+ \frac{n^2d_{\text{avg}}}{\epsilon_1^4} + \frac{n^2}{\epsilon_1^4\epsilon_2^2}+\frac{\sum_{i=1}^n{d_i^2}}{\epsilon_2^2}}   { 
\left( \sum_{i=1}^n{d_i^2}  \right)^2  }  }\right) \\
& \leqslant O\left( \frac{1}{\epsilon_1} \sqrt{\frac{n}{ nd_{\text{avg}}^2 }}
+ \frac{1}{\epsilon_1^2} \sqrt{\frac{n^2d_{\text{avg}}}{ n^2d_{\text{avg}}^4 }}
+ \frac{1}{\epsilon_1^2 \epsilon_2} \sqrt{\frac{n^2}{ n^2d_{\text{avg}}^4 }}
+ \frac{1}{\epsilon_2} \sqrt{\frac{1}{ nd_{\text{avg}}^2 }}
\right)\\
& = O\left( \frac{1}{\epsilon_1} \sqrt{\frac{1}{ d_{\text{avg}}^2 }}
+ \frac{1}{\epsilon_1^2} \sqrt{\frac{1}{ d_{\text{avg}}^3 }}
+ \frac{1}{\epsilon_1^2 \epsilon_2} \sqrt{\frac{1}{ d_{\text{avg}}^4 }}
+ \frac{1}{\epsilon_2} \sqrt{\frac{1}{ nd_{\text{avg}}^2 }}
\right)\\
& = O\left( \frac{1}{\epsilon_1 d_{\text{avg}}}
+ \frac{1}{\epsilon_1^2 d_{\text{avg}}^{\frac{3}{2}}}
+ \frac{1}{\epsilon_1^2 \epsilon_2d_{\text{avg}}^2}
+ \frac{1}{\epsilon_2 \sqrt{ n } d_{\text{avg}}}
\right)
\end{align*}


\subsection{Proof of Theorem 16}

\textbf{Proof.} Given the true number:
\[f^{\text{2-star}}\left( G \right)=\sum_{u=1}^n{d_u(d_u-1)}\]
Let \(Y_u \sim \text{Lap}(1/\epsilon_0)\), then \(\mathbb{E}[Y_u]=0\), \(\mathbb{E}[Y_u^2]=\mathbb{V}[Y_u]=\frac{2}{\epsilon_0^2}\), \(\mathbb{E}[Y_u^3]=0\), \(\mathbb{E}[Y_u^4]=\frac{24}{\epsilon_0^4}\), the first property:
\begin{align*}
&\mathbb{E}[\hat{f}^{\text{2-star}}\left( G \right)]\\
=&\mathbb{E}[\sum_{u=1}^n{\left[(d_u+Y_u)(d_u-1+Y_u)-\frac{2}{\epsilon_0^2}\right]}] \\
=&\sum_{u=1}^n{\left[\mathbb{E}\left[(d_u+Y_u)(d_u-1+Y_u)\right]-\frac{2}{\epsilon_0^2}\right]} \\
=&\sum_{u=1}^n{\left[d_u(d_u-1)+(2d_u-1)\mathbb{E}[Y_u]+\mathbb{E}[Y_u^2]-\frac{2}{\epsilon_0^2}\right]}\\
=&\sum_{u=1}^n{d_u(d_u-1) }\\
=&f^{\text{2-star}}\left( G \right)
\end{align*}

Second property:
\begin{align*}
&\mathbb{V}(\hat{f}^{\text{2-star}}\left( G \right))\\
=&\mathbb{V}(\sum_{u=1}^n{\left[(d_u+Y_u)(d_u-1+Y_u)-\frac{2}{\epsilon_0^2}\right]}) \\
=&\sum_{u=1}^n{\left[\mathbb{V}\left((d_u+Y_u)(d_u-1+Y_u)\right)-\frac{2}{\epsilon_0^2}\right]} \\
=&\sum_{u=1}^n{\left[\mathbb{V}((2d_u-1)Y_u+Y_u^2)\right]}\\
=&\sum_{u=1}^n{\left[ \mathbb{E}[(2d_u-1)Y_u+Y_u^2)^2] - \frac{4}{\epsilon_0^4} \right]}\\
=&\sum_{u=1}^n{\left[ \mathbb{E}[(2d_u-1)^2 Y_u^2 + 2(2d_u-1)Y_u^3 + Y_u^4] - \frac{4}{\epsilon_0^4} \right]}\\
=&\sum_{u=1}^n{\left[ \mathbb{E}[(2d_u-1)^2 Y_u^2] + \mathbb{E}[ Y_u^4] - \frac{4}{\epsilon_0^4} \right]}\\
=&\sum_{u=1}^n{\left[ 2 (2d_u-1)^2\frac{1}{\epsilon_0^2}  + \frac{20}{\epsilon_0^4} \right]}\\
=&\frac{8}{\epsilon_0^2}\sum_{u=1}^n{d_u^2}-\frac{16}{\epsilon_0^2}|E|+\frac{2}{\epsilon_0^2}n+\frac{20}{\epsilon_0^4}n
\end{align*}

Treating \(\epsilon_0\) as a constant, we obtain:
\[
\text{MSE}=O(\sum_{u=1}^n{d_u^2})=O(\#2\text{-star})
\]
Thus:
\[
\text{RE}=O(\frac{\sqrt{\#2\text{-star}}}{\#2\text{-star}})=O(\frac{1}{\sqrt{\#2\text{-star}}})
\]



