\section{Preliminaries}\label{SEC:PRELIMINARIES}

In this paper, we denote the set of natural numbers by $\mathbb{N}$. For any natural numbers $i$ and $j$ with $i \leq j$, we define $\mathbb{N}[i, j]=[i,j]\cap\mathbb{N}$.

\subsection{Join Query} Given a finite attribute set $\mathrm{Att}$ and a set $U\subseteq \mathrm{Att}$, a \emph{tuple} over $U$ is a function $t:U\rightarrow\mathbb{N}$, where $\mathbb{N}$ is the set of all integers, and a projection of a tuple $t$ on $V\subseteq U$, say $t[V]$, is a tuple that satisfies $t[V](v)=t(v)$ for each $v\in V$. A relation $R$ is a set of tuples over an identical attribute set $U$, say $\mathrm{att}(R)=U$.
Then a join query $Q$ is defined as a set of relations $\{R_1, \dots, R_m\}$, and can be expressed as $Q=R_1\Join\dots\Join R_m$. Then let $|Q|=\sum_{i=1}^m|R_i|$ be the sum of sizes of the relations in $Q$ (\emph{i.e.} the size of input), and the result of the query $Q$ is defined as follows:
\begin{equation}
\mathit{Res}(Q)=\{t\text{ over }\mathrm{att}(Q)|\forall R\in Q: t[\mathrm{att}(R)]\in R\},
\end{equation}
where $\mathrm{att}(Q)=\bigcup_{R\in Q}\mathrm{att}(R)$.
Let $\textrm{dom}_Q(v)$ denote the \emph{active domain} of the attribute $v$, more specifically,
\begin{equation}
\textrm{dom}_Q(v)=\bigcup_{R\in Q}\bigcup_{v\in\mathrm{att}(R)}\{t(v)|t\in R\},
\end{equation}
then we have $\mathit{Res}(Q)\subseteq\prod_{v\in\mathrm{att}(Q)}\mathrm{dom}_Q(v)$.

\subsection{AGM Bound} Given a join query $Q$, the \emph{schema graph} of $Q$ is defined as a hypergraph $G_Q=(V,E)$, where $V=\mathrm{att}(Q)$ and $E=\{\mathrm{att}(R)|R\in Q\}$. Let $c:E\rightarrow(0,1)$ be a fractional edge cover of $G_Q$, \emph{i.e.}, $\forall v\in V$,
$\sum_{v\in e}c(e)\ge 1$.
Then $|\mathit{Res}(Q)|\le \textrm{AGM}_c(Q)$~\cite{AGMBound}, where
\begin{equation}
\textrm{AGM}_c(Q):=\prod_{R\in Q}|R|^{c(\mathrm{att}(R))}.
\end{equation}
% In this paper, since both the sizes of relations and queries are integers, the floor of the AGM bound still serves as an upper-bound for the size of the join results. Therefore, without loss of generality, unless otherwise specified, we use the notations $\mathrm{AGM}_c(Q)$ to refer to the floored AGM bound (\emph{i.e.} $\lfloor\prod_{R\in Q}|R|^{c(\mathrm{att}(R))}\rfloor$).

Moreover, let $EC(G_Q)$ denotes the set of all fractional edge covers of $G_Q$, the minimized AGM bound of $Q$, say $\textrm{AGM}(Q)=\min_{c\in EC(G_Q)}\textrm{AGM}_c(Q)$, is tight: there exists a join query $Q^*$ that satisfies $|\mathit{Res}(Q^*)|=\Omega(\textrm{AGM}(Q^*))$~\cite{AGMBound}.
Note that the AGM bound can be efficiently computed with only the sizes of the relation tables, and the minimized AGM bound can be calculated by solving a linear program in $O(1)$ time under data complexity. 



\subsection{Uniform Sampling} 
A \emph{join sampling algorithm} outputs each join result tuple with an identical probability.    
Formally, a join sampling algorithm is a randomized algorithm $\mathcal{G}$ that takes a join query $Q$ as input and outputs a tuple in $Res(Q)$, such that
\begin{equation}
    \forall t\in \mathit{Res}(Q), \mathrm{Pr}(\mathcal{G}(Q)\text{ outputs }t)=\frac{1}{|\mathit{Res}(Q)|}.
\end{equation}

