\begin{enumerate}
    \item each node $u\in T_B$ corresponds bijectively to an interval $I_u = [u.l, u.h] \in B$, and stores it via $u.l$ and $u.h$,
    \item each node $u\in T_B$ maintains $u.\textit{left}$ and $u.\textit{right}$ that point to its left child and right child,
    and if $v$ is the left (right) child of $u$, then $v.h < u.l$ ($v.l > u.h$),
    \item each node $u\in T_B$ maintains $u.\textit{take}$, which denotes the sum of lengths of the intervals in the subtree rooted in $u$,
    % \textit{i.e.},
    % \begin{enumerate}
    %     \item if $u$ is a leaf of $T_B$, $u.take=u.h-u.l+1$,
