\subsection{The Enumeration Framework}
% For any join query $Q$, let $N$ be an upper-bound of $|\mathit{Res}(Q)|$ such that $\forall i>N,\varphi_Q(i)=\textit{false}$, as shown in Algorithm~\ref{ALG:BPREnum}, we enumerate all tuples in $\mathit{Res}(Q)$ by picking integers uniformly at random $\mathbb{N}[1,N]\setminus B$, once an integer $i$ is picked, we output $\varphi_Q(i)$ if $\varphi_Q(i)\neq \textit{false}$.
Given any join query $Q$, let $N$ be an upper bound of $|\mathit{Res}(Q)|$ such that $\forall i>N,\varphi_Q(i) = \textit{false}$.  
Algorithm~\ref{ALG:BPREnum} enumerates all tuples in $\mathit{Res}(Q)$ by repeatedly picking integers uniformly at random from $[1, N] \setminus B$, where $B$ is a set of banned intervals containing trivial and picked integers.  
Each picked integer $i$ is passed to $\textsc{RRAccess}^{Q,\varphi}$.
If $\varphi_Q(i)\neq false$, in which case $\textsc{RRAccess}^{Q,\varphi}$ returns a valid result tuple, then the algorithm outputs the result tuple, and $[i,i]$ is inserted into $B$ to avoid repetition;  
otherwise, if $\varphi_Q(i) = \textit{false}$, indicating that $i$ lies in a trivial interval $I$ returned by $\textsc{RRAccess}^{Q,\varphi}$, then the entire interval $I$ is inserted into $B$.  
This process ensures that each result tuple is output exactly once.
Moreover, at each step, the output tuple (if exists) is uniformly sampled from the set of unenumerated join results.

\begin{algorithm}
    \caption{\textsc{REnum}}\label{ALG:BPREnum}
    \LinesNumbered
    \KwIn{$Q$}
    \KwOut{$\mathit{Res}(Q)$ in a random order}
    $B\leftarrow\emptyset$, $N_\mathrm{ban}\leftarrow 0$\;
    \While{$N_\mathrm{ban}<N$}{
        $i\leftarrow B.pick(N)$\;
        $res\leftarrow\textsc{RRAccess}^{Q,\varphi^*}(i)$\;
        \If{$res$ is a tuple in $\mathit{Res}(Q)$}{\textbf{output} $res$\; $B.ban([i,i])$, $N_\mathrm{ban}\leftarrow N_\mathrm{ban} + 1$;}
        \Else(\hspace{1ex}//\texttt{\footnotesize  $res$ is a trivial interval.}){$B.ban(res)$, $N_\mathrm{ban}\leftarrow N_\mathrm{ban} + |res|$;}
    }
\end{algorithm}



\begin{lemma}\label{lem:RREnum}
    For any $Q\in\mathcal{Q}$, if $\log N\le O(\log |Q|)$ and there exists a relaxed random-access algorithm $RRAccess^{Q,\varphi}$ running in $O(\log^2|Q|)$ worst-case time and $O(\log|Q|)$ amortized time, then Algorithm~\ref{ALG:BPREnum} enumerates the result tuples in $\mathit{Res}(Q)$ in random order in expected $O(\frac{N}{|\mathit{Res}(Q)|+1}\log^2|Q|)$ delay.
    And its total running time is at most $O(N\log|Q|)$.
\end{lemma}

\begin{proof}
    % Therefore, for any $1 \leq i \leq |\mathit{Res}(Q)|$,
    % the probability that $\textsc{RRAccess}^{Q,\varphi}$ runs successfully between the output of the $(i-1)$-th and the $i$-th result tuple is greater than $\frac{|\mathit{Res}(Q)|-(i-1)}{N-N_{i-1}}$,
    \PY{
    % In our algorithmic framework, $\textsc{RRAccess}^{Q,\varphi}(i)$ returns a trivial interval that contains $i$ when $\varphi_Q(i) = \text{false}$.
    % rather than a larger trivial interval.
    To simplify the analysis, we assume that $\textsc{RRAccess}^{Q,\varphi}(i)$ returns the interval $[i, i]$ when $\varphi_Q(i) = false$.
    This choice of a minimal trivial interval, while less efficient, enables us to derive upper bounds on both the total running time and the delay of Algorithm~\ref{ALG:BPREnum}.

    \emph{Total running time.} Since $\log|B|\le \log N\le O(\log|Q|)$, all of $B.ban$, $B.pick$ and \textsc{RRAccess} run in $O(\log |Q|)$ amortized time.
    Moreover, since they run at most $N$ times, the total running time of Algorithm~\ref{ALG:BPREnum} is at most $O(N\log|Q|)$.
    }

    \emph{Enumeration delay.} Let $N_i(0\le i\le |\mathit{Res}(Q)|)$ be the random variable of the number of times that $\textsc{RRAccess}^{Q,\varphi}$ returns \textit{false} in the process of outputting the first $i$ result tuples (the $(i+N_i)$-th run of $\textsc{RRAccess}^{Q,\varphi}$ returns the $i$-th result tuple, and in particular, $N_0$=0).
    By the definition of $\varphi_Q$, for each tuple $t\in \mathit{Res}(Q)$,
    there exists only one integer $i \in \mathbb{N}[1, N]$ such that $\varphi_Q(i) = t$.
    % That is, if we define an integer $i \in \mathbb{N}[1, N]$ as ``non-trivial'' if and only if $\varphi_Q(i) \neq \textit{false}$, 
    Then there are exactly $|\mathit{Res}(Q)|$ non-trivial integers in $\mathbb{N}[1, N]$,
    and for each $0\le i\le|\mathit{Res}(Q)|$, $N_i$ is the number of trivial integers obtained by sampling (without replacement) from $\mathbb{N}[1, N]$ until exactly $i$ non-trivial integers are picked.
    This implies that for each $1\le i\le|\mathit{Res}(Q)|$, $N_i$ follows the negative hypergeometric distribution~\cite{neghyperdistribution} with parameters $N$, $N-|\mathit{Res}(Q)|$ and $i$, and its expectation is:
    \begin{equation}
        E[N_i]=\frac{i\left(N-|\mathit{Res}(Q)|\right)}{|\mathit{Res}(Q)|+1}.
    \end{equation}

    Therefore, the expected number of calls of $\textsc{RRAccess}^{Q,\varphi}$ between the output of the $(i-1)$-th result (the start of the algorithm when $i=1$) and the output of the $i$-th result is 
    \begin{equation}
            E\left[N_i-N_{i-1}+1\right]=\frac{N+1}{|\mathit{Res}(Q)|+1}=O\left(\frac{N}{|\mathit{Res}(Q)|+1}\right).
    \end{equation}
    And the expected running time of $\textsc{RRAccess}^{Q,\varphi}$ between the output of the last result tuple and the end of the algorithm is
    \begin{equation}
    \begin{aligned}
        E\left[N-N_{|\mathit{Res}(Q)|}-|\mathit{Res}(Q)|\right]&= \frac{N-|\mathit{Res}(Q)|}{|\mathit{Res}(Q)|+1}=O\left(\frac{N}{|\mathit{Res}(Q)|+1}\right).
    \end{aligned}
    \end{equation}
    Then, since $\textsc{RRAccess}^{Q,\varphi}$ runs in $O(\log^2|Q|)$ worst-case time,
    the expected delay of Algorithm~\ref{ALG:BPREnum} is $O(\frac{N}{|\mathit{Res}(Q)|+1}\log^2|Q|)$.    
\end{proof}

In the case where $N\le \mathrm{AGM}(Q)$, in other words, if $\textsc{RRAccess}^{Q,\varphi}$ in Lemma~\ref{lem:RREnum} satisfies $\forall i>\mathrm{AGM}(Q), \varphi(i)=\textit{false}$, then Algorithm~\ref{ALG:BPREnum} enumerates the join results in expected $O(\frac{\mathrm{AGM}(Q)}{|\mathit{Res}(Q)|+1}\log^2|Q|)$ delay and $O(\mathrm{AGM}(Q)\log|Q|)$ total running time, where $\rho^*$ is the fractional edge cover number of $G_Q$.

In addition, by \cite{Sample2023}, the $O(\mathrm{AGM}(Q)\log|Q|)$ total running time is nearly optimal in the worst case, unless the combinatorial $k$-clique hypothesis is false.
Moreover, since the first enumerated result tuple is a uniform sample from $Res(Q)$,
the lower bound of the expected running time of join sampling algorithms is also a lower bound of the expected delay of random-order enumeration algorithms.
Formally, the following theorem holds.
\begin{theorem}\label{thmm}
    Under the combinatorial $k$-clique hypothesis, for any $\varepsilon>0$, there is no random-order enumeration algorithm for join queries with expected $\Tilde{O}(\frac{|Q|^{\rho^*-\varepsilon}}{|\mathit{Res}(Q)|+1})$ delay after a $\Tilde{O}(|Q|)$-time preprocessing, where $\rho^*$ is the fractional edge cover number of $G_Q$.
\end{theorem}
\begin{proof}
    For $\forall\varepsilon>0$,
    if there exists a random-order enumeration algorithm $\mathcal{A}$ for join queries with expected $\Tilde{O}(\frac{|Q|^{\rho^*-\varepsilon}}{|\mathit{Res}(Q)|+1})$ delay after a $\Tilde{O}(|Q|)$-time preprocessing,
    we can define $\mathcal{B}$ as the random algorithm obtained by executing $\mathcal{A}$ until the first result tuple is outputted and then stopping the enumeration.
    Then $\mathcal{B}$ is a uniform sampling algorithm for join queries,
    and according to Markov's inequality, $\mathcal{B}$ runs in $\Tilde{O}(|Q|+\frac{|Q|^{\rho^*-\varepsilon}}{|\mathit{Res}(Q)|})$ time with high probability.
    This contradicts Theorem~\ref{thm:WCOLVUS}.
\end{proof}

This shows that, assuming a preprocessing phase of $\Tilde{O}(|Q|)$ time (\emph{e.g.}, for index construction), the expected $O(\frac{\mathrm{AGM}(Q)}{|\mathit{Res}(Q)|+1}\log^2|Q|)\le O(\frac{|Q|^{\rho^*}}{|\mathit{Res}(Q)|+1}\log^2|Q|)$ delay is nearly optimal.


\section{The Relaxed Random-Access}\label{SEC:RRATree}

% To achieve the near-optimal expected delay and total running time, an \textsc{RRAccess} running in $O(\log^2|Q|)$ worst-case time and $O(\log|Q|)$ amortized time is required. 
In this section, we describe an efficient implementation of \textsc{RRAccess} that runs in $O(\log^2|Q|)$ worst-case time and $O(\log|Q|)$ amortized time.
It is based on a logical tree structure, referred to as the relaxed random-access tree (RRATree), denoted by $\Tilde{T}_Q$.

% , on which we are able to estimate the upper-bound of the number of result tuples corresponding to the leaf nodes in each subtree of $\Tilde{T}_Q$ in $O(\log|Q|)$ time.

\subsection{Overview of RRATree and \textsc{RRAccess}}
Formally, the RRATree is defined as follows:

\begin{definition}[RRATree]\label{DEF:RRATREE}


Let $Q$ be an arbitrary join query. The RRATree of $Q$, denoted $\Tilde{T}_Q$, is a rooted tree that satisfies:

\begin{enumerate}
    \item each node $u\in\Tilde{T}_Q$ corresponds to a filter $\psi_u$,
    \item let $r$ be the root node of $\Tilde{T}_Q$, then the filter $\psi_r$ can be computed in $O(|Q|)$ time and satisfies $Q=Q|_{\psi_r}$,
    % \item for each result tuple $s\in \mathit{Res}(Q)$, there is exactly one leaf node $u\in\Tilde{T}_Q$ such that $s\in \mathit{Res}(Q|_{\psi_u})$,
    \item there is an upper-bound algorithm $upp$ which takes a filter $\psi_u$ with $u\in\Tilde{T}_Q$ as input and returns an positive integer in $O(\log|Q|)$ time, such that
    \begin{enumerate}
        % \item $upp(\psi_r)\le \mathrm{AGM}(Q)$,
        \item $\forall u\in\Tilde{T}_Q, upp(\psi_u)\ge |\mathit{Res}(Q|_{\psi_{u}})|$,
        \item for any filter $\psi_u$ with $u\in\Tilde{T}_Q$ and $upp(\psi_u)\le 1$, $\mathit{Res}(Q|_{\psi_u})$ can be computed in $O(\log|Q|)$ time,
    \end{enumerate}
    \item there is a children exploration algorithm $children$, such that for each node $u\in\Tilde{T}_Q$, $children(\psi_u)$ returns at most a constant number of filters $\psi_{v_1},\dots,\psi_{v_k}$ in $O(\log|Q|)$ time, such that
    \begin{enumerate}
        \item $\forall u\in\Tilde{T}_Q$, $children(\psi_u)=\emptyset$ iff $upp(\psi_u)\le 1$,
        \item $\bigcup_{i=1}^k\mathit{Res}(Q|_{\psi_{v_i}})=\mathit{Res}(Q|_{\psi_u})$,
        \item $\forall 1\le i<j\le k,\mathit{Res}(Q|_{\psi_{v_i}})\cap \mathit{Res}(Q|_{\psi_{v_j}})=\emptyset$,
        \item $\sum_{i=1}^k upp(\psi_{v_i})\le upp(\psi_u)$,
        \item $\forall 1\le i\le k, upp(\psi_{v_i})\le\frac{1}{2}upp(\psi_u)$.
    \end{enumerate}
\end{enumerate}

\end{definition}

Based on RRATree, we define the family of functions $\varphi^*$ with $upp$ and develop the algorithm \textsc{RRAccess}. Given a join query $Q$ and fix a partial order relation $\prec$ in the filter set, for each integer $i>0$. If there is a tuple $t\in \mathit{Res}(Q)$ such that
\begin{equation}
\label{EQ:phii}
i=\sum_{j=1}^{h-1}\sum_{\substack{\psi\prec \psi_{u_{j+1}}\\\psi\in children(\psi_{u_j})}}upp(\psi)+1,    
\end{equation}
where $u_1,\dots,u_h$ is the path from the root $r$ to the leaf $u_t$ ($u_1=r$ and $u_h=u_t$), and $u_t\in\Tilde{T}_Q$ is the leaf node such that $t\in \mathit{Res}(Q|_{\psi_{u_t}})$,
then $\varphi^*_Q(i)=s$.
Otherwise, if there does not exist such a tuple, we define $\varphi^*_Q(i)=\textit{false}$.
Then the following lemma holds.

\begin{lemma}\label{lem:upperbound}
    $\forall i>upp(\psi_r)$, $\varphi^*_Q(i)=\textit{false}$.
\end{lemma}
\ifshowproof
\begin{proof}
We prove the contrapositive: if $\varphi^*_Q(i) \neq\mathit{false}$, then $i\le upp(\psi_r)$.
    By the definition of $\varphi^*$, for each integer $i>0$ satisfying $\varphi^*_Q(i)\neq \textit{false}$, there is a tuple $t\in \mathit{Res}(Q)$ along with a root-to-leaf path $u_1,\dots,u_h$ ($u_1=r,u_h=u_t$) such that (\ref{EQ:phii}) holds. Then, let
    \begin{equation}
    \begin{aligned}
    \mathrm{sum}_j&=\sum_{\substack{\psi\prec \psi_{u_{j+1}}\\\psi\in children(\psi_{u_j})}}upp(\psi)\\
    &\le \sum_{\psi\in children(\psi_{u_j})}upp(\psi)-upp(\psi_{u_{j+1}})\\
    &\le upp(\psi_{u_j})-upp(\psi_{u_{j+1}}),
    \end{aligned}
    \end{equation}
    therefore
    \begin{equation}
    \begin{aligned}
    i&=\sum_{j=1}^{h-1}\mathrm{sum}_j+1\le \sum_{j=1}^{h-1}\left(upp(\psi_{u_j})-upp(\psi_{u_{j+1}})\right)+1\\
    &=upp(\psi_{u_1})-upp(\psi_{u_{h}})+1=upp(\psi_r).
    \end{aligned}
    \end{equation}
\end{proof}
\fi
\begin{algorithm}[t]
	\caption{$\textsc{RRAccess}^{Q,\varphi^*}$}
	\label{ALG:RRAccess}
        \LinesNumbered
	\KwIn{$i$}
	\KwOut{$\varphi^*_Q(i)$ if $\varphi^*_Q(i)\neq false$, otherwise a trivial interval containing $i$}
        $\mathit{offset}\leftarrow 0$\;
        $\psi\leftarrow \psi_r$ where $r$ is the root node of $\Tilde{T}_Q$\;
	\While{$upp(\psi)\ge 2$}{
            $\psi_1,\dots,\psi_k\leftarrow children(\psi)$\;
            \lIf{$\mathit{offset}+\sum_{j=1}^k upp(\psi_k)<i$}{\textbf{return} $[i,i]$}            
            % $r^*\leftarrow$ minimal $r\in\mathbb{N}[1,k]$ s.t. $\mathit{offset}+\sum_{j=1}^rupp(\psi_j)\ge i$\;
            $r^*\leftarrow \min\{r\in\mathbb{N}[1,k]|\mathit{offset}+\sum_{j=1}^rupp(\psi_j)\ge i\}$\;
            % $i\leftarrow i-\sum_{j=1}^{r-1}upp(\psi_j)$\;   
            $\mathit{offset}\leftarrow \mathit{offset}+\sum_{j=1}^{r^*-1}upp(\psi_j)$\;
            $\psi\leftarrow\psi_{r^*}$\;
	}
        \If{$\mathit{Res}(Q|_\psi)\neq\emptyset$}{\textbf{return} the tuple in $\mathit{Res}(Q|_\psi)$}
        \lElse{\textbf{return} $[i,i]$}
\end{algorithm}



Our relaxed random-access algorithm is implemented as Algorithm~\ref{ALG:RRAccess}.
The algorithm starts from $\psi_r$, which can be computed in $O(1)$ time after an $O(|Q|\log|Q|)$-time index construction phase.
Then in lines 3-8, the algorithm traverses $\Tilde{T}_Q$ from top to down to find the path on which the filters may contain $\varphi^* _Q(i)$.
Since for each filter $\psi$ and its children $children(\psi)=\psi_1,\dots,\psi_k$, we have $upp(\psi_{i})\le \frac{1}{2}upp(\psi)$ for any $1\le i\le k$,
which implies that the depth of $\Tilde{T}_Q$ is at most $O(\log upp(\psi_r))$ and the number of nodes in $\Tilde{T}_Q$ is $O(upp(\psi_r))$.
Moreover, with the use of a caching mechanism that stores the upper bounds and children of all traversed nodes in $\Tilde{T}_Q$ (thus avoiding redundant computation), in the case where $upp(\psi_r) \le \mathrm{AGM}(Q)$, the following lemma holds.

\begin{lemma}\label{LEM:RRAccess}
If $\psi_r$ can be computed in $O(1)$ time, and there exist an algorithm $upp$ and an algorithm $children$ satisfying the properties in Definition~\ref{DEF:RRATREE} and running in $O(\log|Q|)$ time, then if $upp(\psi_r)\le \mathrm{AGM}(Q)$, Algorithm~\ref{ALG:RRAccess} is a relaxed random-access algorithm running in $O(\log^2|Q|)$ worst-case time and $O(\log|Q|)$ amortized time.
\end{lemma}

\emph{Remarks.} For simplicity, the \textsc{RRAccess} algorithm in this section only implements the trivial interval discovery of a na\"ive method.
Specifically, when $\varphi_Q(i)=false$, the algorithm returns the singleton interval $[i, i]$. 
% This approach simplifies the analysis by avoiding the complexities associated with discovering larger intervals during this phase.
In Section~\ref{SEC:OPTIMIZE}, we will introduce techniques for discovering larger trivial intervals within the running of \textsc{RRAccess}, with the aim of improving the efficiency of enumeration in practice.

% \subsection{RRATree for Join Queries}

In the following, we introduce the proper filters of the tree nodes, the $O(\log|Q|)$-time upper-bound algorithm and the $O(\log|Q|)$-time children exploration algorithm.

\subsection{The Filters of the Tree Nodes}
In this paper, all filters corresponding to the nodes in $\Tilde{T}_Q$ are defined to be range filters.
Specifically, for each node $u \in \Tilde{T}_Q$, the filter $\psi_u$ can be expressed as a list of intervals:
\begin{equation}
    \psi_u = [[l_{u,1}, h_{u,1}], \dots, [l_{u,n}, h_{u,n}]].
\end{equation}
We further say that $\psi_u$ is an \emph{empty} range filter (or an \emph{empty range} for short) if and only if there exists $1\le i\le n$ for which $l_{u,i}>h_{u,i}$.
A tuple $t \in R$ satisfies $\psi_u$ if and only if $x_i \in [l_{u,i}, h_{u,i}]$ holds for each $x_i \in \mathrm{att}(R)$.
In Example~\ref{example}, let $\psi=[[1,2],[1,4],[1,4]]$, we have $R|_\psi=\{(1,2),(2,3)\}$, $S|_\psi=S$, $T|_\psi=\{(4,2)\}$, and then $\mathit{Res}(Q_\Delta|_\psi)=\{(2,3,4)\}$.
Moreover, the filter of the root node $r$ is
\begin{equation}
\psi_r=\left[[\mathrm{min}_Q(x_1),\mathrm{max}_Q(x_1)],\dots,[\mathrm{min}_Q(x_n),\mathrm{max}_Q(x_n)]\right],
\end{equation}
where for each $1\le i\le n$, $\max_Q(x_i)=\max\mathrm{dom}_Q(x_i)$ and $\min_Q(x_i)=\min\mathrm{dom}_Q(x_i)$.
These bounds are computed during the index construction phase in $O(|Q|)$ time.
Then, once the index is constructed, $\psi_r$ can be calculated in $O(1)$ time, and $Q|_{\psi_r}=Q$ since all tuples in $\bigcup_{R\in Q}R$ satisfy $\psi_r$.
% As an example, for $Q_\Delta$ we have $\psi_r=[[1,4],[1,4],[1,4]]$, and then $Q_\Delta=Q_\Delta|_{\psi_r}$.
% Now it remains to prove that there are two algorithms $upp$ and $children$ running in $\Tilde{O}(1)$ time that satisfies the above conditions.

We further define an important class of range filters, say the ``\emph{prefix range filters}", on which the upper-bound algorithm and the children exploration algorithm can be calculated efficiently.
\begin{definition}
    For any range filter $\psi=[[l_1,h_1],\dots,[l_n,h_n]]$, if there exists an integer $1\le s\le n$ such that $\psi$ satisfies
    \begin{enumerate}
        \item $\forall 1\le i< s$, $l_{i}=h_{i}$,
        \item $l_{s}\le h_{s}$, and
        \item $\forall s\le i\le n$, $l_{i}=\min_Q(x_i),h_{i}=\max_Q(x_i)$,
    \end{enumerate}
    then $\psi$ is a \emph{prefix range filter} with a \emph{split position} $s$.
    Moreover, if $s+1$ is not a split position of $\psi$, then $s$ is the \emph{maximum split position} of $\psi$.
\end{definition}
It is clear that $\psi_r$ is a prefix range filter with split position $1$.
We will later discuss the advantage properties of the prefix range filters and prove that all filters in the RRATree are prefix range filters.

\subsection{The Upper-Bound Algorithm}\label{SUBSEC:upp}
Let $G_Q$ be the schema graph of $Q$, given a fractional edge cover $c\in EC(G_Q)$, for the sake of ease in theoretical analysis,
we initially define $upp(\psi)=\lfloor\textrm{AGM}_c(Q|_\psi)\rfloor$ for any range filter $\psi$.
Since all the sizes of relations are integers, the floor of the AGM bound still serves as an upper-bound for the size of the join result.
Then it holds immediately that $upp(\psi)\ge |\mathit{Res}(Q|_\psi)|$.
