We now aim to prove that when $upp(\psi)\le 1$, the join result $Res(Q|_\psi)$ can be computed in $O(\log|Q|)$ time. To this end, we first define a property of $upp$, called super-additivity, and prove that when $upp$ satisfies the property, $Res(Q|_\psi)$ can be computed in $O(\log|Q|)$ time for any $\psi$ satisfying $upp(\psi)\le 1$.


\begin{property}[super-additivity]\label{prop:upp-superadditivity}
  Given any range filter $\psi = [[l_1, h_1], \dots, [l_n, h_n]]$ and $1 \leq p \leq n$,
  for any partition of the interval $[l_p, h_p]$ into $k$ disjoint sub-intervals $I_1, \dots, I_k$ such that $[l_p, h_p] = \bigcup_{i=1}^k I_i$ and $I_i \cap I_j = \emptyset$ for $i \neq j$, the following inequality holds:
    \begin{equation}
        \sum_{i=1}^k upp([[l_1,h_1],\dots,I_i,\dots,[l_n,h_n]])\le upp(\psi).
    \end{equation}
\end{property}

If an upper-bound algorithm satisfies Property~\ref{prop:upp-superadditivity}, it is referred to as \emph{super-additive}. Then the following lemma holds.

\begin{lemma}\label{LEM:AGMLEONE}
    If $upp$ is super-additive, then for any prefix range filter $\psi = [[l_{1}, h_{1}], \dots, [l_{n}, h_{n}]]$ such that $upp(\psi)\le 1$, $\mathit{Res}(Q|_{\psi})$ can be computed in $O(\log|Q|)$ time.
\end{lemma}

\ifshowproof
\begin{proof}
Since $upp(\psi)\le 1$, two cases need to be discussed.
Firstly,
for the case $upp(\psi)=0$,
we have $|\mathit{Res}(Q|_{\psi})|\le upp(\psi)=0$,
which implies that $\mathit{Res}(Q|_{\psi})=\emptyset$.
Secondly, 
for the case $upp(\psi)=1$,
we have $|\mathit{Res}(Q|_{\psi})|\leq1$.
Let $s=\max\{i|l_i\neq h_i\}$,
% be the maximum split position of $\psi$,
by Property~\ref{prop:upp-superadditivity},
there exists at most one integer $p\in\mathbb{N}[l_{s}, h_{s}]$ such that
\begin{itemize}
    \item $upp([[l_{1},h_{1}],\dots,[l_{s},p-1],\dots,[l_{n},h_{n}]])=0$,
    \item $upp([[l_{1},h_{1}],\dots,[p,p],\dots,[l_{n},h_{n}]])=1$,
    \item $upp([[l_{1},h_{1}],\dots,[p+1,h_s],\dots,[l_{n},h_{n}]])=0$.
\end{itemize}
If $upp([[l_{1},h_{1}],\dots,[p,p],\dots,[l_{n},h_{n}]])=0$ follows for every $p\in\mathbb{N}[l_{s},h_{s}]$, we have $\mathit{Res}(Q|_{\psi})=\emptyset$.
Otherwise, it is able to calculate the only integer $p\in\mathbb{N}[l_{s},h_{s}]$ by a multi-head binary search (introduced in Section~\ref{SEC:CHILDREN}) in $O(\log|Q|)$ time.
% Specifically, we binary search for $t=\min\{t|\lfloor\mathrm{AGM}_c(Q|_{[[l_{1},h_{1}],\dots,[l_{k},t],\dots,[l_{n},h_{n}]]})\rfloor>0\}$.
Then apply the same procedure to the next unfixed position of $[[l_{1},h_{1}],\dots,[p,p],\dots,[l_{n},h_{n}]]$, and continue this process iteratively on other positions as needed. If this process finally obtains $\psi^*=[[l_{1}^*, h_{1}^*], \dots, [l_{n}^*, h_{n}^*]]$ such that $upp(\psi^*)=1$ and $\forall 1\le i\le n,l_i^*=h_i^*$, then $(l_1^*,\dots,l_n^*)$ is the only tuple in $\mathit{Res}(Q|_\psi)$.
Otherwise, we have $\mathit{Res}(Q|_{\psi})=\emptyset$.
The time it takes to decide whether $\mathit{Res}(Q|_\psi)=\emptyset$ and calculate $\psi^*$ (if exists) is at most $O(n\log|Q|)$, which is $O(\log|Q|)$ in data complexity.
\end{proof}
\fi
