\subsection{The Children Exploration Algorithm} \label{SEC:CHILDREN}
During the path-finding process of \textsc{RRAccess}, in order to calculate the children of each visited node in $O(\log|Q|)$ time, we develop an efficient children exploration algorithm, which takes a prefix range filter $\psi$ as input and outputs at most a constant number of children filters $\psi_1,\dots,\psi_k$ as required in Definition~\ref{DEF:RRATREE}.
Our approach follows the active domain partitioning strategy proposed by Deng et al.~\cite{Sample2023}.
We improve their method by introducing a novel partitioning algorithm and more efficient data structures, which together reduce the computational complexity from $O(\log^d|Q|)$ to $O(\log|Q|)$, where $d=\max_{R\in Q}\mathrm{att}(R)$ denotes the maximum arity of the relations.
% such that $\mathit{Res}(Q|_{\psi_1}),\dots,\mathit{Res}(Q|_{\psi_n})$ make up a division of $\mathit{Res}(Q|_{\psi})$.
% More specifically,
% % $\mathit{Res}(Q|_{\psi\setminus\bigcup_{i=1}^k\psi_i})=\emptyset$ and for any $1\le i<j\le k$, $\psi_i\cap\psi_j=\emptyset$.
% $\mathit{Res}(Q|_\psi)=\bigcup_{i=1}^k\mathit{Res}(Q|_{\psi_i})$ and for any $1\le i<j\le k$, $\mathit{Res}(Q|_{\psi_i})\cap \mathit{Res}(Q|_{\psi_j})=\emptyset$.

\textbf{The divide operation.}
Specifically, for any range filter $\psi=[[l_1,h_1],\dots,[l_n,h_n]]$, let $s=\min\{i|l_i\neq h_i\}$, an operation named ``divide'' is defined, which takes the filter $\psi$ as input and outputs:
\begin{itemize}
    \item $\psi_{\mathrm{left}}=[[l_1,h_1],\dots,[l_s,p-1],\dots,[l_n,h_n]]$,
    \item $\psi_{\mathrm{mid}}=[[l_1,h_1],\dots,[p,p],\dots,[l_n,h_n]]$,
    \item $\psi_{\mathrm{right}}=[[l_1,h_1],\dots,[p+1,h_s],\dots,[l_n,h_n]]$
\end{itemize}
such that
\begin{enumerate}
    \item $upp(\psi_\mathrm{left})+upp(\psi_\mathrm{mid})+upp(\psi_\mathrm{right})\le upp(\psi)$,
    \item $upp(\psi_\mathrm{left})\le\frac{1}{2}upp(\psi),upp(\psi_\mathrm{right})\le\frac{1}{2}upp(\psi)$.
\end{enumerate}

Assuming the upper-bound algorithm is super-additive,
then (1) holds for any $p\in\mathbb{N}[l_s,h_s]$.
Deng et al.~\cite{Sample2023} calculate the proper division point $p$ that satisfies (2) by a binary search for the minimized integer in $[l_s,h_s]$ such that $upp(\psi_\mathrm{left})\ge \frac{1}{2}upp(\psi)$.
In each iteration of their binary search process, a count oracle implemented by a range tree is employed to calculate the cardinality of each filtered relation. This results in a time complexity of $O(\log^d|Q|)$ for the divide operation, where $d=\max_{R\in Q}|\mathrm{att}(R)|$.
In contrast, we show that when dividing a prefix range filter, the division point $p$ can be computed in $O(\log |Q|)$ time.
We achieve this by first establishing that $s$ is a valid split position of $\psi$, then reducing the problem to an equivalent optimization problem, and finally devising an efficient $O(\log |Q|)$-time algorithm to solve it.

\begin{lemma}
    Let $\psi=[[l_1,h_1],\dots,[l_n,h_n]]$ be a prefix range filter, then $s=\min\{i|l_i\neq h_i\}$ is a split position of $\psi$.
\end{lemma}
\begin{proof}
    Otherwise, there exists $s<s'\le n$ such that $[l_{s'},h_{s'}]\neq [\min_Q(x_{s'}),\max_Q(x_{s'})]$, then for $\forall i \neq s'$, $i$ is not a split position of $\psi$. Moreover, $s'$ is not a split position since $l_s\neq h_s$, then $\psi$ is not a prefix range filter, which leads to a conflict.
\end{proof}
% Let $\psi=[[l_1,h_1],\dots,[l_n,h_n]]$ be a prefix range filter, we see that $s=\min\{i|l_i\neq h_i\}$ must be a split position of $\psi$. 
For each relation $R_i\in Q$ satisfying $x_s\in\mathrm{att}(R_i)$, define $A_i =\left[t_1(x_s),\dots,t_{n_i}(x_s)\right]$,
where $n_i=|R_i|_\psi|$, $R|_\psi=\{t_1,\dots,t_{n_i}\}$ and $t_1\preceq\dots\preceq t_{n_i}$.
We observe that the task of ``calculating the division point $p$" in the divide operation can be cast as an instance of the following optimization problem:
\begin{description}
    \item[\textbf{Input:}] a constant number of sorted integer arrays $A_1,\dots,A_k$ and an integer $T$,
    \item[\textbf{Output:}] the maximum integer $p^*$ such that $F(p^*)\le T$, 
\end{description}
% \textbf{Input:} a constant number of sorted integer arrays $A_1,\dots,A_k$ and an integer $T$,
% \textbf{Output:} the maximum integer $p^*$ such that $F(N_1(p^*),\dots,N_k(p^*))\le T$, 
where $N_i(p)=|\{x\in A_i|x<p\}|$, and $F:\mathbb{N}^k\rightarrow\mathbb{N}$ is an $k$-ary non-decreasing function (For simplicity, we use $F(p)$ as shorthand for $F(N_1(p),\dots,N_k(p))$).
The reduction is obvious since
% the following lemma holds
% \begin{lemma}\label{prop:increasing}
%     For any range filter $\psi_1$, $\psi_2$ with the same lower bound for each attribute and satisfy $|R|_{\psi_1}|\le|R|_{\psi_2}|$ for each $R\in Q$, we have $upp(\psi_1)\le upp(\psi_2)$.
% \end{lemma}
% \begin{proof}
%     Since $\psi_1$ and $\psi_2$ has the same lower bound for each attribute, 
% \end{proof}
$upp$ can be viewed as a non-decreasing function over the cardinalities of the filtered relations $R_{\mathrm{left}}$ for each relation $R\in Q$ with $x_s \in \mathrm{att}(R)$.

% We develop an efficient algorithm, say the \emph{``Multi-Head Binary Search (MHBS)"} algorithm, to solve this problem in logarithmic time, which is shown as Algorithm~\ref{ALG:MHBS}.
% Assume that all tuples are sorted lexicographically as an index for each $R\in Q$,
% we propose the Multi‑Head Binary Search (MHBS) algorithm (see Algorithm~\ref{ALG:MHBS}), which solves the above problem in $O(\log \sum_{i=1}^k|A_i|)$ time.

Assuming for each relation table $R\in Q$, all tuples in $R$ are sorted lexicographically,
we propose the Multi‑Head Binary Search (MHBS) algorithm (see Algorithm~\ref{ALG:MHBS}), which solves the above problem in $O(\log \sum_{i=1}^k|A_i|)$ time.
Intuitively, the MHBS algorithm maintains a binary search interval for each array, and in each iteration, it halves the interval of one selected array, until the intervals converge, yielding the optimal result.

\begin{algorithm}
    \caption{Multi Head Binary Search (MHBS)}\label{ALG:MHBS}
    \LinesNumbered
    \KwIn{$A_1,\dots,A_k$, $T$}
    \KwOut{maximum $p^*$ such that $F(p^*)\le T$}
    \lIf{$F(|A_1|,\dots,|A_k|)\le T$}{\Return{$+\infty$}}
    \For{$1\le i\le k$}{
        \If{$r_i-l_i\le 1$}{
            \lIf{$F(A_{i}[l_i]+1)>T$}{\Return{$A_{i}[l_{i}]$}}
            \lElse{$m_{i}\leftarrow r_i$}
        }
        \lElse{
        $l_i\leftarrow 0$, $r_i\leftarrow|A_i|$, $m_i\leftarrow\lfloor\frac{l_i+r_i}{2}\rfloor$}
    }
    \While{$\exists i,r_i-l_i>1$}{
        $i_{\min}\leftarrow\arg\min\limits_{r_i-l_i>1}A_i[m_i]$\;
        $i_{\max}\leftarrow\arg\max\limits_{r_i-l_i>1}A_i[m_i]$\;
        \lIf{$F(m_1,\dots,m_k)\le T$}{
            $l_{i_{\min}}\leftarrow m_{i_{\min}}$
        }
        \lElse{
            $r_{i_{\max}}\leftarrow m_{i_{\max}}$
        }
        \lFor{$i\in\{i_{\min},i_{\max}\}$}{$m_{i}\leftarrow\lfloor\frac{l_{i}+r_{i}}{2}\rfloor$}
        \If{$\exists i\in\{i_{\min},i_{\max}\},r_{i}-l_{i}\le 1$}{
            \lIf{$F(A_{i}[l_i]+1)>T$}{\Return{$A_{i}[l_i]$}}
            \lElse{$m_{i}\leftarrow r_{i}$}
        }
    }
    \Return{$\min\limits_{1\le i\le k}A_i[r_i]$};
\end{algorithm}

\begin{lemma}
    Algorithm~\ref{ALG:MHBS} returns the maximum integer $p^*$ such that $F(p^*)\le T$ in $O(\log \sum_{i=1}^k|A_i|)$ time.
\end{lemma}

\ifshowproof

\begin{proof}
For the convenience of the proof, a dummy element $+\infty$ is appended to the end of each sequence, that is, $A_i[|A_i|]=+\infty$ for each $1\le i\le k$.
If $F(|A_1|,\dots,|A_k|)\le T$, the algorithm obviously returns $p^*$.
Then for the case where $F(|A_1|,\dots,|A_k|)> T$, we show that Algorithm~\ref{ALG:MHBS} maintains the invariant
\begin{equation}\label{EQ:INV}
A_i[l_i]\le p^*\le A_i[r_i],\quad \forall\,1\le i\le k,
\end{equation}
and then prove that Algorithm~\ref{ALG:MHBS} correctly returns $p^*$ after at most $O(\log\sum_{i=1}^k|A_i|)$ iterations.

\emph{Base case.}  Initially, for each $1\le i\le k$ we set $l_i=0$ and $r_i=|A_i|$. Since each $A_i$ is sorted,
\begin{equation}
A_i[0]\le\min A_i\le p^*\le\max A_i\le A_i[n],
\end{equation}
then the invariant holds before the first iteration.

\emph{Inductive step.}  Suppose at the start of some iteration we have $A_i[l_i]\le p^*\le A_i[r_i]$ for any $1\le i\le k$.
We aim to demonstrate that the invariant is preserved after the update performed in the current iteration.
Without loss of generality, we assume that for any $1\le i\le k$, $r_i - l_i > 1$ satisfies. (If some $i$ already has $r_i - l_i \le 1$ and the algorithm has not yet terminated, then by the invariant we have $A_i[l_i] < p^* \le A_i[r_i]$ and $N_i(A_i[r_i]) \le N_i(A_i[l_i]+1) = r_i$,
then $N_i(p^*) = r_i = m_i$, and the problem reduces to the remaining $k-1$ sequences.)
In each iteration, the algorithm modifies exactly one of the two bounds: it either updates the lower bound $l_{i_{\min}}$ for some index $i_{\min}$, or updates the upper bound $r_{i_{\max}}$ for some index $i_{\max}$.  We discuss the two cases:

\textbf{Case 1:} $F(m_1,\dots,m_k)\le T$.

Let $p=A_{i_{\min}}[m_{i_{\min}}]=\min_{r_i - l_i > 1} A_i[m_i]$.
Since
\begin{equation}
N_{i_{\min}}(p)
=\bigl|\{x\in A_{i_{\min}}\mid x < A_{i_{\min}}[m_{i_{\min}}]\}\bigr|
\le m_{i_{\min}},
\end{equation}
and for each $i\neq i_{\min}$,
\begin{equation}
N_i(p)
\le N_i\bigl(A_i[m_i]\bigr)
=\bigl|\{x\in A_i\mid x < A_i[m_i]\}\bigr|
\le m_i,
\end{equation}
it follows that
\begin{equation}
F\bigl(N_1(p),\dots,N_k(p)\bigr)
\le F(m_1,\dots,m_k)\le T.
\end{equation}
Hence $p^*\ge p$, then after updating $l_{i_{\min}}\leftarrow m_{i_{\min}}$, we still have $A_{i_{\min}}[l_{i_{\min}}]\le p^*\le A_{i_{\min}}[r_{i_{\min}}]$.
For all $i\neq i_{\min}$, neither $l_i$ nor $r_i$ changes, so the invariant is preserved after the update.

\textbf{Case 2:} $F(m_1,\dots,m_k)> T$.

Let $p=A_{i_{\max}}[m_{i_{\max}}]=\max_{r_i - l_i > 1} A_i[m_i]$.
Since
\begin{equation}
    N_{i_{\max}}(p+1)=|\{x\in A_{i_{\max}}|x\le A_{i_{\max}}[m_{i_{\max}}]\}|\ge m_{i_{\max}},
\end{equation}
and for each $i\neq i_{\min}$,
\begin{equation}
    N_i(p+1)\ge N_i(A_i[m_i]+1)=|\{x\in A_i|x\le A_i[m_i]\}|\ge m_i,
\end{equation}
it follows that
\begin{equation}
    F(N_1(p+1),\dots,N_k(p+1))\ge F(m_1,\dots,m_k)> T.
\end{equation}
Thus $p^*<p+1$ which implies $p^*\le p$, then after updating $r_{i_{\max}} \leftarrow m_{i_{\max}}$, we still have $A_{i_{\max}}[l_{i_{\max}}]\le p^*\le A_{i_{\max}}[r_{i_{\max}}]$.
For all $i\neq i_{\max}$, neither $l_i$ nor $r_i$ changes, so the invariant is preserved after the update.

\emph{Convergence and termination}.
In each iteration, an update is performed on sequence $A_i$ only if $r_i - l_i > 1$,
and every such update reduces the length of the interval by at least one.
Consequently, the length of each interval $[l_i,r_i]$ shrinks to at most $2$ after at most $O(\log |A_i|)$ updates on $A_i$.
Since the number of sequences is a constant, the total number of iterations of the algorithm is bounded by $O(\log \sum_{i=1}^k|A_i|)$.

Now we show that when Algorithm~\ref{ALG:MHBS} terminates, it returns $p^*$ correctly. If it
 terminates at Line 4 or Line 14, which implies
\begin{equation}
F\bigl(N_1(A_{i}[l_i]+1),\dots,N_k(A_{i}[l_{i}]+1)\bigr) > T,
\end{equation}
it follows that $p^*\le A_{i}[l_i]$, then by the invariant $p^*\ge A_i[l_i]$, we have $p^* = A_i[l_i]$.

If Algorithm~\ref{ALG:MHBS} terminates at line 16, which implies $r_i - l_i \le 1$ and
$F(N_1(A_i[l_i]+1),\dots,N_k(A_i[l_i]+1))\le T$ satisfies for every $1\le i\le k$.
Let $p=\min_{1\le i\le k}A_i[r_i]$ and $q=\max_{1\le i\le k}A_i[l_i]$, then
\begin{equation}
    \begin{aligned}
F(N_1(p),\dots&,N_k(p))\le F(N_1(A_1[r_1]),\dots,N_k(A_k[r_k]))\\
&\le F(N_1(A_1[l_1]+1),\dots,N_k(A_k[l_k]+1))\\
&\le F(N_1(q+1),\dots,N_k(q+1))\le T.
\end{aligned}
\end{equation}
Thus $p^*\ge p$, and by the invariant, $p^*\le p$, we conclude $p^* =p= \min_{1\le i\le k}A_i[r_i]$.


In summary, since $i_{\min}$, $i_{\max}$, and $F$ can be computed in $O(1)$ time, and computing each $N_i$ takes at most $O(\log |A_i|)$ time, Algorithm~\ref{ALG:MHBS} returns $p^*$ in $O(\log\sum_{i=1}^k|A_i|)$ time.
\end{proof}
\fi

Since $\sum_{i=1}^k|A_i|\le\sum_{i=1}^k|R_i|\le |Q|$, the following corollary follows immediately.

\begin{corollary}
    The divide operation on any prefix range filter can be performed in $O(\log |Q|)$ time.
\end{corollary}

\emph{Remarks.} The assumption that all tuples in each relation table are sorted lexicographically is made for analytical convenience and does not limit generality, as other hierarchical indexing structures (such as balanced trees, B-trees, skip lists, and tries) can be supported with minor modifications in a manner similar to that discussed in Section~\ref{SUBSEC:upp}.


Then for any prefix range filter $\psi$, $children(\psi)$ can be calculated in a recursive way in $O(\log|Q|)$ time, as shown in Algorithm~\ref{ALG:CHILDREN}.


\begin{algorithm}
    \caption{$children$}\label{ALG:CHILDREN}
    \LinesNumbered
    \KwIn{$\psi$}
    \KwOut{a list of filters}
    \lIf{$upp(\psi)\le 1$}{\textbf{return} $\emptyset$}
    $res\leftarrow\emptyset$\;
    divide $\psi$ into $\psi_\mathrm{left},\psi_\mathrm{mid},\psi_\mathrm{right}$\;
    \If{$upp(\psi_\mathrm{left})>0$ and $\psi_{\textrm{left}}$ is not empty}{$res\leftarrow res\cup\{\psi_\mathrm{left}\}$}
    \lIf{$upp(\psi_\mathrm{mid})=1$}{$res\leftarrow res\cup\{\psi_\mathrm{mid}\}$}
    \lElse{$res\leftarrow res\cup children(\psi_\mathrm{mid})$}
    \If{$upp(\psi_\mathrm{right})>0$ and $\psi_{\textrm{right}}$ is not empty}{$res\leftarrow res\cup\{\psi_\mathrm{right}\}$}
    \textbf{return} res\;
\end{algorithm}


