\begin{lemma}
    For any prefix range filter $\psi$, let $\psi_{\mathrm{left}}$, $\psi_{\mathrm{mid}}$ and $\psi_{\mathrm{right}}$ denote the three filters obtained by dividing $\psi$, then all non‑empty ranges among these filters are prefix range filters.
\end{lemma}
\ifshowproof
\begin{proof}
    Let $\psi=[[l_1,h_1],\dots,[l_n,h_n]]$, since $s=\min\{i|l_i\neq h_i\}$ is a split position of $\psi$, it follows that
    \begin{enumerate}
        \item $\forall 1\le i<s$, $l_i=h_i$,
        \item $\forall s<i\le n$, $l_i=\min_Q(x_i)$ and $h_i=\max_Q(x_i)$.
    \end{enumerate}
    If $\psi_{\mathrm{left}}$ is not an empty range, then $l_p\le mid_p-1$, which implies that $\psi_{\mathrm{left}}$ is a prefix range filter with split position $s$.
    Similarly, if $\psi_{\mathrm{left}}$ is not an empty range, then $mid_p+1\le h_p$, which implies that $\psi_{\mathrm{right}}$ is a prefix range filter with split position $s$.
    Finally, since $mid_p\le mid_p$, $\psi_{\mathrm{mid}}$ is a prefix range filter with split position $s$.
    % Each of these prefix range filters has at least one split position $s$.
\end{proof}
\fi
Since the filter of the root node, $\psi_r$, is a prefix range filter, we can conclude by induction that

\begin{corollary}
