\textbf{Upper-bound based on acyclic skeleton query.} Any cyclic join query can be transformed into an acyclic one by removing a subset of relations~\cite{Sample2018}.
Specifically, given any cyclic join query $Q$, it can be decomposed into two subqueries, $Q_s$ and $Q_r$, such that $Q=Q_s\Join Q_r$.
Here, $Q_s$ is an acyclic query (referred to as the \emph{skeleton query}) and $Q_r$ is the query consisting of the remaining relations (referred to as the \emph{residual query}).
In Example~\ref{example}, the triangle query $Q_\Delta$ can be decomposed into an acyclic skeleton subquery $Q_{\Delta s}=R(x,y)\Join S(y,z)$ and a residual subquery $Q_{\Delta r}=T(x,z)$.
% When the skeleton query contains all the attributes in the original query (that is, $\mathrm{att}(Q_s) = \mathrm{att}(Q)$), we have $Res(Q)\subseteq Res(Q_s)$.
Based on the above decomposition, following lemma holds:

\begin{lemma}
    For any join query $Q$ and filter $\psi$, if $\mathrm{att}(Q_s) = \mathrm{att}(Q)$, then $|Res(Q|_\psi)|\le |Res(Q_s|_\psi)|$. Otherwise, if $\mathrm{att}(Q_s)\subsetneq\mathrm{att}(Q)$, for any fractional edge cover $c\in EC(G_{Q_r\setminus Q_s})$, $|Res(Q|_\psi)|\le |Res(Q_s|_\psi)|\cdot\mathrm{AGM}_c(Q_r^*|_\psi)$,
    where $Q_r^*=\{R[\mathrm{att}(Q_r)\setminus\mathrm{att}(Q_s)]|R\in Q_r\}$, and for any attribute set $V\subseteq\mathrm{att}(R)$, $R[V]=\{t[V]|t\in R\}$.
\end{lemma}
\ifshowproof
\begin{proof}
    If $\mathrm{att}(Q_s) = \mathrm{att}(Q)$, then $Res(Q|_\psi)\subseteq Res(Q_s|_\psi)$, which implies $|Res(Q|_\psi)|\le |Res(Q_s|_\psi)|$.
    If $\mathrm{att}(Q_s)\subsetneq\mathrm{att}(Q)$, then
    \begin{equation}
        \begin{aligned}
            |Res(Q|_\psi)|&=|Res(Q_s|_\psi)\Join Res(Q_r|_\psi)|\\
            &\le \sum_{t\in Res(Q_s|_\psi)}|Res((Q_r\ltimes t)|_\psi)|\\
            &\le |Res(Q_s|_\psi)|\max_{t\in Res(Q_s|_\psi)}|Res((Q_r\ltimes t)|_\psi)|\\
            &\le |Res(Q_s|_\psi)|\cdot|Res(Q_r^*|_\psi)|\\
            &\le |Res(Q_s|_\psi)|\cdot\mathrm{AGM}_c(Q_r^*|_\psi).
        \end{aligned}
    \end{equation}
\end{proof}
\fi
