\later{
\begin{algorithm}[!ht]

  \caption{$\textsc{Compactify}$(C)}
  \label{alg:Comp}
  \begin{algorithmic}[1]
    \STATE Compute the slice graph of $C$.
    \WHILE{$C$ is not quasi-compact (ignoring slice $z=0$)}  \label{ln:comp-while}
    \STATE Let $R$ be the cluster where the musketeers currently sit. DFS on the slice graph from $R$, preferring upward edges (in the $z$ direction). Let $S$ be the first extremal cluster (with possibly $S=R$).
    \STATE Move the musketeers to $S$.\label{ln:muskToCluster}
    \STATE Lower non-quasi-compact modules in $S$ as in \cref{sec:ap-lower}.\label{ln:lower}
    \STATE Let $M$ be the set of stragglers $\module m$ sorted by $\|\module m\|_1$.\label{ln:straggler-order}
    \FOR{$\module m \in M$}
        \STATE \hyperref[alg:fix]{$\Fix$}($\module m$)\label{ln:cmptx-fixCall}
    \ENDFOR
    \ENDWHILE
    \WHILE{$\exists \module m$ where $\module m+(0,0,-1)$ is empty and $z_{\module m}>0$}\label{ln:compacting-quasi}
    \STATE Slide $\module m$ down\label{ln:slide-m}
    \ENDWHILE
    \IF{$C$ is not compact}
        \STATE Apply the planar version of \textsc{Compactify} on slice $z=0$
    \ENDIF
  \end{algorithmic}
\end{algorithm}
}

