\section{Supporting Lemmas}
\label{app:support_lemma}
% --------------------------------------------------------------------

\begin{lemma}[Bounding the Sum of Double Exponential Function]
\label{lem:theta_double_exp_sum}
    Let $a, b \ge 2$. Then
    \[ \sum_{i=0}^{n} a^{b^i} = \OhTheta{a^{b^n}} \; . \]
\end{lemma}

\begin{proof}
    The proof proceeds by showing the lower and upper bound separately. For the lower bound, as all terms of the sum is positive, then the sum is bounded below by the last term of the sum.
    To show the upper bound, it is shown by induction in $n$ that
    \[ \sum_{i=0}^{n} a^{b^i} \le 2 a^{b^n} \; . \]
    For $n = 0$ the inequality holds, as there is only one term which is equal to $a$.
    \[ \sum_{i=0}^{n} a^{b^i} = \sum_{i=0}^{0} a^{b^i} = a^{b^0} = a \le 2 a = 2 a^{b^0} = 2 a^{b^n} \; .\]
    For the induction step, let $n = n' + 1$, and let the inequality hold by induction for $n'$. Then
    \[ \sum_{i=0}^{n} a^{b^i} = \left( \sum_{i=0}^{n'} a^{b^i} \right) + a^{b^{n' + 1}} \le 2 a^{b^{n'}} + \left(a^{b^{n'}} \right)^b \]
    From here, the goal bound is twice that of the last term in the sum. It can therefore be shown by proving that the second term bounds the first. For simplicity, let $k = a^{b^{n'}}$. Then it holds that
    \[ 2 k \le k^b  \Longleftrightarrow  \log_k ( 2 k ) \le b  \Longleftrightarrow  \log_k (2) + 1 \le b \; . \]
    As $a, b \ge 2$ and $n' \ge 0$, then $\log_k (2) \le 1$, and the above inequality holds. It therefore holds that
    \[ 2 a^{b^{n'}} + \left(a^{b^{n'}} \right)^b \le 2 \left(a^{b^{n'}} \right)^b = 2 a^{b^{n}} \; , \]
    Concluding the proof.
\end{proof}


